const uuid=x=>typeof x==='string'&&/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(x);
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const exact=(x,keys)=>object(x)&&Object.keys(x).length===keys.length&&keys.every(k=>Object.hasOwn(x,k));
const RPC=Object.freeze({next:'mission_generic_dispatch_next_v1',progress:'mission_generic_progress_v1',staffTick:'mission_generic_staff_tick_v1',reject:'mission_generic_dispatch_reject_v1',claim:'mission_generic_dispatch_claim_v1',
  status:'mission_generic_dispatch_status_v1',asyncStatus:'mission_generic_dispatch_async_status_v1',authorize:'mission_generic_dispatch_authorize_v1',
  consume:'mission_generic_dispatch_consume_v1',markSent:'staff_ai_quota_generic_mark_sent_v1',
  finalize:'mission_generic_dispatch_finalize_v1',
  cachedPublication:'mission_generic_staff_republish_failed_v1',
  d100Scope:'mission_factory_quest_d100_wakeup_scope_v1',
  d100Pending:'mission_factory_quest_d100_pending_v1',
  d100Consume:'mission_factory_quest_d100_consume_v1'});

async function bodyOf(req) {
  if (!req.body) throw Error('REQUEST_BODY_REQUIRED');
  const reader=req.body.getReader(),chunks=[];let total=0,timer;
  const expired=new Promise((_,reject)=>{timer=setTimeout(()=>{reader.cancel().catch(()=>{});reject(Error('REQUEST_TIMEOUT'));},10000);});
