 IF (NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE state IN('claimed','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts WHERE status IN('reserved','authorized','provider_started')) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items WHERE master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND state IN('ready','claimed','authorized','provider_started','uncertain'))) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'NPC_EDITORIAL_ACTIVE_WORK' USING ERRCODE='40001';END IF;
