 EXECUTE 'CREATE TABLE mission_narrative_internal.provider_outputs_v1(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 work_id uuid NOT NULL REFERENCES mission_generic_owner.work_items(id),
 authorization_id uuid NOT NULL REFERENCES mission_narrative_internal.provider_authorizations(id),
 dispatch_receipt_id uuid NOT NULL REFERENCES mission_narrative_internal.dispatch_receipts(id),
 dispatch_id uuid NOT NULL,
 raw_output text NOT NULL CHECK(octet_length(raw_output) BETWEEN 1 AND 262144),
 raw_sha256 text NOT NULL CHECK(raw_sha256~''^[a-f0-9]{64}$''),
 provider_status text NOT NULL CHECK(length(provider_status) BETWEEN 1 AND 64),
 provider_response_id text CHECK(length(provider_response_id)<=256),
 provider_request_id text CHECK(length(provider_request_id)<=256),
 usage jsonb NOT NULL CHECK(jsonb_typeof(usage)=''object'' AND octet_length(usage::text)<=8192),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(work_id,authorization_id,dispatch_id),
 CHECK(raw_sha256=encode(extensions.digest(convert_to(raw_output,''UTF8''),''sha256''),''hex''))
);
ALTER TABLE mission_narrative_internal.provider_outputs_v1 OWNER TO postgres;
ALTER TABLE mission_narrative_internal.provider_outputs_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON mission_narrative_internal.provider_outputs_v1 FROM PUBLIC,anon,authenticated,service_role;
COMMENT ON TABLE mission_narrative_internal.provider_outputs_v1 IS ''Private immutable provider output; written only by retention RPC, no client read or update grants.'';
';
 EXECUTE 'CREATE OR REPLACE FUNCTION public.mission_generic_provider_output_retain_v1(p_work uuid,p_finalize_token text,p_raw_output text,p_raw_sha256 text,p_provider_status text,p_provider_response_id text,p_provider_request_id text,p_usage jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''''
AS $function$
DECLARE w mission_generic_owner.work_items;z mission_narrative_internal.provider_authorizations;
 d mission_narrative_internal.dispatch_receipts;r mission_narrative_internal.provider_outputs_v1;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 p_usage:=coalesce(nullif(p_usage,''null''::jsonb),''{}''::jsonb);
 IF p_work IS NULL OR p_finalize_token IS NULL OR p_raw_output IS NULL OR octet_length(p_raw_output) NOT BETWEEN 1 AND 262144
  OR p_raw_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(p_raw_output,''UTF8''),''sha256''),''hex'')
  OR p_provider_status IS NULL OR length(p_provider_status) NOT BETWEEN 1 AND 64
  OR length(p_provider_response_id)>256 OR length(p_provider_request_id)>256
  OR jsonb_typeof(p_usage) IS DISTINCT FROM ''object'' OR octet_length(p_usage::text)>8192
 THEN RAISE EXCEPTION ''MGD_OUTPUT_RETAIN_INPUT'' USING ERRCODE=''22023'';END IF;
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work FOR UPDATE;
 SELECT * INTO STRICT d FROM mission_narrative_internal.dispatch_receipts WHERE id=w.dispatch_receipt_id FOR UPDATE;
 SELECT * INTO STRICT z FROM mission_narrative_internal.provider_authorizations WHERE id=w.authorization_id AND receipt_id=d.id FOR UPDATE;
 IF w.state<>''provider_started'' OR d.status<>''provider_started'' OR w.dispatch_id IS NULL
  OR z.finalize_token_sha256 IS DISTINCT FROM mission_narrative_internal.token_sha(p_finalize_token)
  OR NOT coalesce(mission_public_owner.work_contract_v1(w.id)->''features'' ? ''provider_output_retention_v1'',false)
 THEN RAISE EXCEPTION ''MGD_OUTPUT_RETAIN_AUTHORITY'' USING ERRCODE=''42501'';END IF;
 SELECT * INTO r FROM mission_narrative_internal.provider_outputs_v1 WHERE work_id=w.id AND authorization_id=z.id AND dispatch_id=w.dispatch_id;
 IF FOUND THEN
  IF r.raw_output IS DISTINCT FROM p_raw_output OR r.raw_sha256 IS DISTINCT FROM p_raw_sha256
   OR r.provider_status IS DISTINCT FROM p_provider_status OR r.provider_response_id IS DISTINCT FROM p_provider_response_id
   OR r.provider_request_id IS DISTINCT FROM p_provider_request_id OR r.usage IS DISTINCT FROM p_usage
  THEN RAISE EXCEPTION ''MGD_OUTPUT_RETAIN_CONFLICT'' USING ERRCODE=''40001'';END IF;
 ELSE
  INSERT INTO mission_narrative_internal.provider_outputs_v1(work_id,authorization_id,dispatch_receipt_id,dispatch_id,raw_output,raw_sha256,provider_status,provider_response_id,provider_request_id,usage)
  VALUES(w.id,z.id,d.id,w.dispatch_id,p_raw_output,p_raw_sha256,p_provider_status,p_provider_response_id,p_provider_request_id,p_usage) RETURNING * INTO r;
 END IF;
 RETURN jsonb_build_object(''schema_version'',''mission-provider-output-receipt/1'',''work_id'',w.id,''dispatch_id'',w.dispatch_id,''output_receipt_id'',r.id,''raw_sha256'',r.raw_sha256);
END;
$function$;
ALTER FUNCTION public.mission_generic_provider_output_retain_v1(uuid,text,text,text,text,text,text,jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.mission_generic_provider_output_retain_v1(uuid,text,text,text,text,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mission_generic_provider_output_retain_v1(uuid,text,text,text,text,text,text,jsonb) TO service_role;
';
 EXECUTE 'CREATE OR REPLACE FUNCTION mission_generic_owner.role_source_released_v4(p_source uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
DECLARE source_row mission_generic_owner.unified_source_windows%ROWTYPE;
        stale_work uuid;
BEGIN
  IF p_source IS NULL THEN RETURN false; END IF;
  SELECT * INTO source_row FROM mission_generic_owner.unified_source_windows
    WHERE id=p_source;
  IF NOT FOUND OR source_row.superseded_at IS NULL
    OR source_row.consumed_message_id IS NOT NULL
    OR source_row.superseded_reason IS NULL
    OR source_row.superseded_reason NOT IN
      (''new_role_before_provider'',''role_revision_changed'',''staff_failed_director_validation_retry'',''staff_preprovider_request_retry'',''staff_unpublished_reinterpretation'')
  THEN RETURN false; END IF;
  IF EXISTS (
    SELECT 1 FROM mission_generic_owner.work_items wi
    WHERE (wi.id=source_row.work_id OR wi.id IN (
      SELECT batch.writer_work_id FROM mission_generic_owner.unified_batches batch
      WHERE batch.source_window_id=p_source AND batch.writer_work_id IS NOT NULL))
    AND wi.state NOT IN (''completed'',''failed'')
  ) THEN RETURN false; END IF;
  IF source_row.superseded_reason=''staff_unpublished_reinterpretation'' THEN RETURN source_row.id=''433ace05-5265-4aad-96a3-5567b6e3480a''::uuid AND source_row.master_session_id=''44078c5f-7001-4129-9506-e2f34e68c8ac''::uuid AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit ar
 JOIN mission_generic_owner.work_items od ON od.dispatch_receipt_id=ar.receipt_id AND od.id=''433ace05-5265-4aad-96a3-5567b6e3480a''::uuid AND od.kind=''director'' AND od.state=''completed'' AND od.message_id IS NULL
 JOIN mission_generic_owner.unified_batches ob ON ob.decision_work_id=od.id AND ob.source_window_id=od.id AND ob.writer_work_id=''310493d3-92d2-4645-ba85-ab42f57dbf9d''::uuid AND ob.state=''ready'' AND ob.message_id IS NULL AND ob.encounter_id IS NULL AND ob.next_round_id IS NULL
 JOIN mission_generic_owner.work_items ow ON ow.id=ob.writer_work_id AND ow.state=''failed'' AND ow.message_id IS NULL
 WHERE ar.event_code=''staff_unpublished_reinterpretation'' AND ar.details->>''schema_version''=''mission-unpublished-reinterpretation/1''
 AND ar.details->>''master_session_id''=''44078c5f-7001-4129-9506-e2f34e68c8ac'' AND ar.details->>''source_window_id''=''433ace05-5265-4aad-96a3-5567b6e3480a'' AND ar.details->>''source_revision''=''ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb''
 AND ar.details->>''director_result_sha256''=od.result_sha256 AND ar.details->>''writer_result_sha256''=ow.result_sha256
 AND ar.details->>''successor_progress_key''=(mission_ai_service_owner.uuid5(''310493d3-92d2-4645-ba85-ab42f57dbf9d''::uuid,''mission-staff-unpublished-reinterpretation/1:ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb''))::text
 AND ar.details->>''old_work_preserved''=''true'' AND ar.details->>''generation_http_calls''=''0'');END IF;
  IF source_row.superseded_reason=''staff_preprovider_request_retry'' AND source_row.id=''f4f7185e-4aae-4edd-ac24-65f8dcfa36f5''::uuid THEN
    RETURN source_row.id=''f4f7185e-4aae-4edd-ac24-65f8dcfa36f5''::uuid
      AND source_row.work_id=source_row.id
      AND source_row.master_session_id=''44078c5f-7001-4129-9506-e2f34e68c8ac''::uuid
      AND source_row.role_ids=ARRAY[''cc335f44-c921-4b63-931d-464a59592db2''::uuid,''458c16cc-e747-49f7-9303-c81dd43cfb82''::uuid]
      AND source_row.source_sha256=''8cf6e4054d88029a6a6842e43c5e14ba90821bb91f57ef9772d2b7fdbd2421f0''
      AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items wi
        JOIN mission_narrative_internal.dispatch_receipts receipt ON receipt.id=wi.dispatch_receipt_id
        JOIN mission_public_owner.work_contracts_v1 wc ON wc.work_id=wi.id
        WHERE wi.id=source_row.work_id AND wi.master_session_id=source_row.master_session_id
          AND wi.authority_receipt_id=source_row.id AND wi.kind=''director'' AND wi.state=''failed''
          AND wi.finalized_at IS NOT NULL AND wi.message_id IS NULL
          AND wi.authorization_id IS NULL AND wi.dispatch_id IS NULL
          AND wi.payload_sha256=source_row.source_sha256
          AND wi.payload_sha256=public.combat_v2_sha256(wi.payload)
          AND wi.result_sha256=''87bc26c0db289a827c5f27e8801ea4afe9b3900119428a0689a8b78c09106584''
          AND wi.result_sha256=public.combat_v2_sha256(wi.result)
          AND wi.result->>''schema_version''=''mission-generic-pre-provider-failure/1''
          AND wi.result->>''failure_code''=''request_validation_failed''
          AND wi.result->''provider_calls''=''0''::jsonb AND wi.result->''charged_cost_usd''=''0''::jsonb
          AND receipt.id=''dab8f917-28cf-44a4-87d7-5f471ca37060''::uuid
          AND receipt.master_session_id=wi.master_session_id AND receipt.authority_receipt_id=wi.id
          AND receipt.request_key=wi.request_key AND receipt.status=''failed''
          AND receipt.dispatch_count=0 AND receipt.charged_cost_usd=0 AND receipt.upper_bound_cost_usd=0
          AND receipt.finalized_at IS NOT NULL
          AND wc.master_session_id=wi.master_session_id
          AND wc.contract_sha256=''d961a10e2e5b8764f932149b80d256da707eb8912ea030c9e4a21d94093fa8b2''
          AND wc.contract_sha256=public.combat_v2_sha256(wc.contract)
          AND wc.release_sha256=''9aa56885e78b9f7f3cf18f06314e909ed32831c9d7327bad7f0f07ee3c31bd11''
