CREATE TABLE mission_narrative_internal.provider_outputs_v1(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 work_id uuid NOT NULL REFERENCES mission_generic_owner.work_items(id),
 authorization_id uuid NOT NULL REFERENCES mission_narrative_internal.provider_authorizations(id),
 dispatch_receipt_id uuid NOT NULL REFERENCES mission_narrative_internal.dispatch_receipts(id),
 dispatch_id uuid NOT NULL,
 raw_output text NOT NULL CHECK(octet_length(raw_output) BETWEEN 1 AND 262144),
 raw_sha256 text NOT NULL CHECK(raw_sha256~'^[a-f0-9]{64}$'),
 provider_status text NOT NULL CHECK(length(provider_status) BETWEEN 1 AND 64),
 provider_response_id text CHECK(length(provider_response_id)<=256),
 provider_request_id text CHECK(length(provider_request_id)<=256),
 usage jsonb NOT NULL CHECK(jsonb_typeof(usage)='object' AND octet_length(usage::text)<=8192),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(work_id,authorization_id,dispatch_id),
 CHECK(raw_sha256=encode(extensions.digest(convert_to(raw_output,'UTF8'),'sha256'),'hex'))
);
ALTER TABLE mission_narrative_internal.provider_outputs_v1 OWNER TO postgres;
ALTER TABLE mission_narrative_internal.provider_outputs_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON mission_narrative_internal.provider_outputs_v1 FROM PUBLIC,anon,authenticated,service_role;
COMMENT ON TABLE mission_narrative_internal.provider_outputs_v1 IS 'Private immutable provider output; written only by retention RPC, no client read or update grants.';

CREATE OR REPLACE FUNCTION public.mission_generic_staff_republish_failed_v1(p_session uuid, p_work uuid, p_staff uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  w mission_generic_owner.work_items;
  b mission_generic_owner.unified_batches;
  source_row mission_generic_owner.unified_source_windows;
  m public.master_v2_sessions;
  run_row public.mission_run_state;
  receipt mission_narrative_internal.dispatch_receipts;
  result_row jsonb;
  error_state text;
  error_message text;
  error_constraint text;
  error_table text;
  error_schema text;
  safe_code text;
  message_ref uuid;
  factory_cached boolean:=false;
  diagnostic_column text;
  diagnostic_context text;
  diagnostic_frames jsonb;
  successor mission_generic_owner.work_items;
  successor_id uuid;
  successor_event uuid;
  successor_key uuid; old_director mission_generic_owner.work_items; recovery_progress mission_generic_owner.progress_receipts; recovery_root jsonb;
begin
