  OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts d JOIN mission_narrative_internal.dispatch_audit a ON a.receipt_id=d.id AND a.event_code='generic_count_overflow_terminal'
   WHERE d.id=w.dispatch_receipt_id AND d.status='failed' AND d.dispatch_count=0 AND d.charged_cost_usd=0 AND d.finalized_at IS NOT NULL
   AND a.details->>'work_id'=w.id::text AND a.details->>'receipt_id'=w.receipt_id::text AND a.details->>'result_sha256'=w.result_sha256 AND a.details->>'payload_sha256'=w.payload_sha256)
  THEN RAISE EXCEPTION 'C889_RECOVERY_BINDING' USING ERRCODE='40001';END IF;
  INSERT INTO mission_generic_owner.work_items(id,master_session_id,event_id,request_key,dedupe_key,step_key,run_control_version,definition_sha256,encounter_id,authority_receipt_id,kind,revision,payload,payload_sha256)
  VALUES(successor_id,p_session,successor_event,successor_key,'c889-count-reissue:'||w.id::text,w.step_key,w.run_control_version,w.definition_sha256,w.encounter_id,b.id,'narration',w.revision,w.payload,w.payload_sha256) RETURNING * INTO successor;
  UPDATE mission_generic_owner.unified_batches SET writer_work_id=successor_id WHERE id=b.id AND writer_work_id=w.id;
  IF NOT FOUND THEN RAISE EXCEPTION 'C889_WRITER_CAS' USING ERRCODE='40001';END IF;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(w.dispatch_receipt_id,'c889_count_narration_reissued',jsonb_build_object('schema_version','c889-native-report-reissue/1','old_work_id',w.id,'work_id',successor_id,'batch_id',b.id,'payload_sha256',w.payload_sha256,'generation_http_calls',0));
  RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor_id,'replayed',false);
 END IF;
  if p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid
    and p_work='42341080-7f78-494e-9adf-85de7cfce038'::uuid and exists(
    select 1 from mission_generic_owner.work_items ow where ow.id=p_work and ow.master_session_id=p_session
      and ow.kind='narration' and ow.state='failed'
      and ow.result->>'schema_version'='mission-count-overflow-failure/1') then
    perform mission_generic_owner.dispatch_user(p_session,p_staff);
    if p_staff not in('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)
    or m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid or m.owner_kind<>'ai_service'
    or m.closed_at is not null or m.suspended_at is not null
    or not exists(select 1 from public.profiles where id=p_staff and role in('admin','master'))
    or mission_generic_owner.c726_factory_staff_runtime_v1(p_session) is distinct from true
    or mission_staff_abort_private.quiescent_v1(p_session) is distinct from true
    or (mission_generic_owner.c7_run_budget_v1(p_session,true,null)->>'allowed') is distinct from 'true'
    then raise exception 'MCR_COUNT_SCOPE' using errcode='42501';end if;
    perform 1 from mission_generic_owner.role_window_cursors where master_session_id=p_session for update;
    if not found then raise exception 'MCR_CURSOR_MISSING' using errcode='55000';end if;
    perform 1 from public.master_v2_sessions where id=p_session for update;
    select * into strict w from mission_generic_owner.work_items where id=p_work and master_session_id=p_session for update;
    if w.payload_sha256<>public.combat_v2_sha256(w.payload) or w.result_sha256<>public.combat_v2_sha256(w.result)
    or w.authorization_id is not null or w.dispatch_id is not null or w.message_id is not null
    or w.finalized_at is null or w.receipt_id is null or w.result->>'provider_calls'<>'0'
    or w.result->>'outcome_uncertain'<>'false' or w.result->>'failure_code'<>'MISSION_INPUT_COUNT_OVERFLOW'
    or not exists(select 1 from mission_narrative_internal.dispatch_receipts d
       join mission_narrative_internal.dispatch_audit a on a.receipt_id=d.id and a.event_code='generic_count_overflow_terminal'
       where d.id=w.dispatch_receipt_id and d.authority_receipt_id=w.id and d.master_session_id=p_session
        and d.status='failed' and d.dispatch_count=0 and d.finalized_at is not null and d.charged_cost_usd=0
        and a.details->>'work_id'=w.id::text and a.details->>'receipt_id'=w.receipt_id::text
        and a.details->>'payload_sha256'=w.payload_sha256 and a.details->>'result_sha256'=w.result_sha256
        and a.details->>'generation_http_calls'='0')
    then raise exception 'MCR_COUNT_PROOF' using errcode='40001';end if;
    select * into strict b from mission_generic_owner.unified_batches where id=w.authority_receipt_id and master_session_id=p_session for update;
    select * into strict source_row from mission_generic_owner.unified_source_windows where id=b.source_window_id and master_session_id=p_session for update;
    select * into strict run_row from public.mission_run_state where master_session_id=p_session for update;
    successor_id:=md5('C1264:NARRATION:work:'||w.id::text)::uuid;
    successor_event:=md5('C1264:NARRATION:event:'||w.id::text)::uuid;
    successor_key:=md5('C1264:NARRATION:request:'||w.id::text)::uuid;
    if b.state<>'ready' or b.message_id is not null or source_row.superseded_at is not null or source_row.consumed_message_id is not null
    or b.payload is distinct from w.payload or b.payload_sha256<>w.payload_sha256
    or b.step_key<>w.step_key or b.run_control_version<>w.run_control_version
    or run_row.current_step_key<>w.step_key or run_row.control_version<>w.run_control_version or run_row.run_phase<>'in_corso'
    or w.payload->>'source_revision' is distinct from mission_generic_owner.role_source_revision_v1(p_session)
    or w.payload#>>'{publication_barrier,closed}' is distinct from 'true'
    or w.payload#>'{publication_barrier,required_receipt_ids}' is distinct from w.payload#>'{publication_barrier,receipt_ids}'
    or (w.payload#>'{publication_barrier,receipt_ids}' @> jsonb_build_array(b.id)) is distinct from true
    or exists(select 1 from mission_generic_owner.unified_segment_publications_v4 where work_id=w.id)
    or not exists(select 1 from mission_generic_owner.work_items dw where dw.id=b.decision_work_id and dw.kind='director'
      and dw.state='completed' and dw.result->>'ok'='true' and dw.result->'decision'=b.decision
      and b.decision_sha256=public.combat_v2_sha256(b.decision) and source_row.work_id=dw.id
      and source_row.source_sha256=dw.payload_sha256 and source_row.definition_sha256=w.definition_sha256)
    then raise exception 'MCR_COUNT_SOURCE_CHANGED' using errcode='40001';end if;
    if b.writer_work_id=successor_id then
      select * into strict successor from mission_generic_owner.work_items where id=successor_id;
      if successor.master_session_id<>p_session or successor.authority_receipt_id<>b.id or successor.kind<>'narration'
      or successor.event_id<>successor_event or successor.request_key<>successor_key
      or successor.payload is distinct from w.payload or successor.payload_sha256<>w.payload_sha256
      then raise exception 'MCR_COUNT_REPLAY_CHANGED' using errcode='40001';end if;
      return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',true);
    end if;
    if b.writer_work_id<>w.id then raise exception 'MCR_COUNT_WRITER_CHANGED' using errcode='40001';end if;
    insert into mission_generic_owner.work_items(id,master_session_id,event_id,request_key,dedupe_key,step_key,run_control_version,definition_sha256,encounter_id,authority_receipt_id,kind,revision,payload,payload_sha256)
    values(successor_id,p_session,successor_event,successor_key,'count-narration-reissue:'||w.id::text,w.step_key,w.run_control_version,w.definition_sha256,w.encounter_id,b.id,'narration',w.revision,w.payload,w.payload_sha256) returning * into successor;
    update mission_generic_owner.unified_batches set writer_work_id=successor.id where id=b.id and writer_work_id=w.id;
    if not found then raise exception 'MCR_COUNT_WRITER_CAS' using errcode='40001';end if;
    insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) values(w.dispatch_receipt_id,'generic_count_narration_reissued',jsonb_build_object('schema_version','c1264-count-narration-reissue/1','old_work_id',w.id,'work_id',successor.id,'batch_id',b.id,'source_window_id',b.source_window_id,'payload_sha256',w.payload_sha256,'actor_user',p_staff,'generation_http_calls',0));
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',false);
  end if;

  factory_cached:=p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid
   and p_work='86e5b361-9d82-aee8-a840-b09a83126fc0'::uuid
   and p_staff in('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)
   and mission_generic_owner.c726_factory_staff_runtime_v1(p_session) is true
   and (select count(*) from public.master_v2_participants where session_id=p_session and engagement_state='attivo' and left_at is null)=2
   and not exists(select 1 from public.master_v2_participants mp join public.characters ch on ch.id=mp.character_id
     where mp.session_id=p_session and mp.engagement_state='attivo' and mp.left_at is null
      and (ch.user_id is distinct from mp.user_id_snapshot or ch.user_id not in('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)))
   and exists(select 1 from mission_generic_owner.run_bindings rb where rb.master_session_id=p_session
     and rb.snapshot_sha256='49817335c60ce9d4b47bc5d81c6950f622635c7fb232264ab54736349124f567'
     and rb.snapshot_sha256=mission_internal.fingerprint(rb.snapshot));
  if factory_cached then perform mission_generic_owner.dispatch_user(p_session,p_staff);end if;
  if m.location_id is distinct from '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
    or m.owner_kind <> 'ai_service' or m.closed_at is not null
    or not (mission_academy_owner.staff_carrier_runtime(p_session) or factory_cached)
    or not mission_generic_owner.flow_scope_enabled(p_session)
    or not exists(select 1 from public.profiles where id=p_staff and role in ('admin','master'))
    or combat_consumer_private.staff_test_allowed(m.location_id,array[p_staff],false) is distinct from true
  then raise exception 'MCR_STAFF_SCOPE' using errcode='42501'; end if;

  perform 1 from mission_generic_owner.role_window_cursors
    where master_session_id=p_session for update;
  if not found then raise exception 'MCR_CURSOR_MISSING' using errcode='55000'; end if;
  perform 1 from public.master_v2_sessions where id=p_session for update;
  select * into strict w from mission_generic_owner.work_items
    where id=p_work and master_session_id=p_session for update;
  if w.state='completed' and w.message_id is not null and exists(
    select 1 from mission_generic_owner.unified_segment_publications_v4
    where work_id=w.id and message_id=w.message_id) then
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
      'status','published','message_id',w.message_id,'replayed',true);
  end if;
  if w.kind<>'narration' or w.payload->>'schema_version'<>'mission-generic-narration/4'
    or w.state<>'failed' or w.result->>'ok'<>'true'
    or w.result->>'provider_calls'<>'1' or w.result->>'outcome_uncertain'<>'false'
    or w.result_sha256 !~ '^[0-9a-f]{64}$' or w.message_id is not null
  then return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
    'status','not_applicable'); end if;
  select * into strict b from mission_generic_owner.unified_batches
    where id=w.authority_receipt_id and master_session_id=p_session and writer_work_id=w.id for update;
  select * into strict source_row from mission_generic_owner.unified_source_windows
    where id=b.source_window_id and master_session_id=p_session for update;
  select * into strict run_row from public.mission_run_state
    where master_session_id=p_session for update;
  select * into strict receipt from mission_narrative_internal.dispatch_receipts
    where id=w.dispatch_receipt_id for share;
  if b.state<>'ready' or b.message_id is not null
    or source_row.superseded_at is not null or source_row.consumed_message_id is not null
    or run_row.run_phase<>'in_corso' or run_row.current_step_key<>w.step_key
    or run_row.control_version<>w.run_control_version
    or w.payload->>'source_revision' is distinct from mission_generic_owner.role_source_revision_v1(p_session)
    or w.payload is distinct from b.payload or w.payload_sha256<>b.payload_sha256
    or w.result->>'work_id' is distinct from w.id::text
    or w.result->>'master_session_id' is distinct from p_session::text
    or w.result->>'request_key' is distinct from w.request_key::text
    or w.result->>'payload_sha256' is distinct from w.payload_sha256
    or receipt.status<>'success' or receipt.finalized_at is null
    or receipt.charged_cost_usd is null
    or exists(select 1 from mission_generic_owner.unified_segment_publications_v4
      where work_id=w.id)
  then raise exception 'MCR_SOURCE_CHANGED' using errcode='40001'; end if;

  if factory_cached and not exists(
   select 1 from mission_narrative_internal.dispatch_receipts nd
   join mission_narrative_internal.dispatch_audit ga on ga.receipt_id=nd.id and ga.event_code='generic_finalized'
   join mission_narrative_internal.dispatch_audit cp on cp.receipt_id=nd.id and cp.event_code='c8_count_success'
   join mission_narrative_internal.provider_authorizations pa on pa.id=w.authorization_id and pa.receipt_id=nd.id
   join mission_narrative_internal.dispatch_attempts na on na.receipt_id=nd.id and na.id=pa.attempt_id
   join staff_ai_quota_private.calls qc on qc.source_id=nd.id and qc.producer='mission_generic_ai' and qc.call_no=1
   where nd.id=w.dispatch_receipt_id and nd.authority_receipt_id=w.id and nd.master_session_id=p_session
    and nd.request_key=w.request_key and nd.status='success' and nd.dispatch_count=1 and nd.finalized_at is not null
    and nd.charged_cost_usd is not null and nd.lease_token_sha256 is null and nd.lease_expires_at is null
    and na.status='success' and na.finalized_at is not null and na.cost_basis='exact'
    and na.actual_cost_usd=nd.charged_cost_usd and qc.scope_id=p_session and qc.state='settled' and qc.charged_usd=nd.charged_cost_usd
    and ga.details->>'work_id'=w.id::text and ga.details->>'receipt_id'=w.receipt_id::text
    and ga.details->>'state'='failed' and ga.details->>'outcome_uncertain'='false'
    and ga.details->>'application_error_sqlstate'='42703'
    and ga.details->>'result_sha256'=w.result_sha256
    and ga.details->>'result_jsonb_sha256'=public.combat_v2_sha256(w.result)
    and cp.details->>'work_id'=w.id::text and cp.details->>'state'='success'
    and cp.details->>'generation_allowed'='true' and cp.details->>'input_tokens'='10066'
    and cp.details->>'max_input_tokens'='12000'
    and w.authority_receipt_id='08512119-3bfd-4df7-adbc-0686f5edf5b7'::uuid
    and w.definition_sha256='49817335c60ce9d4b47bc5d81c6950f622635c7fb232264ab54736349124f567'
    and w.result->>'schema_version'='mission-generic-result/2' and jsonb_typeof(w.result->'segments')='array'
    and w.result->'text'='null'::jsonb
    and not exists(select 1 from mission_generic_owner.work_items other where other.master_session_id=p_session and other.state in('claimed','authorized','provider_started','uncertain'))
    and not exists(select 1 from mission_narrative_internal.dispatch_attempts pending join mission_narrative_internal.dispatch_receipts pd on pd.id=pending.receipt_id where pd.master_session_id=p_session and pending.finalized_at is null)
  ) then raise exception 'MCR_FACTORY_CACHED_RECEIPT' using errcode='40001';end if;
  perform mission_generic_owner.work_assert(w);

  begin
    update mission_generic_owner.work_items set state='provider_started',finalized_at=null
      where id=w.id and state='failed';
    result_row:=mission_generic_owner.unified_publish_v4(
      w.id,w.result,w.request_key,w.result_sha256);
    message_ref:=(result_row->>'message_id')::uuid;
    if message_ref is null then raise exception 'MCR_PUBLICATION_MISSING'; end if;
    update mission_generic_owner.work_items
      set state='completed',finalized_at=clock_timestamp(),message_id=message_ref,
        result=result||jsonb_build_object('text',result_row->>'text','continuity',result_row->'continuity'),
        result_sha256=public.combat_v2_sha256(result||jsonb_build_object(
          'text',result_row->>'text','continuity',result_row->'continuity'))
      where id=w.id and state='provider_started';
    if not found then raise exception 'MCR_WORK_CAS'; end if;
  exception when others then
    get stacked diagnostics error_state=returned_sqlstate,error_message=message_text,
      error_constraint=constraint_name,error_table=table_name,error_schema=schema_name,
      diagnostic_column=column_name,diagnostic_context=pg_exception_context;
    if factory_cached then
      if diagnostic_column !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then diagnostic_column:=null;end if;
      if diagnostic_column is null and error_state='42703' then
        diagnostic_column:=coalesce(
          substring(error_message from '^column "([A-Za-z_][A-Za-z0-9_]{0,62})" does not exist$'),
          substring(error_message from '^record "[A-Za-z_][A-Za-z0-9_]{0,62}" has no field "([A-Za-z_][A-Za-z0-9_]{0,62})"$'),
          substring(error_message from '^column [A-Za-z_][A-Za-z0-9_]{0,62}\.([A-Za-z_][A-Za-z0-9_]{0,62}) does not exist$'));
      end if;
      if error_table !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then error_table:=null;end if;
      if error_schema !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then error_schema:=null;end if;
      select coalesce(jsonb_agg(jsonb_build_object('function',parts[1],'line',parts[2]::integer) order by ordinal),'[]'::jsonb) into diagnostic_frames
        from (select parts,ordinal from regexp_matches(diagnostic_context,'PL/pgSQL function ([A-Za-z_][A-Za-z0-9_.]*)\([^)]*\) line ([0-9]{1,6})','g') with ordinality f(parts,ordinal) limit 8) frames;
    end if;
    safe_code:=case when error_message ~ '^[A-Z][A-Z0-9_]{1,79}$'
      then error_message else 'SQLSTATE_'||error_state end;
  end;
  if safe_code is not null then
    insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
      values(receipt.id,'staff_cached_publication_rejected',jsonb_build_object(
        'work_id',w.id,'master_session_id',p_session,
        'sqlstate',error_state,'error_code',safe_code,
        'constraint_name',nullif(error_constraint,''),
        'table_name',nullif(error_table,''),
        'schema_name',nullif(error_schema,'')) || case when factory_cached then jsonb_build_object('private_diagnostics',jsonb_build_object('schema_version','c1264-cached-private-error/1','column',diagnostic_column,'table',error_table,'schema',error_schema,'frames',diagnostic_frames)) else '{}'::jsonb end);
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
      'status','failed','error_code',safe_code);
  end if;
  insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
    values(receipt.id,'staff_cached_publication_completed',jsonb_build_object(
      'work_id',w.id,'master_session_id',p_session,'message_id',message_ref));
  return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
    'status','published','message_id',message_ref,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.mission_generic_provider_output_retain_v1(p_work uuid,p_finalize_token text,p_raw_output text,p_raw_sha256 text,p_provider_status text,p_provider_response_id text,p_provider_request_id text,p_usage jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $function$
DECLARE w mission_generic_owner.work_items;z mission_narrative_internal.provider_authorizations;
 d mission_narrative_internal.dispatch_receipts;r mission_narrative_internal.provider_outputs_v1;
BEGIN
 PERFORM mission_ai_board_owner.service_only();
 p_usage:=coalesce(nullif(p_usage,'null'::jsonb),'{}'::jsonb);
 IF p_work IS NULL OR p_finalize_token IS NULL OR p_raw_output IS NULL OR octet_length(p_raw_output) NOT BETWEEN 1 AND 262144
  OR p_raw_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(p_raw_output,'UTF8'),'sha256'),'hex')
  OR p_provider_status IS NULL OR length(p_provider_status) NOT BETWEEN 1 AND 64
  OR length(p_provider_response_id)>256 OR length(p_provider_request_id)>256
  OR jsonb_typeof(p_usage) IS DISTINCT FROM 'object' OR octet_length(p_usage::text)>8192
 THEN RAISE EXCEPTION 'MGD_OUTPUT_RETAIN_INPUT' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work FOR UPDATE;
 SELECT * INTO STRICT d FROM mission_narrative_internal.dispatch_receipts WHERE id=w.dispatch_receipt_id FOR UPDATE;
 SELECT * INTO STRICT z FROM mission_narrative_internal.provider_authorizations WHERE id=w.authorization_id AND receipt_id=d.id FOR UPDATE;
 IF w.state<>'provider_started' OR d.status<>'provider_started' OR w.dispatch_id IS NULL
  OR z.finalize_token_sha256 IS DISTINCT FROM mission_narrative_internal.token_sha(p_finalize_token)
  OR NOT coalesce(mission_public_owner.work_contract_v1(w.id)->'features' ? 'provider_output_retention_v1',false)
 THEN RAISE EXCEPTION 'MGD_OUTPUT_RETAIN_AUTHORITY' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM mission_narrative_internal.provider_outputs_v1 WHERE work_id=w.id AND authorization_id=z.id AND dispatch_id=w.dispatch_id;
 IF FOUND THEN
  IF r.raw_output IS DISTINCT FROM p_raw_output OR r.raw_sha256 IS DISTINCT FROM p_raw_sha256
   OR r.provider_status IS DISTINCT FROM p_provider_status OR r.provider_response_id IS DISTINCT FROM p_provider_response_id
   OR r.provider_request_id IS DISTINCT FROM p_provider_request_id OR r.usage IS DISTINCT FROM p_usage
  THEN RAISE EXCEPTION 'MGD_OUTPUT_RETAIN_CONFLICT' USING ERRCODE='40001';END IF;
 ELSE
  INSERT INTO mission_narrative_internal.provider_outputs_v1(work_id,authorization_id,dispatch_receipt_id,dispatch_id,raw_output,raw_sha256,provider_status,provider_response_id,provider_request_id,usage)
  VALUES(w.id,z.id,d.id,w.dispatch_id,p_raw_output,p_raw_sha256,p_provider_status,p_provider_response_id,p_provider_request_id,p_usage) RETURNING * INTO r;
 END IF;
 RETURN jsonb_build_object('schema_version','mission-provider-output-receipt/1','work_id',w.id,'dispatch_id',w.dispatch_id,'output_receipt_id',r.id,'raw_sha256',r.raw_sha256);
END;
$function$;
ALTER FUNCTION public.mission_generic_provider_output_retain_v1(uuid,text,text,text,text,text,text,jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.mission_generic_provider_output_retain_v1(uuid,text,text,text,text,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mission_generic_provider_output_retain_v1(uuid,text,text,text,text,text,text,jsonb) TO service_role;

CREATE OR REPLACE FUNCTION mission_generic_owner.unified_publish_v4(p_work uuid, p_result jsonb, p_request uuid, p_raw_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ww mission_generic_owner.work_items; ub mission_generic_owner.unified_batches;
        uw mission_generic_owner.unified_source_windows; mm public.master_v2_sessions;
        opp jsonb; part jsonb; body text:=''; txt text; route_result jsonb;
        source_kind text; role_ref uuid; role_actor uuid; role_sha text;
        out jsonb; memory jsonb; anchor jsonb; chain text; body_sha text;
        seg_sha text; msg uuid; pub uuid; tr mission_generic_owner.trigger_receipts;
        combat_open jsonb; offense_receipts jsonb; sealed_receipts jsonb;
        slot_count integer; prose_chars integer:=0; seen_slots text[]:='{}'::text[];
        slot_key text; slot_text text; offense_round uuid;
        ev public.mission_run_events; ob public.mission_run_outbox;
        literal_recovery boolean:=false; free_prose boolean:=false;
BEGIN
  -- Named SQL maintenance authority: real postgres connection, no JWT impersonation.
  -- No client entry point, no retry state, no provider call.
  literal_recovery:=session_user='postgres' AND auth.uid() IS NULL
    AND coalesce(auth.role(),'')='' AND p_work='8da0b3ea-3de5-4f1c-9cf9-740b54a33647'::uuid;
  IF NOT literal_recovery THEN PERFORM mission_ai_board_owner.service_only(); END IF;
  -- Caller finalizer MUST hold role cursor before Master/work; this lock is
  -- reentrant and verifies the same role revision under serialization.
  PERFORM 1 FROM mission_generic_owner.role_window_cursors
    WHERE master_session_id=(SELECT master_session_id FROM mission_generic_owner.work_items WHERE id=p_work)
    FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MRS_V4_CURSOR_MISSING'; END IF;
  SELECT * INTO STRICT mm FROM public.master_v2_sessions
    WHERE id=(SELECT master_session_id FROM mission_generic_owner.work_items WHERE id=p_work)
    FOR UPDATE;
  SELECT * INTO STRICT ww FROM mission_generic_owner.work_items WHERE id=p_work FOR UPDATE;
 IF mission_generic_owner.c1266_opening_named_v1(ww.master_session_id) AND mission_generic_owner.c1266_execution_authority_v1(ww.master_session_id,false,true) IS NULL THEN RAISE EXCEPTION 'C1266_PUBLISH5_CURRENT_AUTHORITY' USING ERRCODE='42501';END IF;
  free_prose:=coalesce(mission_public_owner.work_contract_v1(ww.id)->'features' ? 'free_narrative_v1',false);
  SELECT * INTO STRICT ub FROM mission_generic_owner.unified_batches
    WHERE id=ww.authority_receipt_id AND writer_work_id=ww.id FOR UPDATE;
  SELECT * INTO STRICT uw FROM mission_generic_owner.unified_source_windows
    WHERE id=ub.source_window_id FOR UPDATE;
  IF literal_recovery THEN
    IF (
      ww.id='8da0b3ea-3de5-4f1c-9cf9-740b54a33647'::uuid
      AND ww.master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid
      AND ww.kind='narration' AND ww.state='failed' AND ww.message_id IS NULL
      AND ww.finalized_at IS NOT NULL AND ww.result IS NOT DISTINCT FROM p_result
      AND ww.request_key IS NOT DISTINCT FROM p_request
      AND ww.result_sha256 IS NOT DISTINCT FROM p_raw_sha
      AND p_raw_sha='c540de05a0a5b7c5c3760b951b1d278863a5e13ce74c184f61106890e3cd8564'
      AND public.combat_v2_sha256(ww.result)='514156423647274196abccda69d8f7ac94fee2a949d026526d50027f3f6aba03'
      AND ww.result->>'ok'='true' AND ww.result->>'provider_calls'='1'
      AND ww.result->>'outcome_uncertain'='false'
      AND ww.result->>'work_id'=ww.id::text
      AND ww.result->>'master_session_id'=ww.master_session_id::text
      AND ww.result->>'request_key'=ww.request_key::text
      AND ww.result->>'payload_sha256'=ww.payload_sha256
      AND mm.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
      AND mm.owner_kind='ai_service' AND mm.closed_at IS NULL AND mm.stato='in_corso'
      AND EXISTS(SELECT 1 FROM public.locations l WHERE l.id=mm.location_id AND l.is_test AND l.is_active)
      AND EXISTS(SELECT 1 FROM mission_generic_owner.flow_staff_sessions f WHERE f.master_session_id=ww.master_session_id AND f.enabled)
      AND mission_generic_owner.manual_staff_scope_v1(ww.master_session_id) IS NOT NULL
      AND ub.id='5d54201e-913a-44c8-9d30-7fe776cf63aa'::uuid
      AND ub.master_session_id=ww.master_session_id AND ub.writer_work_id=ww.id
      AND ub.state='ready' AND ub.message_id IS NULL AND ub.route IS NULL
      AND ub.composition_kind='narrative_continuation'
      AND ub.encounter_key IS NULL AND ub.encounter_id IS NULL AND ub.next_round_id IS NULL
      AND ub.source_round_id IS NULL AND ub.entry_side IS NULL
      AND ub.decision->>'action_kind'='context' AND ub.decision->'opportunity_id'='null'::jsonb
      AND ww.payload->'offense_slots'='[]'::jsonb
      AND uw.master_session_id=ww.master_session_id
      AND uw.work_id='f470a88c-3e64-41be-9a1c-a9e627faef9c'::uuid
      AND uw.superseded_at IS NULL AND uw.consumed_message_id IS NULL
      AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items dw WHERE dw.id=uw.work_id
        AND dw.master_session_id=ww.master_session_id AND dw.kind='director' AND dw.state='completed')
      AND EXISTS(SELECT 1 FROM mission_generic_owner.role_window_cursors c WHERE c.master_session_id=ww.master_session_id
        AND c.window_epoch=1 AND c.role_revision=2)
      AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 x WHERE x.work_id=ww.id OR x.batch_id=ub.id)
      AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.staff_fato_revisions x WHERE x.work_id=ww.id)
      AND NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions cs WHERE cs.master_session_id=ww.master_session_id AND cs.closed_at IS NULL)
      AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts dr
        JOIN mission_narrative_internal.dispatch_audit ga ON ga.receipt_id=dr.id AND ga.event_code='generic_finalized'
        WHERE dr.id=ww.dispatch_receipt_id AND dr.authority_receipt_id=ww.id
          AND dr.master_session_id=ww.master_session_id AND dr.request_key=ww.request_key
          AND dr.status='success' AND dr.dispatch_count=1 AND dr.finalized_at IS NOT NULL
          AND dr.charged_cost_usd IS NOT NULL AND dr.lease_token_sha256 IS NULL AND dr.lease_expires_at IS NULL
          AND ga.details->>'work_id'=ww.id::text AND ga.details->>'receipt_id'=ww.receipt_id::text
          AND ga.details->>'state'='failed' AND ga.details->>'stale'='false'
          AND ga.details->>'outcome_uncertain'='false'
          AND ga.details->>'application_error_code'='MG_FATO_LITERAL_REPETITION'
          AND ga.details->>'application_error_sqlstate'='22023'
          AND ga.details->>'result_sha256'=ww.result_sha256
          AND ga.details->>'result_jsonb_sha256'=public.combat_v2_sha256(ww.result))
      AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items other
        WHERE other.master_session_id=ww.master_session_id AND other.id<>ww.id
          AND other.state IN('ready','claimed','authorized','provider_started','uncertain'))
      AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts da
        JOIN mission_narrative_internal.dispatch_receipts dr ON dr.id=da.receipt_id
        WHERE dr.master_session_id=ww.master_session_id AND da.finalized_at IS NULL)
    ) IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'C1266_LITERAL_RECOVERY_BINDING' USING ERRCODE='40001';
    END IF;
  END IF;
  IF ww.payload ? 'role_interpretation' THEN
   PERFORM mission_generic_owner.c1266_role_work_attest_dispatch_v2(ww.id);
   IF ww.payload->'role_interpretation' IS DISTINCT FROM ub.decision->'role_interpretation'
    OR ww.payload->'role_disposition' IS DISTINCT FROM ub.decision->'role_disposition'
    OR ww.payload#>'{role_disposition,effective_opportunity_id}' IS DISTINCT FROM ub.decision->'opportunity_id'
    OR (ww.payload#>>'{role_disposition,status}'='context_fallback' AND
      (ub.decision->>'action_kind'<>'context' OR ub.encounter_key IS NOT NULL OR ub.entry_side IS NOT NULL
       OR jsonb_array_length(ub.decision->'npc_intents')<>0))
   THEN RAISE EXCEPTION 'C1266_ROLE_PUBLISH_DISPOSITION_DRIFT' USING ERRCODE='40001';END IF;
  END IF;
  IF ww.payload->>'schema_version'<>'mission-generic-narration/4'
    OR (ww.state<>'provider_started' AND NOT literal_recovery) OR ww.request_key<>p_request
    OR ww.payload IS DISTINCT FROM ub.payload OR ww.payload_sha256<>ub.payload_sha256
    OR ub.state<>'ready'
    OR ub.source_window_id IS NULL OR uw.superseded_at IS NOT NULL
    OR uw.consumed_message_id IS NOT NULL
    OR ww.payload->>'source_revision' IS DISTINCT FROM mission_generic_owner.role_source_revision_v1(ww.master_session_id)
    OR ww.payload->>'source_revision' IS DISTINCT FROM uw.context->>'source_revision'
    OR p_result->>'schema_version'<>'mission-generic-result/2'
    OR p_result->>'runtime_version'<>'mission-generic-runtime/2'
    OR p_result->'text'<>'null'::jsonb
    OR jsonb_typeof(p_result->'segments')<>'array'
    OR jsonb_array_length(p_result->'segments')=0
    OR jsonb_typeof(ww.payload->'offense_slots')<>'array'
  THEN RAISE EXCEPTION 'MRS_V4_NONOFFENSIVE_BINDING' USING ERRCODE='40001'; END IF;
  slot_count:=jsonb_array_length(ww.payload->'offense_slots');
  IF slot_count>0 AND (ub.composition_kind<>'entry_png' OR ub.encounter_key IS NULL
    OR ub.entry_side<>'png' OR slot_count<>cardinality(ub.selected_actor_keys))
  THEN RAISE EXCEPTION 'MRS_V4_OFFENSE_SCOPE' USING ERRCODE='40001'; END IF;
  -- Validate source and work while run/step still match pre-transition state.
  PERFORM mission_generic_owner.work_assert(ww);
  IF mission_generic_owner.unified_batch_payload(ub.id) IS DISTINCT FROM ww.payload
  THEN RAISE EXCEPTION 'MRS_V4_PAYLOAD_DRIFT' USING ERRCODE='40001'; END IF;
  FOR part IN SELECT value FROM jsonb_array_elements(p_result->'segments') LOOP
    IF NOT mission_generic_owner.keys_valid(part,ARRAY['kind','text','slot_id','actor_key'])
    THEN RAISE EXCEPTION 'MRS_V4_SEGMENT_KEYS'; END IF;
    IF part->>'kind'='prose' THEN
      IF jsonb_typeof(part->'text')<>'string'
        OR part->'slot_id'<>'null'::jsonb OR part->'actor_key'<>'null'::jsonb
      THEN RAISE EXCEPTION 'MRS_V4_PROSE_SEGMENT_INVALID'; END IF;
      txt:=btrim(part->>'text');
      IF txt='' THEN RAISE EXCEPTION 'MRS_V4_EMPTY_SEGMENT'; END IF;
      prose_chars:=prose_chars+length(txt);
    ELSIF part->>'kind'='offense_slot' THEN
      slot_key:=part->>'slot_id';
      IF part->'text'<>'null'::jsonb OR slot_key IS DISTINCT FROM part->>'actor_key'
        OR slot_key !~ '^[a-z][a-z0-9_]{0,63}$'
        OR slot_key=ANY(seen_slots)
        OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ww.payload->'offense_slots') slot
           WHERE slot->>'slot_id'=slot_key AND slot->>'actor_key'=slot_key)
      THEN RAISE EXCEPTION 'MRS_V4_OFFENSE_SEGMENT_INVALID'; END IF;
      seen_slots:=array_append(seen_slots,slot_key);
    ELSE RAISE EXCEPTION 'MRS_V4_SEGMENT_KIND'; END IF;
  END LOOP;
  IF prose_chars<(CASE WHEN free_prose THEN 1 ELSE 500 END) OR cardinality(seen_slots)<>slot_count
    OR seen_slots IS DISTINCT FROM coalesce((SELECT array_agg(slot->>'slot_id' ORDER BY slot->>'actor_key')
      FROM jsonb_array_elements(ww.payload->'offense_slots') slot),'{}'::text[])
  THEN RAISE EXCEPTION 'MRS_V4_SEGMENT_COHORT'; END IF;
  seg_sha:=public.combat_v2_sha256(p_result->'segments');
  anchor:=p_result->'history_anchor'; memory:=p_result->'continuity_draft';
  IF jsonb_typeof(anchor) IS DISTINCT FROM 'object'
    OR jsonb_typeof(memory) IS DISTINCT FROM 'object'
    OR anchor->>'chain_sha256' IS DISTINCT FROM ww.payload#>>'{source_context,history_chain_sha256}'
    OR (anchor->>'count')::bigint IS DISTINCT FROM (ww.payload#>>'{source_context,history_count}')::bigint
    OR NOT mission_generic_owner.keys_valid(memory,ARRAY['state','known','open','used'])
  THEN RAISE EXCEPTION 'MRS_V4_MEMORY_BINDING'; END IF;

  SELECT x INTO opp FROM jsonb_array_elements(uw.opportunities) x
    WHERE x->>'opportunity_id'=ub.decision->>'opportunity_id';
  IF opp IS NULL AND (
      ub.decision->>'opportunity_id' IS NOT NULL
      OR ub.decision->>'action_kind' IS DISTINCT FROM 'context'
      OR ub.composition_kind IS DISTINCT FROM 'narrative_continuation'
      OR ub.encounter_key IS NOT NULL OR ub.entry_side IS NOT NULL
    ) THEN RAISE EXCEPTION 'MRS_V4_OPPORTUNITY_MISSING'; END IF;
  IF opp->>'trigger_key' IS NOT NULL THEN
    source_kind:=opp->>'source_kind';
    IF source_kind='player_choice' THEN
      role_ref:=(ub.decision#>>'{source_evidence,0,role_id}')::uuid;
      SELECT rm.character_id,encode(extensions.digest(convert_to(rm.body,'UTF8'),'sha256'),'hex')
        INTO STRICT role_actor,role_sha FROM public.messages rm
        JOIN public.master_v2_participants mp
          ON mp.session_id=ww.master_session_id AND mp.character_id=rm.character_id
          AND mp.left_at IS NULL AND mp.engagement_state='attivo'
        JOIN public.characters ch ON ch.id=rm.character_id
          AND ch.user_id=mp.user_id_snapshot
        WHERE rm.id=role_ref AND rm.id=ANY(uw.role_ids)
          AND rm.location_id=mm.location_id AND rm.kind='say' AND rm.recipient_user IS NULL
          AND EXISTS(SELECT 1 FROM mission_generic_owner.role_latest_v1(ww.master_session_id) role_row
            WHERE role_row.message_id=rm.id AND role_row.valid)
          AND position(ub.decision#>>'{source_evidence,0,quote}' in rm.body)>0
          AND EXISTS(SELECT 1 FROM mission_generic_owner.role_submissions current_submission
            JOIN mission_generic_owner.role_window_cursors current_cursor
              ON current_cursor.master_session_id=current_submission.master_session_id
             AND current_cursor.window_epoch=current_submission.window_epoch
            WHERE current_submission.master_session_id=ww.master_session_id
              AND current_submission.message_id=rm.id);
    ELSIF source_kind='narrative_event' THEN
      role_ref:=ub.id;role_actor:=NULL;role_sha:=ub.decision_sha256;
    ELSE RAISE EXCEPTION 'MRS_V4_TRANSITION_KIND'; END IF;
    INSERT INTO mission_generic_owner.unified_publication_permits
      (batch_id,work_id,transaction_id,backend_pid)
    VALUES(ub.id,ww.id,txid_current(),pg_backend_pid());
    route_result:=mission_generic_owner.apply_authority(
      ww.master_session_id,mission_ai_service_owner.uuid5(ub.id,'transition'),
      mm.control_version,ww.run_control_version,opp->>'trigger_key',
      source_kind,role_ref,role_sha,role_actor);
    UPDATE mission_generic_owner.unified_batches SET route=route_result,
      step_key=(SELECT current_step_key FROM public.mission_run_state
        WHERE master_session_id=ww.master_session_id),
      run_control_version=(SELECT control_version FROM public.mission_run_state
        WHERE master_session_id=ww.master_session_id)
      WHERE id=ub.id;
    SELECT * INTO STRICT ub FROM mission_generic_owner.unified_batches WHERE id=ub.id;
  END IF;

  -- L'incontro e le offerte native restano invisibili finché questa
  -- transazione non pubblica l'unico Fato. Il trigger di round_init crea la
  -- finestra della coorte offensiva quando open_core inserisce il round.
  IF ub.encounter_key IS NOT NULL THEN
    IF ub.composition_kind NOT IN ('entry_pg','entry_png','entry_png_deferred')
      OR ub.encounter_id IS NOT NULL OR ub.next_round_id IS NOT NULL
    THEN RAISE EXCEPTION 'MRS_V4_COMBAT_ENTRY_ORDER'; END IF;
    UPDATE mission_generic_owner.unified_batches SET state='preparing' WHERE id=ub.id;
    IF EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources WHERE session_id=ub.master_session_id) THEN
      PERFORM mission_factory_owner.quest_entry_permit_issue_v1(ub.id,ww.id,
        mission_ai_service_owner.uuid5(ub.id,'open'),nullif(route_result->>'authority_receipt_id','')::uuid);
    END IF;
    combat_open:=public.mission_generic_combat_open_v1(
      ub.master_session_id,ub.encounter_key,ub.run_control_version,
      mission_ai_service_owner.uuid5(ub.id,'open'));
    UPDATE mission_generic_owner.unified_batches SET
      encounter_id=(combat_open->>'encounter_id')::uuid,
      next_round_id=(SELECT id FROM public.combat_v2_rounds
        WHERE session_id=(combat_open->>'encounter_id')::uuid
        ORDER BY round_no DESC LIMIT 1)
      WHERE id=ub.id;
    SELECT * INTO STRICT ub FROM mission_generic_owner.unified_batches WHERE id=ub.id;
    IF ub.encounter_id IS NULL OR ub.next_round_id IS NULL
    THEN RAISE EXCEPTION 'MRS_V4_COMBAT_ROUND_MISSING'; END IF;
    offense_round:=ub.next_round_id;
    IF slot_count>0 THEN
      offense_receipts:=mission_generic_owner.unified_stage_offense_v4(
        ub.id,ub.encounter_id,offense_round);
      IF offense_receipts->>'schema_version'<>'mission-entry-offense-receipts/1'
        OR offense_receipts->>'batch_id' IS DISTINCT FROM ub.id::text
        OR offense_receipts->>'encounter_id' IS DISTINCT FROM ub.encounter_id::text
        OR offense_receipts->>'round_id' IS DISTINCT FROM offense_round::text
        OR jsonb_array_length(offense_receipts->'slots')<>slot_count
      THEN RAISE EXCEPTION 'MRS_V4_NATIVE_OFFENSE_RECEIPT'; END IF;
    END IF;
  ELSIF slot_count>0 THEN
    RAISE EXCEPTION 'MRS_V4_OFFENSE_WITHOUT_COMBAT';
  END IF;

  -- Il provider non sceglie bersagli, offerte o esiti. I segmenti IA vengono
  -- intercalati con i tentativi testuali della ricevuta meccanica server.
  FOR part IN SELECT value FROM jsonb_array_elements(p_result->'segments') LOOP
    IF part->>'kind'='prose' THEN
      txt:=btrim(part->>'text');
    ELSE
      SELECT receipt->>'attempt_text' INTO STRICT txt
        FROM jsonb_array_elements(offense_receipts->'slots') receipt
        WHERE receipt->>'slot_id'=part->>'slot_id'
          AND receipt->>'actor_key'=part->>'actor_key';
      IF nullif(btrim(txt),'') IS NULL OR length(txt)>320
      THEN RAISE EXCEPTION 'MRS_V4_NATIVE_ATTEMPT_TEXT'; END IF;
    END IF;
    body:=body||CASE WHEN body='' THEN '' ELSE ' ' END||txt;
  END LOOP;
  IF length(body) NOT BETWEEN (CASE WHEN free_prose THEN 1 ELSE 500 END) AND (CASE WHEN free_prose THEN 5000+321*slot_count ELSE 5000 END) OR body IS DISTINCT FROM btrim(body)
  THEN RAISE EXCEPTION 'MRS_V4_BODY_LENGTH'; END IF;
  IF NOT free_prose THEN PERFORM mission_generic_owner.assert_no_literal_reuse(ww.master_session_id,body);END IF;
  body_sha:=encode(extensions.digest(convert_to(body,'UTF8'),'sha256'),'hex');
  chain:=encode(extensions.digest(convert_to(anchor->>'chain_sha256'||':'||body_sha,'UTF8'),'sha256'),'hex');
  memory:=memory||jsonb_build_object('schema_version','mission-continuity/1',
    'work_id',ww.id,'covered_count',(anchor->>'count')::bigint+1,
    'chain_sha256',chain,'text_sha256',body_sha);

  -- Publication follows route in this SAME transaction. Do not call the
  -- legacy publisher: it re-runs work_assert against the advanced route.
  INSERT INTO public.messages(location_id,character_id,author_name,body,kind,
    sender_user,recipient_user)
    VALUES(mm.location_id,NULL,'Fato',body,'fato',NULL,NULL)
    RETURNING id INTO msg;
  IF msg IS NULL THEN RAISE EXCEPTION 'MRS_V4_FATO_MISSING'; END IF;
  IF slot_count>0 THEN
    sealed_receipts:=mission_generic_owner.seal_deferred_png_v4(ub.id,msg);
    IF jsonb_array_length(sealed_receipts)<>slot_count
    THEN RAISE EXCEPTION 'MRS_V4_SEAL_RECEIPT_COUNT'; END IF;
  END IF;
  UPDATE mission_generic_owner.unified_round_windows SET publication_id=msg
    WHERE batch_id=ub.id AND publication_id IS NULL;
  IF slot_count>0 AND NOT FOUND THEN RAISE EXCEPTION 'MRS_V4_ROUND_WINDOW_SEAL'; END IF;
  IF route_result IS NOT NULL THEN
    SELECT * INTO STRICT tr FROM mission_generic_owner.trigger_receipts
      WHERE id=(route_result->>'authority_receipt_id')::uuid
        AND master_session_id=ub.master_session_id;
    SELECT * INTO STRICT ev FROM public.mission_run_events
      WHERE id=(tr.result->>'event_id')::uuid AND status='committed';
    SELECT * INTO STRICT ob FROM public.mission_run_outbox
      WHERE event_id=ev.id AND state='pending' FOR UPDATE;
    IF ob.master_session_id<>ub.master_session_id
      OR ob.context_fingerprint<>ev.context_fingerprint
      OR ob.step_key<>ev.step_after
      OR ob.event_version_after<>ev.version_after
    THEN RAISE EXCEPTION 'MRS_V4_OUTBOX_DRIFT'; END IF;
    pub:=gen_random_uuid();
    INSERT INTO public.mission_run_publications
      (id,master_session_id,event_id,request_key_sha256,request_fingerprint,
       source,expected_run_control_version,expected_event_version_after,
       expected_step_key,context_fingerprint,body_sha256,status)
    VALUES(pub,ub.master_session_id,ev.id,
      mission_internal.request_key_sha256(p_request),
      mission_internal.fingerprint(jsonb_build_object('batch',ub.id,'work',ww.id,
        'payload',ww.payload_sha256,'body',body_sha)),
      'model',ev.version_after,ev.version_after,ev.step_after,
      ev.context_fingerprint,body_sha,'committed');
    INSERT INTO public.mission_run_messages(publication_id,message_id,body_sha256)
      VALUES(pub,msg,body_sha);
    PERFORM set_config('app.mission_outbox_publish','on',true);
    UPDATE public.mission_run_outbox SET state='published',publication_id=pub,
      published_at=clock_timestamp() WHERE event_id=ev.id;
    PERFORM set_config('app.mission_outbox_publish','off',true);
  END IF;
  PERFORM mission_generic_owner.staff_fato_regen_publish(p_work,msg);
  UPDATE mission_generic_owner.unified_batches SET state='published',message_id=msg,
    published_at=clock_timestamp() WHERE id=ub.id;
  UPDATE mission_generic_owner.unified_source_windows SET consumed_message_id=msg
    WHERE id=ub.source_window_id;
  UPDATE mission_generic_owner.role_window_cursors SET
    window_epoch=window_epoch+1,role_revision=0,
    last_published_fato_id=msg,updated_at=clock_timestamp()
    WHERE master_session_id=ww.master_session_id
      AND mission_generic_owner.role_source_revision_v1(master_session_id)=
        ww.payload->>'source_revision';
  IF NOT FOUND THEN RAISE EXCEPTION 'MRS_V4_CURSOR_ADVANCE_DRIFT'; END IF;
  INSERT INTO mission_generic_owner.unified_segment_publications_v4
    (work_id,batch_id,message_id,raw_result_sha256,segments_sha256,
      final_text_sha256,source_revision,native_receipts)
  VALUES(ww.id,ub.id,msg,p_raw_sha,seg_sha,body_sha,
    ww.payload->>'source_revision',coalesce(sealed_receipts,'[]'::jsonb));
  IF route_result IS NOT NULL THEN PERFORM mission_factory_owner.c485_after_publication_v1(ub.master_session_id,(route_result->>'event_id')::uuid,msg,ub.id);END IF;
  IF literal_recovery THEN
    -- The original provider result and failure remain immutable evidence.
    INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
    VALUES(ww.dispatch_receipt_id,'staff_literal_recovery_completed',jsonb_build_object(
      'schema_version','c1266-literal-recovery/1','work_id',ww.id,'master_session_id',ww.master_session_id,
      'request_key',ww.request_key,'batch_id',ub.id,'message_id',msg,
      'original_state',ww.state,'original_finalized_at',ww.finalized_at,
      'original_result',ww.result,'original_result_sha256',ww.result_sha256,
      'original_result_jsonb_sha256',public.combat_v2_sha256(ww.result),
      'application_error_code','MG_FATO_LITERAL_REPETITION',
      'provider_calls_added',0,'segments_sha256',seg_sha,'final_text_sha256',body_sha));
    UPDATE mission_generic_owner.work_items SET state='completed',message_id=msg,
      result=ww.result||jsonb_build_object('text',body,'continuity',memory),
      result_sha256=public.combat_v2_sha256(ww.result||jsonb_build_object('text',body,'continuity',memory))
      WHERE id=ww.id AND state='failed' AND message_id IS NULL
        AND result IS NOT DISTINCT FROM ww.result AND result_sha256=ww.result_sha256
        AND finalized_at IS NOT DISTINCT FROM ww.finalized_at;
    IF NOT FOUND THEN RAISE EXCEPTION 'C1266_LITERAL_RECOVERY_CAS' USING ERRCODE='40001'; END IF;
  END IF;
  RETURN jsonb_build_object('batch_id',ub.id,'message_id',msg,
    'publication_id',pub,'transition',route_result,'combat_open',combat_open,
    'offense_receipts',coalesce(sealed_receipts,'[]'::jsonb),'text',body,
    'continuity',memory);
END;
$function$

CREATE OR REPLACE FUNCTION public.mission_generic_staff_tick_v1(p_session uuid, p_user uuid, p_source_revision text, p_staff uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tick mission_generic_owner.staff_progress_ticks_v1;
        m public.master_v2_sessions; r public.mission_run_state;
        diag jsonb; pending jsonb; result jsonb; new_key uuid;
        terminal boolean;
BEGIN
  PERFORM mission_ai_board_owner.service_only();
  IF p_session IS NULL OR p_user IS NULL OR p_staff IS NULL
    OR p_source_revision IS NULL OR p_source_revision !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'MGS_TICK_ARGUMENTS' USING ERRCODE='22023'; END IF;
  -- L'Edge deve verificare la sessione utente; il DB ricontrolla ruolo Staff.
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=p_staff AND p.role IN ('admin','master'))
  THEN RAISE EXCEPTION 'MGS_TICK_STAFF_REQUIRED' USING ERRCODE='42501'; END IF;
  -- Il capture del submit e il tick serializzano sullo stesso cursore prima
  -- che la role sia acquisita/pubblicata. Master non va bloccato prima.
  PERFORM 1 FROM mission_generic_owner.role_window_cursors c
    WHERE c.master_session_id=p_session FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MGS_TICK_CURSOR_REQUIRED' USING ERRCODE='55000'; END IF;
  PERFORM public.master_v2_lock_scope(p_session);
  SELECT s.* INTO STRICT m FROM public.master_v2_sessions s WHERE s.id=p_session FOR UPDATE;
  SELECT s.* INTO STRICT r FROM public.mission_run_state s WHERE s.master_session_id=p_session FOR UPDATE;
  IF NOT EXISTS (SELECT 1 FROM mission_generic_owner.flow_staff_sessions f
    JOIN public.locations l ON l.id=m.location_id
    WHERE f.master_session_id=p_session AND f.enabled AND l.is_test)
    OR m.owner_kind<>'ai_service' OR m.closed_at IS NOT NULL
    OR m.stato<>'in_corso' OR m.suspended_at IS NOT NULL OR r.run_phase<>'in_corso'
    OR NOT mission_generic_owner.flow_scope_enabled(p_session)
  THEN RAISE EXCEPTION 'MGS_TICK_SCOPE' USING ERRCODE='42501'; END IF;
  PERFORM mission_generic_owner.dispatch_user(p_session,p_user);
  -- Anche il replay deve appartenere alla revisione ancora corrente: un nuovo
  -- Fato o una nuova role non possono riesporre un vecchio dispatch.
  diag:=mission_generic_owner.role_flow_status_v1(p_session,p_user);
  IF diag->>'source_revision' IS DISTINCT FROM p_source_revision
    OR mission_generic_owner.role_source_revision_v1(p_session) IS DISTINCT FROM p_source_revision
  THEN RAISE EXCEPTION 'MGS_TICK_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;
  SELECT * INTO tick FROM mission_generic_owner.staff_progress_ticks_v1
    WHERE master_session_id=p_session AND source_revision=p_source_revision FOR UPDATE;
  IF tick.request_key IS NOT NULL THEN
    IF tick.actor_user_id<>p_user THEN RAISE EXCEPTION 'MGS_TICK_ACTOR_CONFLICT' USING ERRCODE='40001'; END IF;
    IF p_session='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND p_source_revision='ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb' AND mission_generic_owner.role_source_released_v4('433ace05-5265-4aad-96a3-5567b6e3480a'::uuid) THEN
     SELECT pr.result INTO result FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=mission_ai_service_owner.uuid5('310493d3-92d2-4645-ba85-ab42f57dbf9d'::uuid,'mission-staff-unpublished-reinterpretation/1:ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb') AND pr.master_session_id=p_session AND pr.actor_user_id=p_user AND pr.result_sha256=public.combat_v2_sha256(pr.result);
     IF FOUND THEN RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1','state','replayed','source_revision',p_source_revision,'request_key',mission_ai_service_owner.uuid5('310493d3-92d2-4645-ba85-ab42f57dbf9d'::uuid,'mission-staff-unpublished-reinterpretation/1:ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb'),'progress',result);END IF;
    END IF;

    SELECT pr.result INTO STRICT result FROM mission_generic_owner.progress_receipts pr
      WHERE pr.request_key=tick.request_key AND pr.master_session_id=p_session
        AND pr.actor_user_id=p_user AND pr.result_sha256=tick.result_sha256
        AND pr.result_sha256=public.combat_v2_sha256(pr.result);
    -- Immutable no-dispatch progress may acquire one server-owned successor receipt.
    IF (mission_factory_owner.keys_exact_v2(result,ARRAY['schema_version','master_session_id','state','dispatch'])
 AND result->>'schema_version'='mission-generic-progress/1' AND result->>'master_session_id'=p_session::text
 AND result->>'state'='needs_attention' AND result->'dispatch'='null'::jsonb
 AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items healed 
 WHERE healed.master_session_id=p_session AND healed.created_at<tick.created_at AND (healed.kind='director' AND healed.state='failed' AND healed.result->>'ok'='true'
 AND healed.payload_sha256=public.combat_v2_sha256(healed.payload)
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts healed_dr
  JOIN mission_narrative_internal.dispatch_audit healed_a ON healed_a.receipt_id=healed_dr.id AND healed_a.event_code='c1266_saved_director_applied'
  JOIN mission_narrative_internal.dispatch_audit healed_f ON healed_f.receipt_id=healed_dr.id AND healed_f.event_code='generic_finalized'
  JOIN mission_generic_owner.unified_batches healed_b ON healed_b.decision_work_id=healed.id AND healed_b.master_session_id=p_session
  JOIN mission_generic_owner.unified_source_windows healed_s ON healed_s.id=healed_b.source_window_id AND healed_s.work_id=healed.id AND healed_s.master_session_id=p_session
  JOIN mission_generic_owner.work_items healed_writer ON healed_writer.id=healed_b.writer_work_id AND healed_writer.master_session_id=p_session AND healed_writer.authority_receipt_id=healed_b.id
  JOIN public.messages healed_msg ON healed_msg.id=healed_writer.message_id AND healed_msg.kind='fato' AND healed_msg.recipient_user IS NULL AND healed_msg.body=healed_writer.result->>'text'
  WHERE healed_dr.id=healed.dispatch_receipt_id AND healed_dr.master_session_id=p_session AND healed_dr.authority_receipt_id=healed.id AND healed_dr.request_key=healed.request_key
   AND healed_dr.status='success' AND healed_dr.dispatch_count=1 AND healed_dr.finalized_at IS NOT NULL
   AND healed_a.details->>'schema_version'='c1266-saved-director-application/1' AND healed_a.details->>'master_session_id'=p_session::text
   AND healed_a.details->>'work_id'=healed.id::text AND healed_a.details->>'result_sha256'=healed.result_sha256
   AND healed_a.details->>'batch_id'=healed_b.id::text AND healed_a.details->>'writer_work_id'=healed_writer.id::text
   AND healed_a.details->>'generation_http_calls'='0' AND healed_a.details->>'failed_work_preserved'='true'
   AND healed_f.details->>'work_id'=healed.id::text AND healed_f.details->>'receipt_id'=healed.receipt_id::text
   AND healed_f.details->>'result_sha256'=healed.result_sha256 AND healed_f.details->>'result_jsonb_sha256'=public.combat_v2_sha256(healed.result)
   AND healed_b.state='published' AND healed_b.published_at IS NOT NULL AND healed_b.message_id=healed_writer.message_id
   AND healed_s.consumed_message_id=healed_b.message_id AND healed_s.superseded_at IS NULL
   AND healed_s.source_sha256=healed.payload_sha256 AND healed_writer.kind='narration' AND healed_writer.state='completed'
   AND healed_writer.payload=healed_b.payload AND healed_writer.payload_sha256=healed_b.payload_sha256
   AND healed_writer.payload_sha256=public.combat_v2_sha256(healed_writer.payload)
   AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 healed_pub WHERE healed_pub.work_id=healed_writer.id AND healed_pub.message_id=healed_msg.id)
   AND EXISTS(SELECT 1 FROM staff_ai_quota_private.calls healed_q WHERE healed_q.producer='mission_generic_ai' AND healed_q.scope_id=p_session AND healed_q.source_id=healed_dr.id AND healed_q.call_no=1 AND healed_q.state='settled' AND healed_q.charged_usd=healed_dr.charged_cost_usd)))) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items unresolved WHERE unresolved.master_session_id=p_session AND unresolved.step_key=r.current_step_key AND unresolved.run_control_version=r.control_version AND unresolved.state='failed' AND NOT (unresolved.kind='director' AND unresolved.state='failed' AND unresolved.result->>'ok'='true'
 AND unresolved.payload_sha256=public.combat_v2_sha256(unresolved.payload)
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts healed_dr
  JOIN mission_narrative_internal.dispatch_audit healed_a ON healed_a.receipt_id=healed_dr.id AND healed_a.event_code='c1266_saved_director_applied'
  JOIN mission_narrative_internal.dispatch_audit healed_f ON healed_f.receipt_id=healed_dr.id AND healed_f.event_code='generic_finalized'
  JOIN mission_generic_owner.unified_batches healed_b ON healed_b.decision_work_id=unresolved.id AND healed_b.master_session_id=p_session
  JOIN mission_generic_owner.unified_source_windows healed_s ON healed_s.id=healed_b.source_window_id AND healed_s.work_id=unresolved.id AND healed_s.master_session_id=p_session
  JOIN mission_generic_owner.work_items healed_writer ON healed_writer.id=healed_b.writer_work_id AND healed_writer.master_session_id=p_session AND healed_writer.authority_receipt_id=healed_b.id
  JOIN public.messages healed_msg ON healed_msg.id=healed_writer.message_id AND healed_msg.kind='fato' AND healed_msg.recipient_user IS NULL AND healed_msg.body=healed_writer.result->>'text'
  WHERE healed_dr.id=unresolved.dispatch_receipt_id AND healed_dr.master_session_id=p_session AND healed_dr.authority_receipt_id=unresolved.id AND healed_dr.request_key=unresolved.request_key
   AND healed_dr.status='success' AND healed_dr.dispatch_count=1 AND healed_dr.finalized_at IS NOT NULL
   AND healed_a.details->>'schema_version'='c1266-saved-director-application/1' AND healed_a.details->>'master_session_id'=p_session::text
   AND healed_a.details->>'work_id'=unresolved.id::text AND healed_a.details->>'result_sha256'=unresolved.result_sha256
   AND healed_a.details->>'batch_id'=healed_b.id::text AND healed_a.details->>'writer_work_id'=healed_writer.id::text
   AND healed_a.details->>'generation_http_calls'='0' AND healed_a.details->>'failed_work_preserved'='true'
   AND healed_f.details->>'work_id'=unresolved.id::text AND healed_f.details->>'receipt_id'=unresolved.receipt_id::text
   AND healed_f.details->>'result_sha256'=unresolved.result_sha256 AND healed_f.details->>'result_jsonb_sha256'=public.combat_v2_sha256(unresolved.result)
   AND healed_b.state='published' AND healed_b.published_at IS NOT NULL AND healed_b.message_id=healed_writer.message_id
   AND healed_s.consumed_message_id=healed_b.message_id AND healed_s.superseded_at IS NULL
   AND healed_s.source_sha256=unresolved.payload_sha256 AND healed_writer.kind='narration' AND healed_writer.state='completed'
   AND healed_writer.payload=healed_b.payload AND healed_writer.payload_sha256=healed_b.payload_sha256
   AND healed_writer.payload_sha256=public.combat_v2_sha256(healed_writer.payload)
   AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 healed_pub WHERE healed_pub.work_id=healed_writer.id AND healed_pub.message_id=healed_msg.id)
   AND EXISTS(SELECT 1 FROM staff_ai_quota_private.calls healed_q WHERE healed_q.producer='mission_generic_ai' AND healed_q.scope_id=p_session AND healed_q.source_id=healed_dr.id AND healed_q.call_no=1 AND healed_q.state='settled' AND healed_q.charged_usd=healed_dr.charged_cost_usd))) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_source_windows released WHERE released.work_id=unresolved.id AND mission_generic_owner.role_source_released_v4(released.id)))) THEN
      new_key:=mission_ai_service_owner.uuid5(tick.request_key,'mission-staff-no-dispatch-resume/1:'||p_source_revision);
      SELECT pr.result INTO result FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=new_key
       AND pr.master_session_id=p_session AND pr.actor_user_id=p_user AND pr.result_sha256=public.combat_v2_sha256(pr.result);
      IF FOUND THEN RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1','state','replayed','source_revision',p_source_revision,'request_key',new_key,'progress',result);END IF;
      IF EXISTS(SELECT 1 FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=new_key) THEN RAISE EXCEPTION 'MGS_NO_WORK_RECEIPT_CONFLICT' USING ERRCODE='40001';END IF;
    ELSE
    -- The first tick is not rewritten. An attested, released Director may
    -- receive one deterministic retry for this very same role revision.
    DECLARE
      failed_work mission_generic_owner.work_items;
      released_source mission_generic_owner.unified_source_windows;
      retry_receipt mission_generic_owner.progress_receipts;
      second_work mission_generic_owner.work_items;
      second_source mission_generic_owner.unified_source_windows;
      second_receipt mission_generic_owner.progress_receipts;
      failed_id uuid;
      second_id uuid;
    BEGIN
      IF (result->'dispatch'->>'event_id') ~
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        failed_id:=(result->'dispatch'->>'event_id')::uuid;
        SELECT * INTO failed_work FROM mission_generic_owner.work_items w
          WHERE w.id=failed_id
            AND w.master_session_id=p_session AND w.kind='director';
        IF failed_work.id IS NOT NULL THEN
          SELECT * INTO released_source FROM mission_generic_owner.unified_source_windows sw
            WHERE sw.id=failed_work.authority_receipt_id
              AND sw.work_id=failed_work.id AND sw.master_session_id=p_session;
        END IF;
      END IF;
      IF failed_work.id IS NOT NULL AND released_source.id IS NOT NULL
        AND failed_work.state='failed' AND failed_work.finalized_at IS NOT NULL
        AND released_source.context->>'source_revision'=p_source_revision
        AND (released_source.superseded_reason='staff_failed_director_validation_retry' OR (released_source.id IN('d460a7be-a3a2-4ad8-9d3b-d2e929f2947e'::uuid,'f4f7185e-4aae-4edd-ac24-65f8dcfa36f5'::uuid) AND released_source.master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND released_source.superseded_reason='staff_preprovider_request_retry'))
        AND released_source.consumed_message_id IS NULL
        AND result->'dispatch'->>'request_key'=failed_work.request_key::text
        AND mission_generic_owner.role_source_released_v4(released_source.id) THEN
        new_key:=mission_ai_service_owner.uuid5(failed_work.id,
          'mission-staff-released-director-retry/1:'||p_source_revision);
        SELECT * INTO retry_receipt FROM mission_generic_owner.progress_receipts pr
          WHERE pr.request_key=new_key;
        IF retry_receipt.request_key IS NOT NULL THEN
          IF retry_receipt.master_session_id<>p_session
            OR retry_receipt.actor_user_id<>p_user
            OR retry_receipt.result_sha256<>public.combat_v2_sha256(retry_receipt.result)
          THEN RAISE EXCEPTION 'MGS_TICK_RETRY_RECEIPT_CONFLICT' USING ERRCODE='40001'; END IF;
          IF (retry_receipt.result#>>'{dispatch,event_id}') ~
             '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            second_id:=(retry_receipt.result#>>'{dispatch,event_id}')::uuid;
            SELECT * INTO second_work FROM mission_generic_owner.work_items w
              WHERE w.id=second_id AND w.master_session_id=p_session AND w.kind='director';
            IF second_work.id IS NOT NULL THEN
              SELECT * INTO second_source FROM mission_generic_owner.unified_source_windows sw
                WHERE sw.id=second_work.authority_receipt_id
                  AND sw.work_id=second_work.id AND sw.master_session_id=p_session;
            END IF;
          END IF;
          IF second_work.id IS NOT NULL AND second_source.id IS NOT NULL
            AND second_work.state='failed' AND second_work.finalized_at IS NOT NULL
            AND second_source.context->>'source_revision'=p_source_revision
            AND second_source.superseded_reason='staff_failed_director_validation_retry'
            AND second_source.consumed_message_id IS NULL
            AND retry_receipt.result#>>'{dispatch,request_key}'=second_work.request_key::text
            AND mission_generic_owner.role_source_released_v4(second_source.id) THEN
            failed_work:=second_work;
            released_source:=second_source;
            new_key:=mission_ai_service_owner.uuid5(second_work.id,
              'mission-staff-db-context-retry/2:'||p_source_revision);
            SELECT * INTO second_receipt FROM mission_generic_owner.progress_receipts pr
              WHERE pr.request_key=new_key;
            IF second_receipt.request_key IS NOT NULL THEN
              IF second_receipt.master_session_id<>p_session
                OR second_receipt.actor_user_id<>p_user
                OR second_receipt.result_sha256<>public.combat_v2_sha256(second_receipt.result)
              THEN RAISE EXCEPTION 'MGS_TICK_SECOND_RECEIPT_CONFLICT' USING ERRCODE='40001'; END IF;
              RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
                'state','replayed','source_revision',p_source_revision,
                'request_key',new_key,'progress',second_receipt.result);
            END IF;
          ELSE
            RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
              'state','replayed','source_revision',p_source_revision,
              'request_key',new_key,'progress',retry_receipt.result);
          END IF;
        END IF;
        IF EXISTS(SELECT 1 FROM mission_generic_owner.work_items newer
          WHERE newer.master_session_id=p_session AND newer.created_at>failed_work.created_at)
        THEN RAISE EXCEPTION 'MGS_TICK_RETRY_NEWER_WORK' USING ERRCODE='40001'; END IF;
      END IF;
    END;
    END IF;
    IF new_key IS NULL THEN
      RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
        'state','replayed','source_revision',p_source_revision,
        'request_key',tick.request_key,'progress',result);
    END IF;
  END IF;
  -- Una revisione nuova non bypassa work/provider incerti della precedente.
  pending:=public.mission_generic_dispatch_next_v1(p_session,p_user);
  IF jsonb_typeof(pending->'request')='object' THEN
    RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
      'state','existing_work','source_revision',p_source_revision,
      'request_key',null,'progress',jsonb_build_object(
        'schema_version','mission-generic-progress/1',
        'master_session_id',p_session,'state','work_pending','dispatch',null));
  END IF;
  IF EXISTS (SELECT 1 FROM mission_generic_owner.work_items w
    WHERE w.master_session_id=p_session AND w.state IN ('ready','claimed','authorized','provider_started'))
    OR EXISTS (SELECT 1 FROM mission_generic_owner.unified_source_windows sw
      WHERE sw.master_session_id=p_session AND sw.consumed_message_id IS NULL AND sw.superseded_at IS NULL)
    OR EXISTS (SELECT 1 FROM public.combat_v2_sessions cs
      WHERE cs.master_session_id=p_session AND cs.closed_at IS NULL)
  THEN RAISE EXCEPTION 'MGS_TICK_ACTIVE_OR_UNCERTAIN_WORK' USING ERRCODE='55000'; END IF;
  SELECT EXISTS (SELECT 1 FROM jsonb_array_elements(
    mission_generic_owner.run_plan_settings(p_session)->'terminal_steps') t
    WHERE t->>'step_key'=r.current_step_key) INTO terminal;
  IF terminal THEN RAISE EXCEPTION 'MGS_TICK_TERMINAL_STEP' USING ERRCODE='55000'; END IF;
  IF diag->>'flow_reason'<>'ready_to_evaluate'
  THEN RAISE EXCEPTION 'MGS_TICK_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;
  new_key:=coalesce(new_key,gen_random_uuid());
  result:=mission_generic_owner.progress_step(p_session,p_user,new_key);
  INSERT INTO mission_generic_owner.progress_receipts
    (request_key,master_session_id,actor_user_id,result,result_sha256)
  VALUES(new_key,p_session,p_user,result,public.combat_v2_sha256(result));
  IF tick.request_key IS NULL THEN
    INSERT INTO mission_generic_owner.staff_progress_ticks_v1
      (master_session_id,source_revision,request_key,actor_user_id,staff_user_id,result_sha256)
    VALUES(p_session,p_source_revision,new_key,p_user,p_staff,public.combat_v2_sha256(result));
  END IF;
  RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
    'state','issued','source_revision',p_source_revision,
    'request_key',new_key,'progress',result);
END;
$function$

CREATE OR REPLACE FUNCTION public.mission_generic_dispatch_finalize_v1(p_work uuid, p_finalize_token text, p_result_text text, p_result_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w mission_generic_owner.work_items;d mission_narrative_internal.dispatch_receipts;z mission_narrative_internal.provider_authorizations;
 pol mission_narrative_internal.runtime_policy;a mission_narrative_internal.dispatch_attempts;
 ok boolean;stale boolean:=false;metrics jsonb;actual numeric;basis text;receipt uuid:=gen_random_uuid();msg uuid;cr jsonb;
 p_result jsonb;tr mission_generic_owner.trigger_receipts;ev public.mission_run_events;ob public.mission_run_outbox;
 publication uuid;bodysha text;bs mission_generic_owner.board_starts;
 application_error text;application_error_code text;outcome_uncertain boolean:=false;stale_role boolean:=false;role_revision text;
 retained mission_narrative_internal.provider_outputs_v1; admission jsonb; free_prose boolean:=false; raw_json jsonb; carried jsonb;
 c726_factory_settlement boolean:=false;shared_on boolean;shared_call staff_ai_quota_private.calls%rowtype;
begin
 perform mission_ai_board_owner.service_only();
 if exists(select 1 from mission_generic_owner.role_window_cursors c
   where c.master_session_id=(select master_session_id from mission_generic_owner.work_items where id=p_work)) then
   perform 1 from mission_generic_owner.role_window_cursors c
     where c.master_session_id=(select master_session_id from mission_generic_owner.work_items where id=p_work)
     for update;
   role_revision:=mission_generic_owner.role_source_revision_v1(
     (select master_session_id from mission_generic_owner.work_items where id=p_work));
 end if;
 perform 1 from public.locations where id=(select q.location_id from mission_factory_owner.quest_run_sources q join mission_generic_owner.work_items wi_lock on wi_lock.master_session_id=q.session_id where wi_lock.id=p_work) for update;
 perform 1 from public.master_v2_sessions where id=(select master_session_id from mission_generic_owner.work_items where id=p_work) for update;
 if p_result_text is null or octet_length(p_result_text)>65536
 or encode(extensions.digest(convert_to(p_result_text,'UTF8'),'sha256'),'hex') is distinct from p_result_sha
 then raise exception 'MGD_RESULT_HASH';end if;
 p_result:=p_result_text::jsonb;
 select * into strict w from mission_generic_owner.work_items where id=p_work for update;
 if w.state in('completed','failed','uncertain') then
  if w.state='completed'
    and w.kind='narration'
    and w.payload->>'schema_version'='mission-generic-narration/4' then
    if not exists(select 1 from mission_generic_owner.unified_segment_publications_v4 pub
      where pub.work_id=w.id and pub.raw_result_sha256=p_result_sha)
    then raise exception 'MGD_FINALIZE_CONFLICT' using errcode='40001';end if;
  elsif w.result_sha256 is distinct from p_result_sha then
    raise exception 'MGD_FINALIZE_CONFLICT' using errcode='40001';
  end if;
  return mission_generic_owner.work_status(w);
 end if;
 select * into strict d from mission_narrative_internal.dispatch_receipts where id=w.dispatch_receipt_id for update;
 select * into strict z from mission_narrative_internal.provider_authorizations where id=w.authorization_id and receipt_id=d.id for update;
 select * into strict a from mission_narrative_internal.dispatch_attempts where id=z.attempt_id for update;
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton for share;
 if w.state<>'provider_started' or d.status<>'provider_started' or z.finalize_token_sha256 is distinct from mission_narrative_internal.token_sha(p_finalize_token)
 or p_result->>'schema_version' is distinct from (case when w.payload->>'schema_version'='mission-generic-narration/4' then 'mission-generic-result/2' else 'mission-generic-result/1' end) or p_result->>'work_id' is distinct from w.id::text
 or p_result->>'master_session_id' is distinct from w.master_session_id::text or p_result->>'event_id' is distinct from w.event_id::text
 or p_result->>'request_key' is distinct from w.request_key::text or (p_result->>'revision')::bigint is distinct from w.revision
 or p_result->>'authority_receipt_id' is distinct from w.authority_receipt_id::text or p_result->>'definition_sha256' is distinct from w.definition_sha256
 or p_result->>'payload_sha256' is distinct from w.payload_sha256 or p_result->>'kind' is distinct from w.kind
 or p_result->>'authorization_id' is distinct from w.authorization_id::text or p_result->>'dispatch_id' is distinct from w.dispatch_id::text
 or p_result->>'model' is distinct from pol.model or coalesce(p_result_sha,'')!~'^[0-9a-f]{64}$'
 or p_result->>'runtime_version' is distinct from (case when w.payload->>'schema_version'='mission-generic-narration/4' then 'mission-generic-runtime/2' else 'mission-generic-runtime/1' end)
 or p_result->>'provider_calls' not in('0','1')
 or jsonb_typeof(p_result->'outcome_uncertain') is distinct from 'boolean'
 or (p_result->>'outcome_uncertain'='true' and p_result->>'ok' is distinct from 'false')
 or (p_result->>'ok'='true' and p_result->>'provider_calls' is distinct from '1')
 then raise exception 'MGD_FINALIZE_BINDING';end if;
 SELECT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls qc726 JOIN mission_generic_owner.dispatch_admissions da726 ON da726.master_session_id=w.master_session_id JOIN mission_generic_owner.run_bindings rb726 ON rb726.master_session_id=da726.master_session_id WHERE qc726.producer='mission_generic_ai' AND qc726.source_id=d.id AND qc726.call_no=1 AND qc726.scope_id=w.master_session_id AND qc726.state IN('reserved','sent','unknown_billable') AND da726.c7_budget_enforced AND da726.call_limit=14 AND da726.cost_budget_usd=0.3136 AND da726.c8_count_upper_cost_usd=0.0112 AND da726.c8_count_qualification_sha256~'^[a-f0-9]{64}$' AND rb726.snapshot_sha256=mission_internal.fingerprint(rb726.snapshot) AND da726.c7_budget_qualification_sha256=encode(extensions.digest(convert_to(jsonb_build_object('schema_version','c717-native-staff-admission-proof/1','count_contract_sha256','b242ee7fcc6655fa951e8697acfbee4d6ba92b42b177fcbcf6a9b08d004661b2','session_id',w.master_session_id,'binding_sha256',rb726.snapshot_sha256,'count_qualification_sha256',da726.c8_count_qualification_sha256,'generation_limit',14,'http_limit',28,'cost','0.3136')::text,'UTF8'),'sha256'),'hex')) INTO c726_factory_settlement;

 if (d.envelope->'narrative_admission') is distinct from mission_public_owner.work_contract_v1(w.id)
 then raise exception 'NARRATIVE_FINALIZE_ADMISSION_BINDING' using errcode='40001';end if;
 -- The exact canonical string is hashed before JSONB parsing; no JS/JSONB equivalence assumption.
 metrics:=p_result->'usage';
 if jsonb_typeof(metrics) is distinct from 'object' then metrics:='{}';end if;
 if jsonb_typeof(metrics)='object' and mission_generic_owner.keys_valid(metrics,array['input_tokens','output_tokens','reasoning_tokens','total_tokens'])
 and not exists(select 1 from jsonb_each_text(metrics) where value!~'^[0-9]+$')
 and (metrics->>'reasoning_tokens')::numeric<=(metrics->>'output_tokens')::numeric
 and (metrics->>'total_tokens')::numeric=(metrics->>'input_tokens')::numeric+(metrics->>'output_tokens')::numeric then
  actual:=((metrics->>'input_tokens')::numeric*pol.input_usd_million+(metrics->>'output_tokens')::numeric*pol.output_usd_million)/1000000;basis:='exact';
 else actual:=d.upper_bound_cost_usd;basis:='upper_bound';end if;
 if actual>d.upper_bound_cost_usd then stale:=true;end if;

begin perform mission_generic_owner.work_assert(w); exception when others then stale:=true;end;
if role_revision is not null then
  if w.kind='director'
     and w.payload#>>'{context,source_revision}' is distinct from role_revision then
    stale_role:=true;stale:=true;
  elsif w.kind='narration' and w.payload->>'schema_version'='mission-generic-narration/4'
     and w.payload->>'source_revision' is distinct from role_revision then
    stale_role:=true;stale:=true;
  end if;
end if;

 outcome_uncertain:=(p_result->>'outcome_uncertain')::boolean;
 ok:=coalesce((p_result->>'ok')::boolean,false) and not outcome_uncertain and not stale and w.lease_expires_at>clock_timestamp();
 admission:=mission_public_owner.work_contract_v1(w.id);
 free_prose:=coalesce(admission->'features' ? 'free_narrative_v1',false);
 -- Result application is a subtransaction: failures roll back every domain write,
 -- while the outer transaction still records the provider receipt and real cost.
 begin
 IF ok AND admission->'features' ? 'provider_output_retention_v1' THEN
  SELECT * INTO STRICT retained FROM mission_narrative_internal.provider_outputs_v1 r
    WHERE r.id=(p_result->>'output_receipt_id')::uuid AND r.work_id=w.id
      AND r.authorization_id=w.authorization_id AND r.dispatch_id=w.dispatch_id
      AND r.dispatch_receipt_id=w.dispatch_receipt_id AND r.raw_sha256=p_result->>'raw_sha256';
  IF retained.raw_sha256<>encode(extensions.digest(convert_to(retained.raw_output,'UTF8'),'sha256'),'hex')
  THEN RAISE EXCEPTION 'MGD_RETAINED_OUTPUT_HASH';END IF;
 END IF;
 IF ok AND free_prose THEN
  IF w.kind<>'narration' OR w.payload->>'schema_version'<>'mission-generic-narration/4'
    OR NOT(admission->'features' ? 'provider_output_retention_v1')
  THEN RAISE EXCEPTION 'MGD_FREE_PROSE_SCOPE';END IF;
  raw_json:=retained.raw_output::jsonb;
  IF jsonb_typeof(raw_json->'testo') IS DISTINCT FROM 'string'
    OR btrim(raw_json->>'testo')='' OR p_result->>'text' IS DISTINCT FROM raw_json->>'testo'
  THEN RAISE EXCEPTION 'MGD_FREE_PROSE_TEXT_BINDING';END IF;
  carried:=w.payload#>'{source_context,continuity}';
  IF jsonb_typeof(carried) IS DISTINCT FROM 'object' THEN carried:='{"state":"","known":[],"open":[],"used":[]}'::jsonb;END IF;
  carried:=jsonb_build_object('state',carried->'state','known',carried->'known','open',carried->'open','used',carried->'used');
  p_result:=p_result||jsonb_build_object('text',null,'profile_audit',null,
    'segments',jsonb_build_array(jsonb_build_object('kind','prose','text',raw_json->>'testo','slot_id',null,'actor_key',null))||
      coalesce((SELECT jsonb_agg(jsonb_build_object('kind','offense_slot','text',null,'slot_id',slot->>'slot_id','actor_key',slot->>'actor_key') ORDER BY slot->>'actor_key') FROM jsonb_array_elements(w.payload->'offense_slots') slot),'[]'::jsonb),
    'continuity_draft',carried,'history_anchor',jsonb_build_object('chain_sha256',w.payload#>>'{source_context,history_chain_sha256}','count',(w.payload#>>'{source_context,history_count}')::bigint));
 END IF;
 if ok and w.kind='narration' and mission_generic_owner.flow_scope_enabled(w.master_session_id)
    and w.payload->>'schema_version' is distinct from 'mission-generic-narration/4' then
  if jsonb_typeof(p_result->'text') is distinct from 'string' then raise exception 'MGD_NARRATIVE_TEXT_SHAPE';end if;
  perform mission_generic_owner.assert_no_literal_reuse(w.master_session_id,p_result->>'text');
 end if;
 if ok and w.kind='director' then
  if p_result->'command' is distinct from 'null'::jsonb or p_result->'text' is distinct from 'null'::jsonb
  then raise exception 'MUF_DIRECTOR_RESULT_SHAPE';end if;
  cr:=mission_generic_owner.unified_director_commit(w.id,p_result->'decision');
 elsif ok and w.kind='narration' and w.payload->>'mode'='unified' then
  if w.payload->>'schema_version'='mission-generic-narration/4' then
    cr:=mission_generic_owner.unified_publish_v4(w.id,p_result,w.request_key,p_result_sha);
    msg:=(cr->>'message_id')::uuid;
    p_result:=p_result||jsonb_build_object('text',cr->>'text','continuity',cr->'continuity');
  else
    if jsonb_typeof(p_result->'text') is distinct from 'string' then raise exception 'MUF_WRITER_RESULT_SHAPE';end if;
    cr:=mission_generic_owner.unified_publish(w.id,p_result->>'text',w.request_key);msg:=(cr->>'message_id')::uuid;
  end if;
 elsif ok and w.kind='choice' then
  if p_result ? 'peaceful_exit' then
   if not mission_generic_owner.keys_valid(p_result->'peaceful_exit',
      array['schema_version','intent','pg_declaration_ids','agreement_summary'])
    or p_result#>>'{peaceful_exit,schema_version}' is distinct from 'mission-peaceful-proposal/1'
    or p_result#>>'{peaceful_exit,intent}' not in ('none','accept')
    or jsonb_typeof(p_result#>'{peaceful_exit,pg_declaration_ids}') is distinct from 'array'
    or jsonb_typeof(p_result#>'{peaceful_exit,agreement_summary}') is distinct from 'string'
    or (p_result#>>'{peaceful_exit,intent}'='none' and
      (jsonb_array_length(p_result#>'{peaceful_exit,pg_declaration_ids}')<>0
       or p_result#>>'{peaceful_exit,agreement_summary}'<>''))
    or (p_result#>>'{peaceful_exit,intent}'='accept' and
      (jsonb_array_length(p_result#>'{peaceful_exit,pg_declaration_ids}')=0
       or length(btrim(p_result#>>'{peaceful_exit,agreement_summary}')) not between 8 and 500))
   then raise exception 'MUP_CHOICE_PEACEFUL_SHAPE';end if;
  end if;
  if d.envelope#>>'{narrative_admission,schema_version}' IN('mission-narrative-admission/2','mission-narrative-admission/3') then
   cr:=mission_public_owner.choice_commit_v2(w.id,(w.payload->>'capability_id')::uuid,p_result->'command',p_result->'peaceful_exit');
  else
   cr:=mission_generic_owner.choice_commit(w.id,(w.payload->>'capability_id')::uuid,p_result->'command');
  end if;
  if cr is null or not exists(select 1 from mission_generic_owner.panel_choices pc
   join combat_panel_private.request_receipts rr on rr.principal_user=pc.principal_id and rr.request_key=pc.request_key
   where pc.work_id=w.id and pc.id=(w.payload->>'capability_id')::uuid and pc.consumed_at is not null
    and pc.result=cr and rr.viewer_envelope=cr and rr.event_id is not null
    and rr.offer_id=(p_result#>>'{command,offer_id}')::uuid
    and pc.command_sha256=public.combat_v2_sha256(combat_panel_private.validate_command(p_result->'command')))
  then raise exception 'MGD_COMMAND_RECEIPT_MISSING';end if;
 elsif ok then
  if w.payload#>>'{barrier,closed}' is distinct from 'true'
   or exists(select 1 from jsonb_array_elements_text(w.payload#>'{barrier,required_receipt_ids}') id
    where not(w.payload#>'{barrier,receipt_ids}' ? id))
   or jsonb_typeof(p_result->'text') is distinct from 'string' or length(btrim(p_result->>'text')) not between 1 and 5000
  then raise exception 'MGD_NARRATIVE_BARRIER';end if;
  if w.payload->>'source_kind'='quest' and w.payload#>>'{quest_lifecycle,phase}' in('opening','terminal') then
   cr:=mission_factory_owner.quest_work_publish_v1(w.id,p_result->>'text');
   msg:=(cr->>'message_id')::uuid;
   if msg is null then raise exception 'MF_QUEST_PUBLICATION_MESSAGE_MISSING';end if;
  elsif w.payload->>'mode'='combat' then
   cr:=mission_generic_owner.combat_publish(w.id,p_result->>'text',w.request_key);
   msg:=(cr->>'message_id')::uuid;
   if msg is null or not exists(select 1 from public.messages m join public.master_v2_sessions s on s.location_id=m.location_id
    where s.id=w.master_session_id and m.id=msg) then raise exception 'MGD_COMBAT_PUBLICATION_MISSING';end if;
  elsif w.payload->>'mode'='mission' then
   insert into public.messages(location_id,character_id,author_name,body,kind,sender_user,recipient_user,created_at)
   select location_id,null,'Fato',p_result->>'text','fato',null,null,clock_timestamp() from public.master_v2_sessions where id=w.master_session_id returning id into msg;
   if w.payload ? 'opening_start_receipt_id' then
    select * into strict bs from mission_generic_owner.board_starts where id=w.authority_receipt_id and master_session_id=w.master_session_id for update;
    select * into strict ev from public.mission_run_events where id=bs.event_id and master_session_id=w.master_session_id for update;
   else
    select * into strict tr from mission_generic_owner.trigger_receipts where id=w.authority_receipt_id and master_session_id=w.master_session_id;
    select * into strict ev from public.mission_run_events where id=(tr.result->>'event_id')::uuid and master_session_id=w.master_session_id for update;
   end if;
   select * into strict ob from public.mission_run_outbox where event_id=ev.id and master_session_id=w.master_session_id for update;
   if ev.status<>'committed' or ob.state<>'pending' or ev.version_after<>w.run_control_version
    or ob.event_version_after<>ev.version_after or ev.step_after<>w.step_key or ob.step_key<>w.step_key
    or ob.context_fingerprint<>ev.context_fingerprint then raise exception 'MGD_OUTBOX_STALE';end if;
   bodysha:=encode(extensions.digest(convert_to(p_result->>'text','UTF8'),'sha256'),'hex');
   publication:=gen_random_uuid();
   insert into public.mission_run_publications(id,master_session_id,event_id,request_key_sha256,request_fingerprint,source,
    expected_run_control_version,expected_event_version_after,expected_step_key,context_fingerprint,body_sha256,status)
   values(publication,w.master_session_id,ev.id,mission_internal.request_key_sha256(w.request_key),
    mission_internal.fingerprint(jsonb_build_object('schema_version','mission-generic-publication/1','work_id',w.id,'event_id',ev.id,
    'payload_sha256',w.payload_sha256,'body_sha256',bodysha)),'model',w.run_control_version,ev.version_after,w.step_key,ev.context_fingerprint,bodysha,'committed');
   insert into public.mission_run_messages(publication_id,message_id,body_sha256) values(publication,msg,bodysha);
   -- Same guarded outbox transition as native publication; no invented reveal grants.
   perform set_config('app.mission_outbox_publish','on',true);
   update public.mission_run_outbox set state='published',publication_id=publication,published_at=clock_timestamp() where event_id=ev.id;
   perform set_config('app.mission_outbox_publish','off',true);
   if w.payload ? 'opening_start_receipt_id' then
    perform mission_generic_owner.opening_published(w.master_session_id,publication);
   end if;
  else raise exception 'MGD_NARRATIVE_MODE';
  end if;
 end if;
 exception when others then
  application_error:=SQLSTATE;
  application_error_code:=case when SQLSTATE='22023' and SQLERRM='MG_FATO_LITERAL_REPETITION' then 'MG_FATO_LITERAL_REPETITION'
   WHEN SQLSTATE IN('P0001','40001','42501') AND SQLERRM IN('C1266_PEER_BATCH_PROVENANCE','C1266_PEER_CONTRACT_BINDING','C1266_PEER_EVIDENCE_BINDING','C1266_PEER_FEATURE_SCOPE','C1266_PEER_INTERPRETATION_VERSION_REQUIRED','C1266_PEER_NULL_REQUIRED','C1266_PEER_ORDER_BINDING','C1266_PEER_ORDER_COVERAGE','C1266_PEER_OWN_MOVEMENT_REQUIRED','C1266_PEER_REFERENCE_BINDING','C1266_PEER_REFERENCE_SHAPE','C1266_PEER_SUBMISSION_ORDER_BINDING','C1266_PEER_TEMPORAL_SHAPE','C1266_PEER4_BATCH_FULL_PROJECTION','C1266_PEER4_EFFECT_INVALID','C1266_PEER4_IMMEDIATE_ANCHOR','C1266_PEER4_IMMEDIATE_LIMIT','C1266_PEER4_IMMEDIATE_SHAPE','C1266_PEER4_PROJECTION_IMMEDIATE','C1266_PEER4_ROLE_BINDING','C1266_PEER4_UNKNOWN_BINDING','C1266_PEER4_UNKNOWN_EVIDENCE','C1266_PEER4_VALID_ROSTER_REQUIRED','C1266_PEER4_WRITER_FULL_PROJECTION')
    AND EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 peer_wc
 JOIN mission_factory_owner.editor_release_readiness peer_rr ON peer_rr.singleton
 WHERE peer_wc.work_id=w.id AND peer_wc.master_session_id=w.master_session_id AND peer_wc.scope='staff_mission'
 AND peer_wc.contract_sha256=public.combat_v2_sha256(peer_wc.contract)
 AND peer_wc.contract->>'schema_version'='mission-narrative-admission/3'
 AND peer_wc.contract->'features' ? 'role_intents_v2'
 AND peer_wc.contract->'features' ? 'execution_authority_v1'
 AND peer_wc.contract#>>'{source_attestation,role_intents,schema_version}'='mission-role-intent-attestation/4'
 AND peer_wc.contract#>>'{source_attestation,role_intents,temporal_contract_sha256}'='0603ab23e76750b5babeb41421bc84b551b959945f21267ffd7169140732f1e8'
 AND peer_wc.contract#>>'{source_attestation,role_intents,peer_confirmation,schema_version}'='mission-peer-confirmation-contract/2'
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,schema_version}'='c1266-work-execution-attestation/1' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND peer_wc.contract#>>'{source_attestation,execution_authority,execution_context}'='staff_mission'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,kind}'='staff_finite'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,resource_scope}'='staff_simulation'
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,source_scope,mission_id}'='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,location_id}'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,release_sha256}'=peer_wc.release_sha256
 AND peer_wc.contract#>>'{source_attestation,execution_authority,binding_sha256}'=peer_wc.definition_sha256
 AND (peer_rr.revision_sha256=peer_wc.release_sha256 OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND ((CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='7ce1a932-d339-5914-93d1-3f4698686c2c' OR (CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='e3579a26-560d-5d1d-bfbd-649df53a73c7' OR (CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='a85c7787-7cd4-4998-9ecc-8086e2c84d7b' OR (CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='b2fc5e28-072b-41f2-8dd8-cb5a35a13092')
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,admission,grant_id}'=peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,grant_id}' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND ((w.kind='director' AND w.payload->>'schema_version'='mission-director-work/4' AND w.payload#>>'{peer_confirmation,schema_version}'='mission-peer-confirmation-contract/2') OR(w.kind='narration' AND w.payload->>'schema_version'='mission-generic-narration/4' AND w.payload->>'mode'='unified' AND w.payload#>>'{role_interpretation,schema_version}'='mission-role-interpretation/4' AND w.payload#>>'{role_disposition,schema_version}'='mission-role-disposition/4'))) THEN SQLERRM
   WHEN SQLSTATE IN('P0001','40001','42501') AND SQLERRM IN('C1266_PEER_BATCH_PROVENANCE','C1266_PEER_CONTRACT_BINDING','C1266_PEER_EVIDENCE_BINDING','C1266_PEER_FEATURE_SCOPE','C1266_PEER_INTERPRETATION_VERSION_REQUIRED','C1266_PEER_NULL_REQUIRED','C1266_PEER_ORDER_BINDING','C1266_PEER_ORDER_COVERAGE','C1266_PEER_OWN_MOVEMENT_REQUIRED','C1266_PEER_REFERENCE_BINDING','C1266_PEER_REFERENCE_SHAPE','C1266_PEER_SUBMISSION_ORDER_BINDING','C1266_PEER_TEMPORAL_SHAPE')
    AND EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 peer_wc
 JOIN mission_factory_owner.editor_release_readiness peer_rr ON peer_rr.singleton
 WHERE peer_wc.work_id=w.id AND peer_wc.master_session_id=w.master_session_id AND peer_wc.scope='staff_mission'
 AND peer_wc.contract_sha256=public.combat_v2_sha256(peer_wc.contract)
 AND peer_wc.contract->>'schema_version'='mission-narrative-admission/3'
 AND peer_wc.contract->'features' ? 'role_intents_v2'
 AND peer_wc.contract->'features' ? 'execution_authority_v1'
 AND peer_wc.contract#>>'{source_attestation,role_intents,schema_version}'='mission-role-intent-attestation/3'
 AND peer_wc.contract#>>'{source_attestation,role_intents,temporal_contract_sha256}'='3fdeaa942bcf3ba217a976f7b0896f4594721fa45cde9ff8ed7bddf15391feda'
 AND peer_wc.contract#>>'{source_attestation,role_intents,peer_confirmation,schema_version}'='mission-peer-confirmation-contract/1'
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,schema_version}'='c1266-work-execution-attestation/1' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND peer_wc.contract#>>'{source_attestation,execution_authority,execution_context}'='staff_mission'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,kind}'='staff_finite'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,resource_scope}'='staff_simulation'
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,source_scope,mission_id}'='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,location_id}'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,release_sha256}'=peer_wc.release_sha256
 AND peer_wc.contract#>>'{source_attestation,execution_authority,binding_sha256}'=peer_wc.definition_sha256
 AND (peer_rr.revision_sha256=peer_wc.release_sha256 OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND ((CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='bedc09e2-559b-586d-a38b-cd600b419cd3' OR (CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='4c316c8c-3d92-5757-815e-dedcb0ac2f24')
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,admission,grant_id}'=peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,grant_id}' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND ((w.kind='director' AND w.payload->>'schema_version'='mission-director-work/4' AND w.payload#>>'{peer_confirmation,schema_version}'='mission-peer-confirmation-contract/1') OR(w.kind='narration' AND w.payload->>'schema_version'='mission-generic-narration/4' AND w.payload->>'mode'='unified' AND w.payload#>>'{role_interpretation,schema_version}'='mission-role-interpretation/3' AND w.payload#>>'{role_disposition,schema_version}'='mission-role-disposition/3'))) THEN SQLERRM
   else null end;
  ok:=false;msg:=null;cr:=null;publication:=null;
 end;
 if mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR c726_factory_settlement OR mission_generic_owner.c758_admission_proof_v1(w.master_session_id) then
   select enabled into strict shared_on from staff_ai_quota_private.runtime where singleton;
   select * into shared_call from staff_ai_quota_private.calls
       where producer='mission_generic_ai' and source_id=d.id and call_no=1
         and scope_id=w.master_session_id for update;
   if shared_call.id is not null then
     if shared_call.state='reserved' and p_result->>'provider_calls'='0' then
       perform staff_ai_quota_private.no_http(shared_call.id);
       actual:=0;basis:='exact';
     elsif shared_call.state='sent' and basis='exact'
       and p_result->>'provider_calls'='1' then
       perform staff_ai_quota_private.settle(shared_call.id,
         (metrics->>'input_tokens')::integer,(metrics->>'output_tokens')::integer);
     elsif shared_call.state in('sent','unknown_billable') then
       perform staff_ai_quota_private.unknown_billable(shared_call.id);
     else
       raise exception 'STAFF_GENERIC_SETTLEMENT_STATE' using errcode='40001';
     end if;
   elsif shared_on then
     raise exception 'STAFF_GENERIC_SETTLEMENT_MISSING' using errcode='40001';
   end if;
 end if;
 update mission_narrative_internal.dispatch_attempts set status=case when basis='exact' then 'success' else 'unknown_billable' end,
  actual_cost_usd=actual,cost_basis=basis,input_tokens=case when basis='exact' then (metrics->>'input_tokens')::int end,
  output_tokens=case when basis='exact' then (metrics->>'output_tokens')::int end,reasoning_tokens=case when basis='exact' then (metrics->>'reasoning_tokens')::int end,
  total_tokens=case when basis='exact' then (metrics->>'total_tokens')::int end,finalized_at=clock_timestamp() where id=a.id;
 update mission_narrative_internal.dispatch_receipts set status=case when basis='exact' then 'success' else 'unknown_billable' end,
  charged_cost_usd=actual,lease_token_sha256=null,lease_expires_at=null,finalized_at=clock_timestamp(),updated_at=clock_timestamp() where id=d.id;
 update mission_narrative_internal.provider_authorizations set finalize_token_sha256=null where id=z.id;
 update mission_generic_owner.work_items set state=case when outcome_uncertain then 'uncertain' when ok then 'completed' else 'failed' end,result=p_result,result_sha256=case
    when ok and msg is not null and w.kind='narration'
      and w.payload->>'schema_version'='mission-generic-narration/4'
    then public.combat_v2_sha256(p_result)
    else p_result_sha end,

  receipt_id=receipt,message_id=msg,finalized_at=clock_timestamp() where id=w.id returning * into w;
 if stale_role then
   if w.kind='director' then
     update mission_generic_owner.unified_source_windows
       set superseded_at=clock_timestamp(),superseded_reason='role_revision_changed'
       where work_id=w.id and consumed_message_id is null and superseded_at is null;
   elsif w.kind='narration' then
     update mission_generic_owner.unified_source_windows uw
       set superseded_at=clock_timestamp(),superseded_reason='role_revision_changed'
       from mission_generic_owner.unified_batches ub
       where ub.id=w.authority_receipt_id and uw.id=ub.source_window_id
         and uw.consumed_message_id is null and uw.superseded_at is null;
   end if;
 end if;

 insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) values(d.id,'generic_finalized',jsonb_build_object(
  'work_id',w.id,'receipt_id',receipt,'message_id',msg,'result_jsonb_sha256',public.combat_v2_sha256(p_result),'result_sha256',p_result_sha,
  'command_receipt',cr,'cost_basis',basis,'stale',stale,'state',w.state,
  'outcome_uncertain',outcome_uncertain,'application_error_sqlstate',application_error,
  'application_error_code',application_error_code));
 return mission_generic_owner.work_status(w);
end;
$function$

CREATE OR REPLACE FUNCTION mission_public_owner.work_contract_issue_v1(p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w mission_generic_owner.work_items;b mission_generic_owner.run_bindings;
 a mission_public_owner.session_admissions_v1;q mission_factory_owner.quest_run_sources;
 pub mission_factory_owner.publications;source_scope text;release_sha text;profile text;
 q49 jsonb;source_attestation jsonb;payload_version text;features jsonb:='[]'::jsonb;doc jsonb;old jsonb;ignored jsonb;c5_proof jsonb;c5_native jsonb;c5_stamp jsonb;
begin
 select * into strict w from mission_generic_owner.work_items where id=p_work for update;
 old:=mission_public_owner.work_contract_v1(w.id);
 if old is not null then return old;end if;
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) THEN
  c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
  c5_native:=mission_generic_owner.c1266_native_start_v1(w.master_session_id,false,true);
  IF c5_proof IS NULL OR c5_native IS NULL THEN RAISE EXCEPTION 'C1266_NARRATIVE5_ISSUE_CLOSED' USING ERRCODE='42501';END IF;
  release_sha:=c5_proof->>'release_sha256';source_scope:=CASE WHEN c5_proof#>>'{admission,resource_scope}'='world' THEN 'public_mission' ELSE 'staff_mission' END;
  c5_stamp:=jsonb_build_object('schema_version','c1266-work-execution-attestation/1','execution_context',c5_proof->>'execution_context',
   'admission',c5_proof->'admission','release_sha256',release_sha,'binding_sha256',c5_proof->>'binding_sha256',
   'financial_qualification_sha256',c5_proof->>'financial_qualification_sha256','c7_budget_qualification_sha256',c5_proof->>'c7_budget_qualification_sha256',
   'start_receipt_id',c5_native->>'start_receipt_id','start_snapshot_sha256',c5_native#>>'{eligibility,board_snapshot_sha256}',
   'source_scope',(SELECT canonical_preimage::jsonb#>'{config,c1266_opening,source_scope}' FROM mission_factory_owner.editor_release_readiness WHERE singleton));
 q49:=mission_generic_owner.c1266_staff_source_scope_v1(w.master_session_id);
 IF q49 IS NOT NULL THEN
 c5_stamp:=c5_stamp||jsonb_build_object('schema_version','c1266-work-execution-attestation/2','source_scope',q49->'source_scope','source_qualification',q49,'source_qualification_sha256',public.combat_v2_sha256(q49));
 END IF;
 q49:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
 IF q49 IS NOT NULL THEN
  c5_stamp:=c5_stamp||jsonb_build_object('schema_version','c1266-work-execution-attestation/3','source_scope',q49->'source_scope','source_qualification',q49,'source_qualification_sha256',public.combat_v2_sha256(q49));
 END IF;
 ELSIF mission_generic_owner.c1266_role_scope_v1(w.master_session_id,true) THEN
  ignored:=mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true);
  release_sha:=ignored->>'release_sha256';source_scope:='staff_mission';
 ELSIF exists(select 1 from mission_factory_owner.quest_run_sources qs where qs.session_id=w.master_session_id and qs.availability_scope='public' and qs.state in('prepared','opening_pending','uncertain','started')) then
  ignored:=mission_factory_owner.quest_run_source_assert_v1(w.master_session_id);
  select * into strict q from mission_factory_owner.quest_run_sources where session_id=w.master_session_id;
  release_sha:=q.public_release_sha256;source_scope:='public_quest';
 elsif mission_public_owner.role_session_allowed_v1(w.master_session_id) then
  select * into strict a from mission_public_owner.session_admissions_v1 where master_session_id=w.master_session_id;
  release_sha:=a.release_sha256;source_scope:='public_mission';
 elsif exists(select 1 from mission_launch_owner.dual_decisions d
  join mission_launch_owner.dual_scopes s on s.mission_id=d.mission_id and s.activation_id=d.activation_id
  where d.master_session_id=w.master_session_id) then
  ignored:=mission_public_owner.launch_provenance_v1(w.master_session_id);
  if ignored->>'availability_scope' is distinct from 'staff'
  then raise exception 'NARRATIVE_STAFF_LAUNCH_PROVENANCE' using errcode='42501';end if;
  release_sha:=ignored->>'release_sha256';source_scope:='staff_mission';
 elsif exists(select 1 from mission_factory_owner.quest_run_sources qs
  join public.master_v2_sessions ms on ms.id=qs.session_id
  join public.locations l on l.id=ms.location_id
  where qs.session_id=w.master_session_id and l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   and l.is_active and l.is_test and ms.owner_kind='ai_service' and ms.mission_id is null
   and ms.closed_at is null and ms.suspended_at is null
   and qs.state in('prepared','opening_pending','uncertain','started')) then
  -- Same authoritative Factory assertion, not a second Quest engine.
  ignored:=mission_factory_owner.quest_run_source_assert_v1(w.master_session_id);
  select * into strict q from mission_factory_owner.quest_run_sources where session_id=w.master_session_id;
  select p.* into strict pub from mission_public_owner.publications_v2 p
   join mission_factory_owner.quest_arcs arc on arc.publication_request=p.request_key where arc.id=q.arc_id;
  if pub.target<>'staff' or pub.state<>'staff' or pub.quest_arc_id is distinct from q.arc_id
  then raise exception 'NARRATIVE_QUEST_PUBLICATION_SCOPE' using errcode='42501';end if;
  release_sha:=pub.release_revision_sha256;source_scope:='staff_quest';
 else return null;end if;
 if w.state<>'ready' or w.kind not in('director','narration','choice')
 or w.payload_sha256 is distinct from public.combat_v2_sha256(w.payload)
 then raise exception 'NARRATIVE_WORK_CONTRACT_SOURCE' using errcode='40001';end if;
 select * into strict b from mission_generic_owner.run_bindings where master_session_id=w.master_session_id;
 if b.snapshot_sha256 is distinct from w.definition_sha256
 or b.snapshot_sha256 is distinct from mission_internal.fingerprint(b.snapshot)
 then raise exception 'NARRATIVE_WORK_CONTRACT_BINDING' using errcode='40001';end if;
 payload_version:=w.payload->>'schema_version';
 profile:=case when w.kind in('narration','director') then 'cinematic_master_1' else 'legacy' end;
 if w.kind='director' and (payload_version in('mission-director-work/1','mission-director-work/2','mission-director-work/3') OR(payload_version='mission-director-work/4' AND mission_generic_owner.c1266_role_scope_v2(w.master_session_id,true) AND mission_generic_owner.c1266_role_work_attest_v2(w.id) IS NOT NULL)) then
  if not exists(select 1 from mission_generic_owner.unified_source_windows sw
   where sw.id=w.authority_receipt_id and sw.master_session_id=w.master_session_id
    and sw.work_id=w.id and sw.definition_sha256=w.definition_sha256
    and sw.step_key=w.step_key and sw.run_control_version=w.run_control_version)
  then raise exception 'NARRATIVE_DIRECTOR_SOURCE_RECEIPT' using errcode='40001';end if;
  features:=jsonb_build_array('director_progression','speech_intent');
 elsif w.kind='narration' and payload_version in('mission-generic-narration/3','mission-generic-narration/4') then
  if not exists(select 1 from mission_generic_owner.unified_batches ub
   where ub.id=w.authority_receipt_id and ub.master_session_id=w.master_session_id
    and ub.writer_work_id=w.id and ub.payload_sha256=w.payload_sha256
    and ub.state='ready')
  then raise exception 'NARRATIVE_WRITER_BATCH_RECEIPT' using errcode='40001';end if;
  features:=jsonb_build_array(case payload_version when 'mission-generic-narration/3'
    then 'unified_narration_v3' else 'segmented_narration_v4' end);
 elsif w.kind='narration' and payload_version in('mission-generic-narration/1','mission-generic-narration/2') then
  if jsonb_array_length(coalesce(w.payload->'roleless_declarations','[]'::jsonb))>0 then
   raise exception 'NARRATIVE_ROLELESS_REQUIRES_NATIVE_UNIFIED_ROUTE' using errcode='55000';end if;
 elsif w.kind<>'choice' then
  raise exception 'NARRATIVE_WORK_PROFILE_UNSUPPORTED' using errcode='55000';
 end if;
 source_attestation:=mission_public_owner.narrative_source_attest_v1(w.id)||jsonb_build_object('master_session_id',w.master_session_id,'definition_sha256',w.definition_sha256,'release_sha256',release_sha);
 IF source_attestation#>>'{role_intents,schema_version}' IN('mission-role-intent-attestation/2','mission-role-intent-attestation/3','mission-role-intent-attestation/4') THEN
  IF source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/4' AND(source_scope IS DISTINCT FROM 'staff_mission' OR source_attestation#>>'{role_intents,temporal_contract_sha256}' IS DISTINCT FROM '0603ab23e76750b5babeb41421bc84b551b959945f21267ffd7169140732f1e8' OR source_attestation#>>'{role_intents,peer_confirmation,schema_version}' IS DISTINCT FROM 'mission-peer-confirmation-contract/2') THEN RAISE EXCEPTION 'C1266_PEER_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  IF source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/3' AND (source_scope IS DISTINCT FROM 'staff_mission' OR source_attestation#>>'{role_intents,temporal_contract_sha256}' IS DISTINCT FROM '3fdeaa942bcf3ba217a976f7b0896f4594721fa45cde9ff8ed7bddf15391feda' OR source_attestation#>>'{role_intents,peer_confirmation,schema_version}' IS DISTINCT FROM 'mission-peer-confirmation-contract/1') THEN RAISE EXCEPTION 'C1266_PEER_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  IF NOT mission_generic_owner.c1266_role_scope_v2(w.master_session_id,true) OR (source_scope IS DISTINCT FROM 'staff_mission' AND c5_proof IS NULL) THEN RAISE EXCEPTION 'C1266_TEMPORAL_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  features:=features||jsonb_build_array('role_intents_v2');
 ELSIF source_attestation->'role_intents' IS NOT NULL THEN
  IF NOT mission_generic_owner.c1266_role_scope_v1(w.master_session_id,true)
   OR (source_scope IS DISTINCT FROM 'staff_mission' AND c5_proof IS NULL)
  THEN RAISE EXCEPTION 'C1266_ROLE_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  features:=features||jsonb_build_array('role_intents_v1');
 END IF;
 if jsonb_typeof(source_attestation->'peaceful_exit')='object' then features:=features||jsonb_build_array('peaceful_exit_v1');end if;
 if jsonb_array_length(source_attestation->'continuity_sources')>0 then
  features:=features||jsonb_build_array('continuity_sources_v1');
 end if;
 -- peaceful_exit is not inferred from the profile, caller or an arbitrary UUID.
 -- It requires a separate native legal capability; none is minted here.
 IF c5_stamp IS NOT NULL THEN source_attestation:=source_attestation||jsonb_build_object('execution_authority',c5_stamp);features:=features||jsonb_build_array('execution_authority_v1');END IF;
 IF source_scope='staff_mission' AND c5_stamp IS NOT NULL
  AND mission_generic_owner.manual_staff_scope_v1(w.master_session_id) IS NOT NULL
  AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness r WHERE r.singleton AND r.state='enabled'
    AND r.revision_sha256=r.observed_revision_sha256
    AND r.canonical_preimage::jsonb#>>'{config,c1266_free_narrative,enabled}'='true'
    AND r.canonical_preimage::jsonb#>>'{config,c1266_free_narrative,master_session_id}'=w.master_session_id::text)
  AND (w.kind='director' OR(w.kind='narration' AND payload_version='mission-generic-narration/4')) THEN
  features:=features||jsonb_build_array('provider_output_retention_v1');
  IF w.kind='narration' THEN features:=features||jsonb_build_array('free_narrative_v1');END IF;
 END IF;
 doc:=jsonb_build_object('schema_version',case when c5_proof IS NOT NULL OR source_scope='public_quest' then 'mission-narrative-admission/3' else 'mission-narrative-admission/2' end,'scope',source_scope,
  'release_sha256',release_sha,'work_id',w.id,'master_session_id',w.master_session_id,
  'definition_sha256',w.definition_sha256,'payload_sha256',w.payload_sha256,
  'payload_schema_version',payload_version,'editorial_profile',profile,'features',features,'source_attestation',source_attestation);
 insert into mission_public_owner.work_contracts_v1(work_id,master_session_id,scope,release_sha256,
 definition_sha256,payload_sha256,contract,contract_sha256)
 values(w.id,w.master_session_id,source_scope,release_sha,w.definition_sha256,w.payload_sha256,doc,public.combat_v2_sha256(doc));
 return doc;
end $function$

CREATE OR REPLACE FUNCTION mission_public_owner.work_contract_v1(p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE wc mission_public_owner.work_contracts_v1;w mission_generic_owner.work_items;
 a jsonb;descriptor jsonb;path text[];actual jsonb;node jsonb;seen text[]:='{}'::text[];
BEGIN
 SELECT * INTO wc FROM mission_public_owner.work_contracts_v1 WHERE work_id=p_work;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work;
 IF (wc.master_session_id,wc.definition_sha256,wc.payload_sha256)
  IS DISTINCT FROM (w.master_session_id,w.definition_sha256,w.payload_sha256)
 OR wc.contract_sha256 IS DISTINCT FROM public.combat_v2_sha256(wc.contract)
 OR w.payload_sha256 IS DISTINCT FROM public.combat_v2_sha256(w.payload)
 THEN RAISE EXCEPTION 'NARRATIVE_WORK_CONTRACT_DRIFT' USING ERRCODE='40001'; END IF;
 IF NOT(wc.contract->'features' ? 'execution_authority_v1') AND (wc.scope='public_quest') IS DISTINCT FROM (wc.contract->>'schema_version'='mission-narrative-admission/3') THEN RAISE EXCEPTION 'NARRATIVE_ADMISSION_SCOPE_VERSION' USING ERRCODE='40001';END IF;
 IF wc.contract->>'schema_version' IN('mission-narrative-admission/2','mission-narrative-admission/3') THEN
  a:=wc.contract->'source_attestation';
  IF jsonb_typeof(a) IS DISTINCT FROM 'object'
   OR a->>'schema_version' IS DISTINCT FROM 'mission-narrative-source-attestation/1'
   OR (a->>'work_id',a->>'master_session_id',a->>'definition_sha256',a->>'payload_sha256',a->>'release_sha256',a->>'authority_receipt_id')
    IS DISTINCT FROM (w.id::text,w.master_session_id::text,w.definition_sha256,w.payload_sha256,wc.release_sha256,w.authority_receipt_id::text)
   OR jsonb_typeof(a->'continuity_sources') IS DISTINCT FROM 'array'
   OR jsonb_typeof(a->'director_progression_sources') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'NARRATIVE_ATTESTATION_BINDING' USING ERRCODE='40001'; END IF;
  FOR descriptor IN SELECT value FROM jsonb_array_elements(a->'continuity_sources') LOOP
   IF jsonb_typeof(descriptor->'path') IS DISTINCT FROM 'array'
   THEN RAISE EXCEPTION 'NARRATIVE_CONTINUITY_PATH_SHAPE'; END IF;
   SELECT coalesce(array_agg(value ORDER BY ordinality),'{}'::text[]) INTO path
    FROM jsonb_array_elements_text(descriptor->'path') WITH ORDINALITY;
   IF w.kind<>'narration' OR NOT (
    (cardinality(path)=0 AND w.payload->>'schema_version' IN ('mission-generic-narration/1','mission-generic-narration/2'))
    OR (w.payload->>'schema_version' IN ('mission-generic-narration/3','mission-generic-narration/4') AND (
      (cardinality(path)=1 AND path[1] IN ('mission_context','source_context'))
      OR (cardinality(path) IN (2,3) AND path[1]='resolved_scenes' AND path[2]~'^[0-9]+$'
        AND (cardinality(path)=2 OR path[3]='native_scene')))))
   OR path::text=ANY(seen)
   THEN RAISE EXCEPTION 'NARRATIVE_CONTINUITY_PATH_FORBIDDEN' USING ERRCODE='42501'; END IF;
   seen:=array_append(seen,path::text);node:=w.payload#>path;
   actual:=mission_public_owner.continuity_node_attest_v1(node,path,descriptor->>'shape');
   IF actual IS NULL OR actual IS DISTINCT FROM descriptor
   THEN RAISE EXCEPTION 'NARRATIVE_CONTINUITY_NODE_DRIFT' USING ERRCODE='40001'; END IF;
  END LOOP;
  IF (jsonb_array_length(a->'continuity_sources')>0) IS DISTINCT FROM (wc.contract->'features' ? 'continuity_sources_v1')
  THEN RAISE EXCEPTION 'NARRATIVE_CONTINUITY_FEATURE_DRIFT'; END IF;
  FOR descriptor IN SELECT value FROM jsonb_array_elements(a->'director_progression_sources') LOOP
   IF w.kind<>'director' OR descriptor->'path' IS DISTINCT FROM '["context","prior_progression"]'::jsonb
    OR descriptor->>'node_sha256' IS DISTINCT FROM public.combat_v2_sha256(w.payload#>'{context,prior_progression}')
   THEN RAISE EXCEPTION 'NARRATIVE_DIRECTOR_PROGRESSION_DRIFT' USING ERRCODE='40001'; END IF;
  END LOOP;
  IF jsonb_array_length(a->'director_progression_sources')>1
  THEN RAISE EXCEPTION 'NARRATIVE_DIRECTOR_PROGRESSION_MULTIPLE'; END IF;
  IF (jsonb_typeof(a->'peaceful_exit')='object') IS DISTINCT FROM (wc.contract->'features' ? 'peaceful_exit_v1')
  THEN RAISE EXCEPTION 'NARRATIVE_PEACEFUL_FEATURE_DRIFT'; END IF;
 END IF;
 IF wc.contract->'features' ? 'execution_authority_v1' THEN
  IF mission_generic_owner.c1266_historical_work_v1(w.id) IS NULL OR wc.scope NOT IN('staff_mission','public_mission') THEN RAISE EXCEPTION 'C1266_NARRATIVE5_HISTORY_BINDING' USING ERRCODE='40001';END IF;
 END IF;
 IF wc.contract->'features' ? 'role_intents_v2' THEN
  IF wc.contract->'features' ? 'role_intents_v1' OR (wc.scope IS DISTINCT FROM 'staff_mission' AND mission_generic_owner.c1266_historical_work_v1(w.id) IS NULL) OR wc.contract#>'{source_attestation,role_intents}' IS DISTINCT FROM mission_generic_owner.c1266_role_work_attest_v2(w.id) THEN RAISE EXCEPTION 'C1266_TEMPORAL_FEATURE_ATTESTATION_DRIFT' USING ERRCODE='40001';END IF;
 ELSIF wc.contract->'features' ? 'role_intents_v1' THEN
  IF (wc.scope IS DISTINCT FROM 'staff_mission' AND NOT(wc.contract->'features' ? 'execution_authority_v1'))
   OR wc.contract#>'{source_attestation,role_intents}' IS DISTINCT FROM mission_generic_owner.c1266_role_work_attest_v1(w.id)
  THEN RAISE EXCEPTION 'C1266_ROLE_FEATURE_ATTESTATION_DRIFT' USING ERRCODE='40001';END IF;
 ELSIF w.payload->>'schema_version' IN('mission-director-work/3','mission-director-work/4') OR w.payload ? 'role_interpretation' THEN
  RAISE EXCEPTION 'C1266_ROLE_FEATURE_REQUIRED' USING ERRCODE='42501';
 END IF;
 RETURN wc.contract;
END $function$

CREATE OR REPLACE FUNCTION public.mission_generic_staff_republish_failed_v1(p_session uuid, p_work uuid, p_staff uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  w mission_generic_owner.work_items;
  b mission_generic_owner.unified_batches;
  source_row mission_generic_owner.unified_source_windows;
  m public.master_v2_sessions;
  run_row public.mission_run_state;
  receipt mission_narrative_internal.dispatch_receipts;
  result_row jsonb;
  error_state text;
  error_message text;
  error_constraint text;
  error_table text;
  error_schema text;
  safe_code text;
  message_ref uuid;
  factory_cached boolean:=false;
  diagnostic_column text;
  diagnostic_context text;
  diagnostic_frames jsonb;
  successor mission_generic_owner.work_items;
  successor_id uuid;
  successor_event uuid;
  successor_key uuid;
begin
  perform mission_ai_board_owner.service_only();
  if p_session is null or p_work is null or p_staff is null then
    raise exception 'MCR_INPUT' using errcode='22023';
  end if;
  select * into strict m from public.master_v2_sessions where id=p_session;

  -- Named application recovery of an already charged successful Director.
  IF p_session='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND p_work='e366b9fa-54dc-4abd-8ba6-9ceee83be9a4'::uuid THEN
   PERFORM mission_generic_owner.dispatch_user(p_session,p_staff);
   IF p_staff<>'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_staff AND role IN('admin','master'))
    OR m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR m.owner_kind<>'ai_service' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
   THEN RAISE EXCEPTION 'RAW_RECOVERY_STAFF_SCOPE' USING ERRCODE='42501';END IF;
   PERFORM 1 FROM mission_generic_owner.role_window_cursors WHERE master_session_id=p_session FOR UPDATE;
   PERFORM public.master_v2_lock_scope(p_session);
   SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work AND master_session_id=p_session FOR UPDATE;
   IF NOT (w.id='e366b9fa-54dc-4abd-8ba6-9ceee83be9a4'::uuid AND w.master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid
 AND w.kind='director' AND w.state='failed' AND w.receipt_id='07366817-3bf6-4bad-8387-0a4c0d1804f7'::uuid
 AND w.dispatch_receipt_id='e9524086-1e03-42d8-866b-1c12eb77840a'::uuid
 AND w.payload_sha256='52ae7392cc038543f01c3a9d07532a292c6f9b7cf044d52b2ce2d0a9a7b77754'
 AND w.result_sha256='d0a4266f89198307e8c9020af67b4d2b099edc1cbf20e0aea5b38d1b78fc8ea9'
 AND public.combat_v2_sha256(w.result)='674c8253e511750022b6d9b477383aed5743ffb2c9ceee7b35a0125c10ac6201'
 AND w.result->>'ok'='true' AND w.result->>'provider_calls'='1' AND w.result->>'outcome_uncertain'='false'
 AND EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 wc WHERE wc.work_id=w.id AND wc.master_session_id=w.master_session_id
  AND wc.contract_sha256='0c4e3f0016df29ed7b740336e90ba58d6b1e8d72ac21ed144b9796d32073ecce'
  AND wc.contract_sha256=public.combat_v2_sha256(wc.contract) AND wc.release_sha256='e58e2e460469dced1c6efb98858b23f043fe8976988ae15bcb25525becc70cd8')
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts dr JOIN mission_narrative_internal.dispatch_audit ga ON ga.receipt_id=dr.id AND ga.event_code='generic_finalized'
  JOIN staff_ai_quota_private.calls q ON q.source_id=dr.id AND q.producer='mission_generic_ai' AND q.call_no=1 AND q.scope_id=w.master_session_id AND q.state='settled' AND q.charged_usd=dr.charged_cost_usd
  WHERE dr.id=w.dispatch_receipt_id AND dr.status='success' AND dr.dispatch_count=1 AND dr.finalized_at IS NOT NULL
   AND dr.master_session_id=w.master_session_id AND dr.authority_receipt_id=w.id AND dr.request_key=w.request_key
   AND ga.details->>'work_id'=w.id::text AND ga.details->>'receipt_id'=w.receipt_id::text
   AND ga.details->>'application_error_sqlstate'='54000' AND ga.details->'command_receipt'='null'::jsonb
   AND ga.details->>'stale'='false' AND ga.details->>'outcome_uncertain'='false'
   AND ga.details->>'result_sha256'=w.result_sha256 AND ga.details->>'result_jsonb_sha256'=public.combat_v2_sha256(w.result))
 AND EXISTS(SELECT 1 FROM mission_factory_owner.editor_release_readiness rr WHERE rr.singleton AND rr.state='enabled'
  AND rr.revision_sha256=rr.observed_revision_sha256 AND rr.revision_sha256=encode(extensions.digest(convert_to(rr.canonical_preimage,'UTF8'),'sha256'),'hex')
  AND rr.canonical_preimage::jsonb#>>'{config,c1266_raw_input_recovery,schema_version}'='c1266-raw-input-recovery/1'
  AND rr.canonical_preimage::jsonb#>>'{config,c1266_raw_input_recovery,failed_work_id}'=w.id::text
  AND rr.canonical_preimage::jsonb#>>'{config,c1266_raw_input_recovery,result_sha256}'=w.result_sha256
  AND rr.canonical_preimage::jsonb#>>'{config,c1266_raw_input_recovery,commit_source_md5}'=(SELECT md5(p.prosrc)FROM pg_proc p WHERE p.oid='mission_generic_owner.unified_director_commit(uuid,jsonb)'::regprocedure)
  AND rr.canonical_preimage::jsonb#>>'{config,c1266_raw_input_recovery,cached_source_md5}'=(SELECT md5(p.prosrc)FROM pg_proc p WHERE p.oid='public.mission_generic_staff_republish_failed_v1(uuid,uuid,uuid)'::regprocedure))) THEN RAISE EXCEPTION 'RAW_RECOVERY_RESULT_PROOF' USING ERRCODE='40001';END IF;
   SELECT * INTO b FROM mission_generic_owner.unified_batches WHERE decision_work_id=w.id;
   IF b.id IS NOT NULL AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_audit ra WHERE ra.receipt_id=w.dispatch_receipt_id AND ra.event_code='c1266_saved_director_applied' AND ra.details->>'batch_id'=b.id::text AND ra.details->>'writer_work_id'=b.writer_work_id::text AND ra.details->>'result_sha256'=w.result_sha256) THEN
    RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',b.writer_work_id,'replayed',true);
   END IF;
   IF b.id IS NOT NULL OR EXISTS(SELECT 1 FROM mission_generic_owner.work_items newer WHERE newer.master_session_id=p_session AND newer.created_at>w.created_at)
    OR EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE master_session_id=p_session AND closed_at IS NULL)
   THEN RAISE EXCEPTION 'RAW_RECOVERY_NEWER_WORK' USING ERRCODE='40001';END IF;
   SELECT * INTO STRICT source_row FROM mission_generic_owner.unified_source_windows WHERE id=w.authority_receipt_id AND work_id=w.id AND master_session_id=p_session FOR UPDATE;
   IF source_row.superseded_at IS NOT NULL OR source_row.consumed_message_id IS NOT NULL
    OR source_row.context->>'source_revision' IS DISTINCT FROM 'a0ba47902e6746a13c24ebae4e360db2e56dd64abad23483c09ba64411e11e51'
    OR source_row.context->>'source_revision' IS DISTINCT FROM mission_generic_owner.role_source_revision_v1(p_session)
    OR source_row.role_ids IS DISTINCT FROM ARRAY['cc335f44-c921-4b63-931d-464a59592db2'::uuid,'458c16cc-e747-49f7-9303-c81dd43cfb82'::uuid]
    OR EXISTS(SELECT 1 FROM unnest(source_row.role_ids) rid WHERE NOT EXISTS(SELECT 1 FROM mission_generic_owner.role_latest_v1(p_session) lr WHERE lr.message_id=rid AND lr.valid))
   THEN RAISE EXCEPTION 'RAW_RECOVERY_SOURCE_CHANGED' USING ERRCODE='40001';END IF;
   result_row:=mission_generic_owner.unified_director_commit(w.id,w.result->'decision');
   SELECT * INTO STRICT b FROM mission_generic_owner.unified_batches WHERE decision_work_id=w.id AND master_session_id=p_session;
   SELECT * INTO STRICT successor FROM mission_generic_owner.work_items WHERE id=b.writer_work_id AND kind='narration' AND state='ready' AND master_session_id=p_session AND authority_receipt_id=b.id;
   IF b.state<>'ready' OR b.message_id IS NOT NULL THEN RAISE EXCEPTION 'RAW_RECOVERY_WRITER_NOT_READY' USING ERRCODE='55000';END IF;
   INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)VALUES(w.dispatch_receipt_id,'c1266_saved_director_applied',jsonb_build_object('schema_version','c1266-saved-director-application/1','master_session_id',p_session,'work_id',w.id,'result_sha256',w.result_sha256,'batch_id',b.id,'writer_work_id',successor.id,'actor_user',p_staff,'generation_http_calls',0,'failed_work_preserved',true));
   RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',false);
  END IF;
  -- Count-overflow reissue is distinct from cached successful generation publication.

 if p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid AND p_work='c88958e7-8983-4332-a14e-095076f967f4'::uuid THEN
  PERFORM mission_generic_owner.dispatch_user(p_session,p_staff);
  IF p_staff NOT IN('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)
  OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_staff AND role IN('admin','master'))
  OR m.owner_kind<>'ai_service' OR m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
  OR mission_generic_owner.c726_factory_staff_runtime_v1(p_session) IS DISTINCT FROM TRUE
  OR mission_staff_abort_private.quiescent_v1(p_session) IS DISTINCT FROM TRUE
  THEN RAISE EXCEPTION 'C889_RECOVERY_SCOPE' USING ERRCODE='42501';END IF;
  PERFORM 1 FROM public.master_v2_sessions WHERE id=p_session FOR UPDATE;
  SELECT * INTO STRICT w FROM mission_generic_owner.work_items WHERE id=p_work AND master_session_id=p_session FOR UPDATE;
  successor_id:=md5('C889:work:'||w.id::text)::uuid;successor_event:=md5('C889:event:'||w.id::text)::uuid;successor_key:=md5('C889:request:'||w.id::text)::uuid;
  SELECT * INTO STRICT b FROM mission_generic_owner.unified_batches WHERE id=w.authority_receipt_id FOR UPDATE;
  IF b.writer_work_id=successor_id THEN
   SELECT * INTO STRICT successor FROM mission_generic_owner.work_items WHERE id=successor_id AND master_session_id=p_session AND authority_receipt_id=b.id AND payload=w.payload AND payload_sha256=w.payload_sha256 AND kind='narration' AND event_id=successor_event AND request_key=successor_key;
   RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor_id,'replayed',true);
  END IF;
  IF w.state<>'failed' OR w.result->>'schema_version'<>'mission-count-overflow-failure/1' OR w.result->>'provider_calls'<>'0' OR w.result->>'outcome_uncertain'<>'false'
  OR w.result_sha256<>public.combat_v2_sha256(w.result) OR w.authorization_id IS NOT NULL OR w.dispatch_id IS NOT NULL OR w.message_id IS NOT NULL
  OR NOT  EXISTS(SELECT 1 FROM mission_generic_owner.unified_batches native_batch_check
 WHERE native_batch_check.id=w.authority_receipt_id AND native_batch_check.id='32e674f6-f1b8-4273-973e-7da88ed2c5b9'::uuid
 AND native_batch_check.master_session_id=w.master_session_id AND native_batch_check.writer_work_id=w.id AND native_batch_check.state='ready' AND native_batch_check.message_id IS NULL
 AND native_batch_check.composition_kind='combat_resolved_no_pending' AND native_batch_check.source_window_id IS NULL AND native_batch_check.next_round_id IS NULL
 AND native_batch_check.encounter_id='28af57fd-aaea-4036-8881-e3df39e23092'::uuid AND native_batch_check.run_control_version=4
 AND native_batch_check.source_report_id='5b5f46db-c1e2-4ad6-b0f1-dc9563e81eb0'::uuid AND native_batch_check.secondary_report_id='a5355e32-d780-490d-97fa-2767af05db7f'::uuid
 AND native_batch_check.source_round_id='f7e9fdaf-8681-4034-ab96-3e668a176956'::uuid
 AND native_batch_check.payload=w.payload AND native_batch_check.payload_sha256=w.payload_sha256 AND w.payload_sha256=public.combat_v2_sha256(w.payload)
 AND w.payload->>'schema_version'='mission-generic-narration/3' AND w.payload->>'mode'='unified'
 AND w.payload->>'composition_kind'=native_batch_check.composition_kind AND w.payload->>'batch_id'=native_batch_check.id::text
 AND w.payload->>'preparation_receipt_id'=native_batch_check.id::text AND w.payload->>'next_state_receipt_id'=native_batch_check.id::text
 AND w.payload->'publication_barrier'=jsonb_build_object('closed',true,'required_receipt_ids',jsonb_build_array(native_batch_check.id,native_batch_check.source_report_id,native_batch_check.secondary_report_id),'receipt_ids',jsonb_build_array(native_batch_check.id,native_batch_check.source_report_id,native_batch_check.secondary_report_id))
 AND public.combat_v2_sha256(w.payload#>'{resolved_scenes,0}')='8ffc1e7abc84f8db7da30e3af234ab6e574106464cb760fa4204891291af3f53' AND public.combat_v2_sha256(w.payload#>'{resolved_scenes,1}')='37de1843c7c1967d25a564e2cd682bc2e4baae20d996aac647365529e0ae06bb' AND jsonb_array_length(w.payload->'resolved_scenes')=2 AND w.payload->'pending_offensives'='[]'::jsonb AND w.payload->'source_windows'='[]'::jsonb
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(w.payload->'resolved_scenes') item
 WHERE NOT EXISTS(SELECT 1 FROM public.combat_v2_round_reports rp JOIN public.combat_v2_rounds cr ON cr.id=rp.round_id
 WHERE rp.id=CASE WHEN (item#>>'{scene_binding,report_sha256}')=(SELECT mechanics_sha256 FROM public.combat_v2_round_reports WHERE id=native_batch_check.source_report_id) THEN native_batch_check.source_report_id ELSE native_batch_check.secondary_report_id END
 AND item->>'schema_version'='mission-generic-narration/2' AND item->>'mode'='combat'
 AND item#>>'{scene_binding,session_id}'=native_batch_check.encounter_id::text AND item#>>'{scene_binding,control_version}'=native_batch_check.run_control_version::text
 AND item#>>'{scene_binding,round_id}'=cr.id::text AND item#>>'{scene_binding,report_sha256}'=rp.mechanics_sha256
 AND item#>>'{scene,snapshot_sha256}'=public.combat_v2_sha256(item#>'{scene,snapshot}')
 AND item#>>'{scene_binding,scene_sha256}'=item#>>'{scene,snapshot_sha256}'
 AND item->'barrier'=jsonb_build_object('closed',true,'required_receipt_ids',jsonb_build_array(rp.id),'receipt_ids',jsonb_build_array(rp.id))
 AND cr.session_id=native_batch_check.encounter_id AND cr.report_id=rp.id AND cr.state='risolto' AND cr.resolved_at IS NOT NULL
 AND rp.narration_state='attesa' AND rp.mechanics_sha256=public.combat_v2_sha256(rp.mechanics) AND rp.values_written IS FALSE))
 AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_report_publications pub WHERE pub.report_id IN(native_batch_check.source_report_id,native_batch_check.secondary_report_id))
 AND public.combat_v2_values_written(native_batch_check.encounter_id) IS FALSE AND combat_panel_private.uses_simulated_pools(native_batch_check.encounter_id) IS TRUE
 AND EXISTS(SELECT 1 FROM public.mission_run_state r WHERE r.master_session_id=w.master_session_id AND r.run_phase='in_corso' AND r.current_step_key=native_batch_check.step_key AND r.control_version=native_batch_check.run_control_version)
 )
  OR NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts d JOIN mission_narrative_internal.dispatch_audit a ON a.receipt_id=d.id AND a.event_code='generic_count_overflow_terminal'
   WHERE d.id=w.dispatch_receipt_id AND d.status='failed' AND d.dispatch_count=0 AND d.charged_cost_usd=0 AND d.finalized_at IS NOT NULL
   AND a.details->>'work_id'=w.id::text AND a.details->>'receipt_id'=w.receipt_id::text AND a.details->>'result_sha256'=w.result_sha256 AND a.details->>'payload_sha256'=w.payload_sha256)
  THEN RAISE EXCEPTION 'C889_RECOVERY_BINDING' USING ERRCODE='40001';END IF;
  INSERT INTO mission_generic_owner.work_items(id,master_session_id,event_id,request_key,dedupe_key,step_key,run_control_version,definition_sha256,encounter_id,authority_receipt_id,kind,revision,payload,payload_sha256)
  VALUES(successor_id,p_session,successor_event,successor_key,'c889-count-reissue:'||w.id::text,w.step_key,w.run_control_version,w.definition_sha256,w.encounter_id,b.id,'narration',w.revision,w.payload,w.payload_sha256) RETURNING * INTO successor;
  UPDATE mission_generic_owner.unified_batches SET writer_work_id=successor_id WHERE id=b.id AND writer_work_id=w.id;
  IF NOT FOUND THEN RAISE EXCEPTION 'C889_WRITER_CAS' USING ERRCODE='40001';END IF;
  INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) VALUES(w.dispatch_receipt_id,'c889_count_narration_reissued',jsonb_build_object('schema_version','c889-native-report-reissue/1','old_work_id',w.id,'work_id',successor_id,'batch_id',b.id,'payload_sha256',w.payload_sha256,'generation_http_calls',0));
  RETURN jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor_id,'replayed',false);
 END IF;
  if p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid
    and p_work='42341080-7f78-494e-9adf-85de7cfce038'::uuid and exists(
    select 1 from mission_generic_owner.work_items ow where ow.id=p_work and ow.master_session_id=p_session
      and ow.kind='narration' and ow.state='failed'
      and ow.result->>'schema_version'='mission-count-overflow-failure/1') then
    perform mission_generic_owner.dispatch_user(p_session,p_staff);
    if p_staff not in('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)
    or m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid or m.owner_kind<>'ai_service'
    or m.closed_at is not null or m.suspended_at is not null
    or not exists(select 1 from public.profiles where id=p_staff and role in('admin','master'))
    or mission_generic_owner.c726_factory_staff_runtime_v1(p_session) is distinct from true
    or mission_staff_abort_private.quiescent_v1(p_session) is distinct from true
    or (mission_generic_owner.c7_run_budget_v1(p_session,true,null)->>'allowed') is distinct from 'true'
    then raise exception 'MCR_COUNT_SCOPE' using errcode='42501';end if;
    perform 1 from mission_generic_owner.role_window_cursors where master_session_id=p_session for update;
    if not found then raise exception 'MCR_CURSOR_MISSING' using errcode='55000';end if;
    perform 1 from public.master_v2_sessions where id=p_session for update;
    select * into strict w from mission_generic_owner.work_items where id=p_work and master_session_id=p_session for update;
    if w.payload_sha256<>public.combat_v2_sha256(w.payload) or w.result_sha256<>public.combat_v2_sha256(w.result)
    or w.authorization_id is not null or w.dispatch_id is not null or w.message_id is not null
    or w.finalized_at is null or w.receipt_id is null or w.result->>'provider_calls'<>'0'
    or w.result->>'outcome_uncertain'<>'false' or w.result->>'failure_code'<>'MISSION_INPUT_COUNT_OVERFLOW'
    or not exists(select 1 from mission_narrative_internal.dispatch_receipts d
       join mission_narrative_internal.dispatch_audit a on a.receipt_id=d.id and a.event_code='generic_count_overflow_terminal'
       where d.id=w.dispatch_receipt_id and d.authority_receipt_id=w.id and d.master_session_id=p_session
        and d.status='failed' and d.dispatch_count=0 and d.finalized_at is not null and d.charged_cost_usd=0
        and a.details->>'work_id'=w.id::text and a.details->>'receipt_id'=w.receipt_id::text
        and a.details->>'payload_sha256'=w.payload_sha256 and a.details->>'result_sha256'=w.result_sha256
        and a.details->>'generation_http_calls'='0')
    then raise exception 'MCR_COUNT_PROOF' using errcode='40001';end if;
    select * into strict b from mission_generic_owner.unified_batches where id=w.authority_receipt_id and master_session_id=p_session for update;
    select * into strict source_row from mission_generic_owner.unified_source_windows where id=b.source_window_id and master_session_id=p_session for update;
    select * into strict run_row from public.mission_run_state where master_session_id=p_session for update;
    successor_id:=md5('C1264:NARRATION:work:'||w.id::text)::uuid;
    successor_event:=md5('C1264:NARRATION:event:'||w.id::text)::uuid;
    successor_key:=md5('C1264:NARRATION:request:'||w.id::text)::uuid;
    if b.state<>'ready' or b.message_id is not null or source_row.superseded_at is not null or source_row.consumed_message_id is not null
    or b.payload is distinct from w.payload or b.payload_sha256<>w.payload_sha256
    or b.step_key<>w.step_key or b.run_control_version<>w.run_control_version
    or run_row.current_step_key<>w.step_key or run_row.control_version<>w.run_control_version or run_row.run_phase<>'in_corso'
    or w.payload->>'source_revision' is distinct from mission_generic_owner.role_source_revision_v1(p_session)
    or w.payload#>>'{publication_barrier,closed}' is distinct from 'true'
    or w.payload#>'{publication_barrier,required_receipt_ids}' is distinct from w.payload#>'{publication_barrier,receipt_ids}'
    or (w.payload#>'{publication_barrier,receipt_ids}' @> jsonb_build_array(b.id)) is distinct from true
    or exists(select 1 from mission_generic_owner.unified_segment_publications_v4 where work_id=w.id)
    or not exists(select 1 from mission_generic_owner.work_items dw where dw.id=b.decision_work_id and dw.kind='director'
      and dw.state='completed' and dw.result->>'ok'='true' and dw.result->'decision'=b.decision
      and b.decision_sha256=public.combat_v2_sha256(b.decision) and source_row.work_id=dw.id
      and source_row.source_sha256=dw.payload_sha256 and source_row.definition_sha256=w.definition_sha256)
    then raise exception 'MCR_COUNT_SOURCE_CHANGED' using errcode='40001';end if;
    if b.writer_work_id=successor_id then
      select * into strict successor from mission_generic_owner.work_items where id=successor_id;
      if successor.master_session_id<>p_session or successor.authority_receipt_id<>b.id or successor.kind<>'narration'
      or successor.event_id<>successor_event or successor.request_key<>successor_key
      or successor.payload is distinct from w.payload or successor.payload_sha256<>w.payload_sha256
      then raise exception 'MCR_COUNT_REPLAY_CHANGED' using errcode='40001';end if;
      return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',true);
    end if;
    if b.writer_work_id<>w.id then raise exception 'MCR_COUNT_WRITER_CHANGED' using errcode='40001';end if;
    insert into mission_generic_owner.work_items(id,master_session_id,event_id,request_key,dedupe_key,step_key,run_control_version,definition_sha256,encounter_id,authority_receipt_id,kind,revision,payload,payload_sha256)
    values(successor_id,p_session,successor_event,successor_key,'count-narration-reissue:'||w.id::text,w.step_key,w.run_control_version,w.definition_sha256,w.encounter_id,b.id,'narration',w.revision,w.payload,w.payload_sha256) returning * into successor;
    update mission_generic_owner.unified_batches set writer_work_id=successor.id where id=b.id and writer_work_id=w.id;
    if not found then raise exception 'MCR_COUNT_WRITER_CAS' using errcode='40001';end if;
    insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) values(w.dispatch_receipt_id,'generic_count_narration_reissued',jsonb_build_object('schema_version','c1264-count-narration-reissue/1','old_work_id',w.id,'work_id',successor.id,'batch_id',b.id,'source_window_id',b.source_window_id,'payload_sha256',w.payload_sha256,'actor_user',p_staff,'generation_http_calls',0));
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1','status','recovered','master_session_id',p_session,'work_id',successor.id,'replayed',false);
  end if;

  factory_cached:=p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid
   and p_work='86e5b361-9d82-aee8-a840-b09a83126fc0'::uuid
   and p_staff in('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)
   and mission_generic_owner.c726_factory_staff_runtime_v1(p_session) is true
   and (select count(*) from public.master_v2_participants where session_id=p_session and engagement_state='attivo' and left_at is null)=2
   and not exists(select 1 from public.master_v2_participants mp join public.characters ch on ch.id=mp.character_id
     where mp.session_id=p_session and mp.engagement_state='attivo' and mp.left_at is null
      and (ch.user_id is distinct from mp.user_id_snapshot or ch.user_id not in('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid)))
   and exists(select 1 from mission_generic_owner.run_bindings rb where rb.master_session_id=p_session
     and rb.snapshot_sha256='49817335c60ce9d4b47bc5d81c6950f622635c7fb232264ab54736349124f567'
     and rb.snapshot_sha256=mission_internal.fingerprint(rb.snapshot));
  if factory_cached then perform mission_generic_owner.dispatch_user(p_session,p_staff);end if;
  if m.location_id is distinct from '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
    or m.owner_kind <> 'ai_service' or m.closed_at is not null
    or not (mission_academy_owner.staff_carrier_runtime(p_session) or factory_cached)
    or not mission_generic_owner.flow_scope_enabled(p_session)
    or not exists(select 1 from public.profiles where id=p_staff and role in ('admin','master'))
    or combat_consumer_private.staff_test_allowed(m.location_id,array[p_staff],false) is distinct from true
  then raise exception 'MCR_STAFF_SCOPE' using errcode='42501'; end if;

  perform 1 from mission_generic_owner.role_window_cursors
    where master_session_id=p_session for update;
  if not found then raise exception 'MCR_CURSOR_MISSING' using errcode='55000'; end if;
  perform 1 from public.master_v2_sessions where id=p_session for update;
  select * into strict w from mission_generic_owner.work_items
    where id=p_work and master_session_id=p_session for update;
  if w.state='completed' and w.message_id is not null and exists(
    select 1 from mission_generic_owner.unified_segment_publications_v4
    where work_id=w.id and message_id=w.message_id) then
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
      'status','published','message_id',w.message_id,'replayed',true);
  end if;
  if w.kind<>'narration' or w.payload->>'schema_version'<>'mission-generic-narration/4'
    or w.state<>'failed' or w.result->>'ok'<>'true'
    or w.result->>'provider_calls'<>'1' or w.result->>'outcome_uncertain'<>'false'
    or w.result_sha256 !~ '^[0-9a-f]{64}$' or w.message_id is not null
  then return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
    'status','not_applicable'); end if;
  select * into strict b from mission_generic_owner.unified_batches
    where id=w.authority_receipt_id and master_session_id=p_session and writer_work_id=w.id for update;
  select * into strict source_row from mission_generic_owner.unified_source_windows
    where id=b.source_window_id and master_session_id=p_session for update;
  select * into strict run_row from public.mission_run_state
    where master_session_id=p_session for update;
  select * into strict receipt from mission_narrative_internal.dispatch_receipts
    where id=w.dispatch_receipt_id for share;
  if b.state<>'ready' or b.message_id is not null
    or source_row.superseded_at is not null or source_row.consumed_message_id is not null
    or run_row.run_phase<>'in_corso' or run_row.current_step_key<>w.step_key
    or run_row.control_version<>w.run_control_version
    or w.payload->>'source_revision' is distinct from mission_generic_owner.role_source_revision_v1(p_session)
    or w.payload is distinct from b.payload or w.payload_sha256<>b.payload_sha256
    or w.result->>'work_id' is distinct from w.id::text
    or w.result->>'master_session_id' is distinct from p_session::text
    or w.result->>'request_key' is distinct from w.request_key::text
    or w.result->>'payload_sha256' is distinct from w.payload_sha256
    or receipt.status<>'success' or receipt.finalized_at is null
    or receipt.charged_cost_usd is null
    or exists(select 1 from mission_generic_owner.unified_segment_publications_v4
      where work_id=w.id)
  then raise exception 'MCR_SOURCE_CHANGED' using errcode='40001'; end if;

  if factory_cached and not exists(
   select 1 from mission_narrative_internal.dispatch_receipts nd
   join mission_narrative_internal.dispatch_audit ga on ga.receipt_id=nd.id and ga.event_code='generic_finalized'
   join mission_narrative_internal.dispatch_audit cp on cp.receipt_id=nd.id and cp.event_code='c8_count_success'
   join mission_narrative_internal.provider_authorizations pa on pa.id=w.authorization_id and pa.receipt_id=nd.id
   join mission_narrative_internal.dispatch_attempts na on na.receipt_id=nd.id and na.id=pa.attempt_id
   join staff_ai_quota_private.calls qc on qc.source_id=nd.id and qc.producer='mission_generic_ai' and qc.call_no=1
   where nd.id=w.dispatch_receipt_id and nd.authority_receipt_id=w.id and nd.master_session_id=p_session
    and nd.request_key=w.request_key and nd.status='success' and nd.dispatch_count=1 and nd.finalized_at is not null
    and nd.charged_cost_usd is not null and nd.lease_token_sha256 is null and nd.lease_expires_at is null
    and na.status='success' and na.finalized_at is not null and na.cost_basis='exact'
    and na.actual_cost_usd=nd.charged_cost_usd and qc.scope_id=p_session and qc.state='settled' and qc.charged_usd=nd.charged_cost_usd
    and ga.details->>'work_id'=w.id::text and ga.details->>'receipt_id'=w.receipt_id::text
    and ga.details->>'state'='failed' and ga.details->>'outcome_uncertain'='false'
    and ga.details->>'application_error_sqlstate'='42703'
    and ga.details->>'result_sha256'=w.result_sha256
    and ga.details->>'result_jsonb_sha256'=public.combat_v2_sha256(w.result)
    and cp.details->>'work_id'=w.id::text and cp.details->>'state'='success'
    and cp.details->>'generation_allowed'='true' and cp.details->>'input_tokens'='10066'
    and cp.details->>'max_input_tokens'='12000'
    and w.authority_receipt_id='08512119-3bfd-4df7-adbc-0686f5edf5b7'::uuid
    and w.definition_sha256='49817335c60ce9d4b47bc5d81c6950f622635c7fb232264ab54736349124f567'
    and w.result->>'schema_version'='mission-generic-result/2' and jsonb_typeof(w.result->'segments')='array'
    and w.result->'text'='null'::jsonb
    and not exists(select 1 from mission_generic_owner.work_items other where other.master_session_id=p_session and other.state in('claimed','authorized','provider_started','uncertain'))
    and not exists(select 1 from mission_narrative_internal.dispatch_attempts pending join mission_narrative_internal.dispatch_receipts pd on pd.id=pending.receipt_id where pd.master_session_id=p_session and pending.finalized_at is null)
  ) then raise exception 'MCR_FACTORY_CACHED_RECEIPT' using errcode='40001';end if;
  perform mission_generic_owner.work_assert(w);

  begin
    update mission_generic_owner.work_items set state='provider_started',finalized_at=null
      where id=w.id and state='failed';
    result_row:=mission_generic_owner.unified_publish_v4(
      w.id,w.result,w.request_key,w.result_sha256);
    message_ref:=(result_row->>'message_id')::uuid;
    if message_ref is null then raise exception 'MCR_PUBLICATION_MISSING'; end if;
    update mission_generic_owner.work_items
      set state='completed',finalized_at=clock_timestamp(),message_id=message_ref,
        result=result||jsonb_build_object('text',result_row->>'text','continuity',result_row->'continuity'),
        result_sha256=public.combat_v2_sha256(result||jsonb_build_object(
          'text',result_row->>'text','continuity',result_row->'continuity'))
      where id=w.id and state='provider_started';
    if not found then raise exception 'MCR_WORK_CAS'; end if;
  exception when others then
    get stacked diagnostics error_state=returned_sqlstate,error_message=message_text,
      error_constraint=constraint_name,error_table=table_name,error_schema=schema_name,
      diagnostic_column=column_name,diagnostic_context=pg_exception_context;
    if factory_cached then
      if diagnostic_column !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then diagnostic_column:=null;end if;
      if diagnostic_column is null and error_state='42703' then
        diagnostic_column:=coalesce(
          substring(error_message from '^column "([A-Za-z_][A-Za-z0-9_]{0,62})" does not exist$'),
          substring(error_message from '^record "[A-Za-z_][A-Za-z0-9_]{0,62}" has no field "([A-Za-z_][A-Za-z0-9_]{0,62})"$'),
          substring(error_message from '^column [A-Za-z_][A-Za-z0-9_]{0,62}\.([A-Za-z_][A-Za-z0-9_]{0,62}) does not exist$'));
      end if;
      if error_table !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then error_table:=null;end if;
      if error_schema !~ '^[A-Za-z_][A-Za-z0-9_]{0,62}$' then error_schema:=null;end if;
      select coalesce(jsonb_agg(jsonb_build_object('function',parts[1],'line',parts[2]::integer) order by ordinal),'[]'::jsonb) into diagnostic_frames
        from (select parts,ordinal from regexp_matches(diagnostic_context,'PL/pgSQL function ([A-Za-z_][A-Za-z0-9_.]*)\([^)]*\) line ([0-9]{1,6})','g') with ordinality f(parts,ordinal) limit 8) frames;
    end if;
    safe_code:=case when error_message ~ '^[A-Z][A-Z0-9_]{1,79}$'
      then error_message else 'SQLSTATE_'||error_state end;
  end;
  if safe_code is not null then
    insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
      values(receipt.id,'staff_cached_publication_rejected',jsonb_build_object(
        'work_id',w.id,'master_session_id',p_session,
        'sqlstate',error_state,'error_code',safe_code,
        'constraint_name',nullif(error_constraint,''),
        'table_name',nullif(error_table,''),
        'schema_name',nullif(error_schema,'')) || case when factory_cached then jsonb_build_object('private_diagnostics',jsonb_build_object('schema_version','c1264-cached-private-error/1','column',diagnostic_column,'table',error_table,'schema',error_schema,'frames',diagnostic_frames)) else '{}'::jsonb end);
    return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
      'status','failed','error_code',safe_code);
  end if;
  insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
    values(receipt.id,'staff_cached_publication_completed',jsonb_build_object(
      'work_id',w.id,'master_session_id',p_session,'message_id',message_ref));
  return jsonb_build_object('schema_version','mission-generic-staff-cached-publication/1',
    'status','published','message_id',message_ref,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION mission_generic_owner.role_flow_status_v1(p_session uuid, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c mission_generic_owner.role_window_cursors%ROWTYPE;
        needed integer; received integer; own_role record; latest_work record;
        reason text; actor text; revision text;
BEGIN
  SELECT * INTO c FROM mission_generic_owner.role_window_cursors
    WHERE master_session_id = p_session;
  IF NOT FOUND THEN RETURN NULL; END IF;
  revision := mission_generic_owner.role_source_revision_v1(p_session);
  SELECT count(DISTINCT mp.user_id_snapshot) INTO needed
    FROM public.master_v2_participants mp
    JOIN public.characters ch ON ch.id = mp.character_id
      AND ch.user_id = mp.user_id_snapshot
    WHERE mp.session_id = p_session AND mp.left_at IS NULL
      AND mp.engagement_state = 'attivo';
  SELECT count(DISTINCT lr.user_id) INTO received
    FROM mission_generic_owner.role_latest_v1(p_session) lr
    JOIN public.master_v2_participants mp
      ON mp.session_id = p_session AND mp.user_id_snapshot = lr.user_id
      AND mp.character_id = lr.character_id AND mp.left_at IS NULL
      AND mp.engagement_state = 'attivo'
    WHERE lr.valid;
  SELECT * INTO own_role FROM mission_generic_owner.role_latest_v1(p_session) lr
    WHERE lr.user_id = p_user;
  SELECT wi.id, wi.state, wi.request_key, wi.lease_expires_at,
         uw.context->>'source_revision' AS source_revision
    INTO latest_work
    FROM mission_generic_owner.unified_source_windows uw
    LEFT JOIN LATERAL (
      SELECT ub.writer_work_id FROM mission_generic_owner.unified_batches ub
      WHERE ub.source_window_id=uw.id AND ub.writer_work_id IS NOT NULL
      ORDER BY ub.created_at DESC,ub.id DESC LIMIT 1
    ) active_batch ON true
    JOIN mission_generic_owner.work_items wi
      ON wi.id=coalesce(active_batch.writer_work_id,uw.work_id)
    WHERE uw.master_session_id = p_session AND uw.consumed_message_id IS NULL
      AND uw.superseded_at IS NULL
    ORDER BY uw.created_at DESC, uw.id DESC LIMIT 1;
  IF own_role.user_id IS NULL THEN
    reason := 'own_role_missing'; actor := 'player';
  ELSIF NOT own_role.valid THEN
    reason := 'own_role_invalid';
    actor := CASE WHEN own_role.invalid_reason='left_before_submission'
      THEN 'staff' ELSE 'player' END;
  ELSIF received < needed THEN
    reason := 'waiting_other_roles'; actor := 'other_players';
  ELSIF latest_work.id IS NULL THEN
    reason := 'ready_to_evaluate'; actor := 'system';
  ELSIF latest_work.source_revision IS DISTINCT FROM revision THEN
    reason := 'review_required'; actor := 'staff';
  ELSIF latest_work.state = 'uncertain'
    OR (latest_work.state IN ('claimed','authorized','provider_started')
        AND latest_work.lease_expires_at <= clock_timestamp()) THEN
    reason := 'uncertain'; actor := 'staff';
  ELSIF latest_work.state = 'failed' THEN
    reason := 'failed'; actor := 'staff';
  ELSIF latest_work.state = 'ready' THEN
    reason := 'recoverable_not_started'; actor := 'staff';
  ELSIF latest_work.state IN ('claimed','authorized','provider_started') THEN
    reason := 'provider_processing'; actor := 'system';
  ELSE
    reason := 'review_required'; actor := 'staff';
  END IF;
  RETURN jsonb_build_object('flow_reason',reason,'next_actor',actor,
    'roles_received',received,'roles_required',needed,
    'source_revision',revision,
    'flow_detail',CASE WHEN reason='own_role_invalid' THEN own_role.invalid_reason ELSE NULL END,
    'work_id',latest_work.id,'request_key',latest_work.request_key);
END;
$function$

CREATE OR REPLACE FUNCTION mission_generic_owner.unified_publish_v4(p_work uuid, p_result jsonb, p_request uuid, p_raw_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ww mission_generic_owner.work_items; ub mission_generic_owner.unified_batches;
        uw mission_generic_owner.unified_source_windows; mm public.master_v2_sessions;
        opp jsonb; part jsonb; body text:=''; txt text; route_result jsonb;
        source_kind text; role_ref uuid; role_actor uuid; role_sha text;
        out jsonb; memory jsonb; anchor jsonb; chain text; body_sha text;
        seg_sha text; msg uuid; pub uuid; tr mission_generic_owner.trigger_receipts;
        combat_open jsonb; offense_receipts jsonb; sealed_receipts jsonb;
        slot_count integer; prose_chars integer:=0; seen_slots text[]:='{}'::text[];
        slot_key text; slot_text text; offense_round uuid;
        ev public.mission_run_events; ob public.mission_run_outbox;
        literal_recovery boolean:=false;
BEGIN
  -- Named SQL maintenance authority: real postgres connection, no JWT impersonation.
  -- No client entry point, no retry state, no provider call.
  literal_recovery:=session_user='postgres' AND auth.uid() IS NULL
    AND coalesce(auth.role(),'')='' AND p_work='8da0b3ea-3de5-4f1c-9cf9-740b54a33647'::uuid;
  IF NOT literal_recovery THEN PERFORM mission_ai_board_owner.service_only(); END IF;
  -- Caller finalizer MUST hold role cursor before Master/work; this lock is
  -- reentrant and verifies the same role revision under serialization.
  PERFORM 1 FROM mission_generic_owner.role_window_cursors
    WHERE master_session_id=(SELECT master_session_id FROM mission_generic_owner.work_items WHERE id=p_work)
    FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MRS_V4_CURSOR_MISSING'; END IF;
  SELECT * INTO STRICT mm FROM public.master_v2_sessions
    WHERE id=(SELECT master_session_id FROM mission_generic_owner.work_items WHERE id=p_work)
    FOR UPDATE;
  SELECT * INTO STRICT ww FROM mission_generic_owner.work_items WHERE id=p_work FOR UPDATE;
 IF mission_generic_owner.c1266_opening_named_v1(ww.master_session_id) AND mission_generic_owner.c1266_execution_authority_v1(ww.master_session_id,false,true) IS NULL THEN RAISE EXCEPTION 'C1266_PUBLISH5_CURRENT_AUTHORITY' USING ERRCODE='42501';END IF;
  SELECT * INTO STRICT ub FROM mission_generic_owner.unified_batches
    WHERE id=ww.authority_receipt_id AND writer_work_id=ww.id FOR UPDATE;
  SELECT * INTO STRICT uw FROM mission_generic_owner.unified_source_windows
    WHERE id=ub.source_window_id FOR UPDATE;
  IF literal_recovery THEN
    IF (
      ww.id='8da0b3ea-3de5-4f1c-9cf9-740b54a33647'::uuid
      AND ww.master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid
      AND ww.kind='narration' AND ww.state='failed' AND ww.message_id IS NULL
      AND ww.finalized_at IS NOT NULL AND ww.result IS NOT DISTINCT FROM p_result
      AND ww.request_key IS NOT DISTINCT FROM p_request
      AND ww.result_sha256 IS NOT DISTINCT FROM p_raw_sha
      AND p_raw_sha='c540de05a0a5b7c5c3760b951b1d278863a5e13ce74c184f61106890e3cd8564'
      AND public.combat_v2_sha256(ww.result)='514156423647274196abccda69d8f7ac94fee2a949d026526d50027f3f6aba03'
      AND ww.result->>'ok'='true' AND ww.result->>'provider_calls'='1'
      AND ww.result->>'outcome_uncertain'='false'
      AND ww.result->>'work_id'=ww.id::text
      AND ww.result->>'master_session_id'=ww.master_session_id::text
      AND ww.result->>'request_key'=ww.request_key::text
      AND ww.result->>'payload_sha256'=ww.payload_sha256
      AND mm.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
      AND mm.owner_kind='ai_service' AND mm.closed_at IS NULL AND mm.stato='in_corso'
      AND EXISTS(SELECT 1 FROM public.locations l WHERE l.id=mm.location_id AND l.is_test AND l.is_active)
      AND EXISTS(SELECT 1 FROM mission_generic_owner.flow_staff_sessions f WHERE f.master_session_id=ww.master_session_id AND f.enabled)
      AND mission_generic_owner.manual_staff_scope_v1(ww.master_session_id) IS NOT NULL
      AND ub.id='5d54201e-913a-44c8-9d30-7fe776cf63aa'::uuid
      AND ub.master_session_id=ww.master_session_id AND ub.writer_work_id=ww.id
      AND ub.state='ready' AND ub.message_id IS NULL AND ub.route IS NULL
      AND ub.composition_kind='narrative_continuation'
      AND ub.encounter_key IS NULL AND ub.encounter_id IS NULL AND ub.next_round_id IS NULL
      AND ub.source_round_id IS NULL AND ub.entry_side IS NULL
      AND ub.decision->>'action_kind'='context' AND ub.decision->'opportunity_id'='null'::jsonb
      AND ww.payload->'offense_slots'='[]'::jsonb
      AND uw.master_session_id=ww.master_session_id
      AND uw.work_id='f470a88c-3e64-41be-9a1c-a9e627faef9c'::uuid
      AND uw.superseded_at IS NULL AND uw.consumed_message_id IS NULL
      AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items dw WHERE dw.id=uw.work_id
        AND dw.master_session_id=ww.master_session_id AND dw.kind='director' AND dw.state='completed')
      AND EXISTS(SELECT 1 FROM mission_generic_owner.role_window_cursors c WHERE c.master_session_id=ww.master_session_id
        AND c.window_epoch=1 AND c.role_revision=2)
      AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 x WHERE x.work_id=ww.id OR x.batch_id=ub.id)
      AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.staff_fato_revisions x WHERE x.work_id=ww.id)
      AND NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions cs WHERE cs.master_session_id=ww.master_session_id AND cs.closed_at IS NULL)
      AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts dr
        JOIN mission_narrative_internal.dispatch_audit ga ON ga.receipt_id=dr.id AND ga.event_code='generic_finalized'
        WHERE dr.id=ww.dispatch_receipt_id AND dr.authority_receipt_id=ww.id
          AND dr.master_session_id=ww.master_session_id AND dr.request_key=ww.request_key
          AND dr.status='success' AND dr.dispatch_count=1 AND dr.finalized_at IS NOT NULL
          AND dr.charged_cost_usd IS NOT NULL AND dr.lease_token_sha256 IS NULL AND dr.lease_expires_at IS NULL
          AND ga.details->>'work_id'=ww.id::text AND ga.details->>'receipt_id'=ww.receipt_id::text
          AND ga.details->>'state'='failed' AND ga.details->>'stale'='false'
          AND ga.details->>'outcome_uncertain'='false'
          AND ga.details->>'application_error_code'='MG_FATO_LITERAL_REPETITION'
          AND ga.details->>'application_error_sqlstate'='22023'
          AND ga.details->>'result_sha256'=ww.result_sha256
          AND ga.details->>'result_jsonb_sha256'=public.combat_v2_sha256(ww.result))
      AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items other
        WHERE other.master_session_id=ww.master_session_id AND other.id<>ww.id
          AND other.state IN('ready','claimed','authorized','provider_started','uncertain'))
      AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts da
        JOIN mission_narrative_internal.dispatch_receipts dr ON dr.id=da.receipt_id
        WHERE dr.master_session_id=ww.master_session_id AND da.finalized_at IS NULL)
    ) IS DISTINCT FROM TRUE THEN
      RAISE EXCEPTION 'C1266_LITERAL_RECOVERY_BINDING' USING ERRCODE='40001';
    END IF;
  END IF;
  IF ww.payload ? 'role_interpretation' THEN
   PERFORM mission_generic_owner.c1266_role_work_attest_dispatch_v2(ww.id);
   IF ww.payload->'role_interpretation' IS DISTINCT FROM ub.decision->'role_interpretation'
    OR ww.payload->'role_disposition' IS DISTINCT FROM ub.decision->'role_disposition'
    OR ww.payload#>'{role_disposition,effective_opportunity_id}' IS DISTINCT FROM ub.decision->'opportunity_id'
    OR (ww.payload#>>'{role_disposition,status}'='context_fallback' AND
      (ub.decision->>'action_kind'<>'context' OR ub.encounter_key IS NOT NULL OR ub.entry_side IS NOT NULL
       OR jsonb_array_length(ub.decision->'npc_intents')<>0))
   THEN RAISE EXCEPTION 'C1266_ROLE_PUBLISH_DISPOSITION_DRIFT' USING ERRCODE='40001';END IF;
  END IF;
  IF ww.payload->>'schema_version'<>'mission-generic-narration/4'
    OR (ww.state<>'provider_started' AND NOT literal_recovery) OR ww.request_key<>p_request
    OR ww.payload IS DISTINCT FROM ub.payload OR ww.payload_sha256<>ub.payload_sha256
    OR ub.state<>'ready'
    OR ub.source_window_id IS NULL OR uw.superseded_at IS NOT NULL
    OR uw.consumed_message_id IS NOT NULL
    OR ww.payload->>'source_revision' IS DISTINCT FROM mission_generic_owner.role_source_revision_v1(ww.master_session_id)
    OR ww.payload->>'source_revision' IS DISTINCT FROM uw.context->>'source_revision'
    OR p_result->>'schema_version'<>'mission-generic-result/2'
    OR p_result->>'runtime_version'<>'mission-generic-runtime/2'
    OR p_result->'text'<>'null'::jsonb
    OR jsonb_typeof(p_result->'segments')<>'array'
    OR jsonb_array_length(p_result->'segments')=0
    OR jsonb_typeof(ww.payload->'offense_slots')<>'array'
  THEN RAISE EXCEPTION 'MRS_V4_NONOFFENSIVE_BINDING' USING ERRCODE='40001'; END IF;
  slot_count:=jsonb_array_length(ww.payload->'offense_slots');
  IF slot_count>0 AND (ub.composition_kind<>'entry_png' OR ub.encounter_key IS NULL
    OR ub.entry_side<>'png' OR slot_count<>cardinality(ub.selected_actor_keys))
  THEN RAISE EXCEPTION 'MRS_V4_OFFENSE_SCOPE' USING ERRCODE='40001'; END IF;
  -- Validate source and work while run/step still match pre-transition state.
  PERFORM mission_generic_owner.work_assert(ww);
  IF mission_generic_owner.unified_batch_payload(ub.id) IS DISTINCT FROM ww.payload
  THEN RAISE EXCEPTION 'MRS_V4_PAYLOAD_DRIFT' USING ERRCODE='40001'; END IF;
  FOR part IN SELECT value FROM jsonb_array_elements(p_result->'segments') LOOP
    IF NOT mission_generic_owner.keys_valid(part,ARRAY['kind','text','slot_id','actor_key'])
    THEN RAISE EXCEPTION 'MRS_V4_SEGMENT_KEYS'; END IF;
    IF part->>'kind'='prose' THEN
      IF jsonb_typeof(part->'text')<>'string'
        OR part->'slot_id'<>'null'::jsonb OR part->'actor_key'<>'null'::jsonb
      THEN RAISE EXCEPTION 'MRS_V4_PROSE_SEGMENT_INVALID'; END IF;
      txt:=btrim(part->>'text');
      IF txt='' THEN RAISE EXCEPTION 'MRS_V4_EMPTY_SEGMENT'; END IF;
      prose_chars:=prose_chars+length(txt);
    ELSIF part->>'kind'='offense_slot' THEN
      slot_key:=part->>'slot_id';
      IF part->'text'<>'null'::jsonb OR slot_key IS DISTINCT FROM part->>'actor_key'
        OR slot_key !~ '^[a-z][a-z0-9_]{0,63}$'
        OR slot_key=ANY(seen_slots)
        OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ww.payload->'offense_slots') slot
           WHERE slot->>'slot_id'=slot_key AND slot->>'actor_key'=slot_key)
      THEN RAISE EXCEPTION 'MRS_V4_OFFENSE_SEGMENT_INVALID'; END IF;
      seen_slots:=array_append(seen_slots,slot_key);
    ELSE RAISE EXCEPTION 'MRS_V4_SEGMENT_KIND'; END IF;
  END LOOP;
  IF prose_chars<500 OR cardinality(seen_slots)<>slot_count
    OR seen_slots IS DISTINCT FROM coalesce((SELECT array_agg(slot->>'slot_id' ORDER BY slot->>'actor_key')
      FROM jsonb_array_elements(ww.payload->'offense_slots') slot),'{}'::text[])
  THEN RAISE EXCEPTION 'MRS_V4_SEGMENT_COHORT'; END IF;
  seg_sha:=public.combat_v2_sha256(p_result->'segments');
  anchor:=p_result->'history_anchor'; memory:=p_result->'continuity_draft';
  IF jsonb_typeof(anchor) IS DISTINCT FROM 'object'
    OR jsonb_typeof(memory) IS DISTINCT FROM 'object'
    OR anchor->>'chain_sha256' IS DISTINCT FROM ww.payload#>>'{source_context,history_chain_sha256}'
    OR (anchor->>'count')::bigint IS DISTINCT FROM (ww.payload#>>'{source_context,history_count}')::bigint
    OR NOT mission_generic_owner.keys_valid(memory,ARRAY['state','known','open','used'])
  THEN RAISE EXCEPTION 'MRS_V4_MEMORY_BINDING'; END IF;

  SELECT x INTO opp FROM jsonb_array_elements(uw.opportunities) x
    WHERE x->>'opportunity_id'=ub.decision->>'opportunity_id';
  IF opp IS NULL AND (
      ub.decision->>'opportunity_id' IS NOT NULL
      OR ub.decision->>'action_kind' IS DISTINCT FROM 'context'
      OR ub.composition_kind IS DISTINCT FROM 'narrative_continuation'
      OR ub.encounter_key IS NOT NULL OR ub.entry_side IS NOT NULL
    ) THEN RAISE EXCEPTION 'MRS_V4_OPPORTUNITY_MISSING'; END IF;
  IF opp->>'trigger_key' IS NOT NULL THEN
    source_kind:=opp->>'source_kind';
    IF source_kind='player_choice' THEN
      role_ref:=(ub.decision#>>'{source_evidence,0,role_id}')::uuid;
      SELECT rm.character_id,encode(extensions.digest(convert_to(rm.body,'UTF8'),'sha256'),'hex')
        INTO STRICT role_actor,role_sha FROM public.messages rm
        JOIN public.master_v2_participants mp
          ON mp.session_id=ww.master_session_id AND mp.character_id=rm.character_id
          AND mp.left_at IS NULL AND mp.engagement_state='attivo'
        JOIN public.characters ch ON ch.id=rm.character_id
          AND ch.user_id=mp.user_id_snapshot
        WHERE rm.id=role_ref AND rm.id=ANY(uw.role_ids)
          AND rm.location_id=mm.location_id AND rm.kind='say' AND rm.recipient_user IS NULL
          AND EXISTS(SELECT 1 FROM mission_generic_owner.role_latest_v1(ww.master_session_id) role_row
            WHERE role_row.message_id=rm.id AND role_row.valid)
          AND position(ub.decision#>>'{source_evidence,0,quote}' in rm.body)>0
          AND EXISTS(SELECT 1 FROM mission_generic_owner.role_submissions current_submission
            JOIN mission_generic_owner.role_window_cursors current_cursor
              ON current_cursor.master_session_id=current_submission.master_session_id
             AND current_cursor.window_epoch=current_submission.window_epoch
            WHERE current_submission.master_session_id=ww.master_session_id
              AND current_submission.message_id=rm.id);
    ELSIF source_kind='narrative_event' THEN
      role_ref:=ub.id;role_actor:=NULL;role_sha:=ub.decision_sha256;
    ELSE RAISE EXCEPTION 'MRS_V4_TRANSITION_KIND'; END IF;
    INSERT INTO mission_generic_owner.unified_publication_permits
      (batch_id,work_id,transaction_id,backend_pid)
    VALUES(ub.id,ww.id,txid_current(),pg_backend_pid());
    route_result:=mission_generic_owner.apply_authority(
      ww.master_session_id,mission_ai_service_owner.uuid5(ub.id,'transition'),
      mm.control_version,ww.run_control_version,opp->>'trigger_key',
      source_kind,role_ref,role_sha,role_actor);
    UPDATE mission_generic_owner.unified_batches SET route=route_result,
      step_key=(SELECT current_step_key FROM public.mission_run_state
        WHERE master_session_id=ww.master_session_id),
      run_control_version=(SELECT control_version FROM public.mission_run_state
        WHERE master_session_id=ww.master_session_id)
      WHERE id=ub.id;
    SELECT * INTO STRICT ub FROM mission_generic_owner.unified_batches WHERE id=ub.id;
  END IF;

  -- L'incontro e le offerte native restano invisibili finché questa
  -- transazione non pubblica l'unico Fato. Il trigger di round_init crea la
  -- finestra della coorte offensiva quando open_core inserisce il round.
  IF ub.encounter_key IS NOT NULL THEN
    IF ub.composition_kind NOT IN ('entry_pg','entry_png','entry_png_deferred')
      OR ub.encounter_id IS NOT NULL OR ub.next_round_id IS NOT NULL
    THEN RAISE EXCEPTION 'MRS_V4_COMBAT_ENTRY_ORDER'; END IF;
    UPDATE mission_generic_owner.unified_batches SET state='preparing' WHERE id=ub.id;
    IF EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources WHERE session_id=ub.master_session_id) THEN
      PERFORM mission_factory_owner.quest_entry_permit_issue_v1(ub.id,ww.id,
        mission_ai_service_owner.uuid5(ub.id,'open'),nullif(route_result->>'authority_receipt_id','')::uuid);
    END IF;
    combat_open:=public.mission_generic_combat_open_v1(
      ub.master_session_id,ub.encounter_key,ub.run_control_version,
      mission_ai_service_owner.uuid5(ub.id,'open'));
    UPDATE mission_generic_owner.unified_batches SET
      encounter_id=(combat_open->>'encounter_id')::uuid,
      next_round_id=(SELECT id FROM public.combat_v2_rounds
        WHERE session_id=(combat_open->>'encounter_id')::uuid
        ORDER BY round_no DESC LIMIT 1)
      WHERE id=ub.id;
    SELECT * INTO STRICT ub FROM mission_generic_owner.unified_batches WHERE id=ub.id;
    IF ub.encounter_id IS NULL OR ub.next_round_id IS NULL
    THEN RAISE EXCEPTION 'MRS_V4_COMBAT_ROUND_MISSING'; END IF;
    offense_round:=ub.next_round_id;
    IF slot_count>0 THEN
      offense_receipts:=mission_generic_owner.unified_stage_offense_v4(
        ub.id,ub.encounter_id,offense_round);
      IF offense_receipts->>'schema_version'<>'mission-entry-offense-receipts/1'
        OR offense_receipts->>'batch_id' IS DISTINCT FROM ub.id::text
        OR offense_receipts->>'encounter_id' IS DISTINCT FROM ub.encounter_id::text
        OR offense_receipts->>'round_id' IS DISTINCT FROM offense_round::text
        OR jsonb_array_length(offense_receipts->'slots')<>slot_count
      THEN RAISE EXCEPTION 'MRS_V4_NATIVE_OFFENSE_RECEIPT'; END IF;
    END IF;
  ELSIF slot_count>0 THEN
    RAISE EXCEPTION 'MRS_V4_OFFENSE_WITHOUT_COMBAT';
  END IF;

  -- Il provider non sceglie bersagli, offerte o esiti. I segmenti IA vengono
  -- intercalati con i tentativi testuali della ricevuta meccanica server.
  FOR part IN SELECT value FROM jsonb_array_elements(p_result->'segments') LOOP
    IF part->>'kind'='prose' THEN
      txt:=btrim(part->>'text');
    ELSE
      SELECT receipt->>'attempt_text' INTO STRICT txt
        FROM jsonb_array_elements(offense_receipts->'slots') receipt
        WHERE receipt->>'slot_id'=part->>'slot_id'
          AND receipt->>'actor_key'=part->>'actor_key';
      IF nullif(btrim(txt),'') IS NULL OR length(txt)>320
      THEN RAISE EXCEPTION 'MRS_V4_NATIVE_ATTEMPT_TEXT'; END IF;
    END IF;
    body:=body||CASE WHEN body='' THEN '' ELSE ' ' END||txt;
  END LOOP;
  IF length(body) NOT BETWEEN 500 AND 5000 OR body IS DISTINCT FROM btrim(body)
  THEN RAISE EXCEPTION 'MRS_V4_BODY_LENGTH'; END IF;
  PERFORM mission_generic_owner.assert_no_literal_reuse(ww.master_session_id,body);
  body_sha:=encode(extensions.digest(convert_to(body,'UTF8'),'sha256'),'hex');
  chain:=encode(extensions.digest(convert_to(anchor->>'chain_sha256'||':'||body_sha,'UTF8'),'sha256'),'hex');
  memory:=memory||jsonb_build_object('schema_version','mission-continuity/1',
    'work_id',ww.id,'covered_count',(anchor->>'count')::bigint+1,
    'chain_sha256',chain,'text_sha256',body_sha);

  -- Publication follows route in this SAME transaction. Do not call the
  -- legacy publisher: it re-runs work_assert against the advanced route.
  INSERT INTO public.messages(location_id,character_id,author_name,body,kind,
    sender_user,recipient_user)
    VALUES(mm.location_id,NULL,'Fato',body,'fato',NULL,NULL)
    RETURNING id INTO msg;
  IF msg IS NULL THEN RAISE EXCEPTION 'MRS_V4_FATO_MISSING'; END IF;
  IF slot_count>0 THEN
    sealed_receipts:=mission_generic_owner.seal_deferred_png_v4(ub.id,msg);
    IF jsonb_array_length(sealed_receipts)<>slot_count
    THEN RAISE EXCEPTION 'MRS_V4_SEAL_RECEIPT_COUNT'; END IF;
  END IF;
  UPDATE mission_generic_owner.unified_round_windows SET publication_id=msg
    WHERE batch_id=ub.id AND publication_id IS NULL;
  IF slot_count>0 AND NOT FOUND THEN RAISE EXCEPTION 'MRS_V4_ROUND_WINDOW_SEAL'; END IF;
  IF route_result IS NOT NULL THEN
    SELECT * INTO STRICT tr FROM mission_generic_owner.trigger_receipts
      WHERE id=(route_result->>'authority_receipt_id')::uuid
        AND master_session_id=ub.master_session_id;
    SELECT * INTO STRICT ev FROM public.mission_run_events
      WHERE id=(tr.result->>'event_id')::uuid AND status='committed';
    SELECT * INTO STRICT ob FROM public.mission_run_outbox
      WHERE event_id=ev.id AND state='pending' FOR UPDATE;
    IF ob.master_session_id<>ub.master_session_id
      OR ob.context_fingerprint<>ev.context_fingerprint
      OR ob.step_key<>ev.step_after
      OR ob.event_version_after<>ev.version_after
    THEN RAISE EXCEPTION 'MRS_V4_OUTBOX_DRIFT'; END IF;
    pub:=gen_random_uuid();
    INSERT INTO public.mission_run_publications
      (id,master_session_id,event_id,request_key_sha256,request_fingerprint,
       source,expected_run_control_version,expected_event_version_after,
       expected_step_key,context_fingerprint,body_sha256,status)
    VALUES(pub,ub.master_session_id,ev.id,
      mission_internal.request_key_sha256(p_request),
      mission_internal.fingerprint(jsonb_build_object('batch',ub.id,'work',ww.id,
        'payload',ww.payload_sha256,'body',body_sha)),
      'model',ev.version_after,ev.version_after,ev.step_after,
      ev.context_fingerprint,body_sha,'committed');
    INSERT INTO public.mission_run_messages(publication_id,message_id,body_sha256)
      VALUES(pub,msg,body_sha);
    PERFORM set_config('app.mission_outbox_publish','on',true);
    UPDATE public.mission_run_outbox SET state='published',publication_id=pub,
      published_at=clock_timestamp() WHERE event_id=ev.id;
    PERFORM set_config('app.mission_outbox_publish','off',true);
  END IF;
  PERFORM mission_generic_owner.staff_fato_regen_publish(p_work,msg);
  UPDATE mission_generic_owner.unified_batches SET state='published',message_id=msg,
    published_at=clock_timestamp() WHERE id=ub.id;
  UPDATE mission_generic_owner.unified_source_windows SET consumed_message_id=msg
    WHERE id=ub.source_window_id;
  UPDATE mission_generic_owner.role_window_cursors SET
    window_epoch=window_epoch+1,role_revision=0,
    last_published_fato_id=msg,updated_at=clock_timestamp()
    WHERE master_session_id=ww.master_session_id
      AND mission_generic_owner.role_source_revision_v1(master_session_id)=
        ww.payload->>'source_revision';
  IF NOT FOUND THEN RAISE EXCEPTION 'MRS_V4_CURSOR_ADVANCE_DRIFT'; END IF;
  INSERT INTO mission_generic_owner.unified_segment_publications_v4
    (work_id,batch_id,message_id,raw_result_sha256,segments_sha256,
      final_text_sha256,source_revision,native_receipts)
  VALUES(ww.id,ub.id,msg,p_raw_sha,seg_sha,body_sha,
    ww.payload->>'source_revision',coalesce(sealed_receipts,'[]'::jsonb));
  IF route_result IS NOT NULL THEN PERFORM mission_factory_owner.c485_after_publication_v1(ub.master_session_id,(route_result->>'event_id')::uuid,msg,ub.id);END IF;
  IF literal_recovery THEN
    -- The original provider result and failure remain immutable evidence.
    INSERT INTO mission_narrative_internal.dispatch_audit(receipt_id,event_code,details)
    VALUES(ww.dispatch_receipt_id,'staff_literal_recovery_completed',jsonb_build_object(
      'schema_version','c1266-literal-recovery/1','work_id',ww.id,'master_session_id',ww.master_session_id,
      'request_key',ww.request_key,'batch_id',ub.id,'message_id',msg,
      'original_state',ww.state,'original_finalized_at',ww.finalized_at,
      'original_result',ww.result,'original_result_sha256',ww.result_sha256,
      'original_result_jsonb_sha256',public.combat_v2_sha256(ww.result),
      'application_error_code','MG_FATO_LITERAL_REPETITION',
      'provider_calls_added',0,'segments_sha256',seg_sha,'final_text_sha256',body_sha));
    UPDATE mission_generic_owner.work_items SET state='completed',message_id=msg,
      result=ww.result||jsonb_build_object('text',body,'continuity',memory),
      result_sha256=public.combat_v2_sha256(ww.result||jsonb_build_object('text',body,'continuity',memory))
      WHERE id=ww.id AND state='failed' AND message_id IS NULL
        AND result IS NOT DISTINCT FROM ww.result AND result_sha256=ww.result_sha256
        AND finalized_at IS NOT DISTINCT FROM ww.finalized_at;
    IF NOT FOUND THEN RAISE EXCEPTION 'C1266_LITERAL_RECOVERY_CAS' USING ERRCODE='40001'; END IF;
  END IF;
  RETURN jsonb_build_object('batch_id',ub.id,'message_id',msg,
    'publication_id',pub,'transition',route_result,'combat_open',combat_open,
    'offense_receipts',coalesce(sealed_receipts,'[]'::jsonb),'text',body,
    'continuity',memory);
END;
$function$

CREATE OR REPLACE FUNCTION public.mission_generic_staff_tick_v1(p_session uuid, p_user uuid, p_source_revision text, p_staff uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tick mission_generic_owner.staff_progress_ticks_v1;
        m public.master_v2_sessions; r public.mission_run_state;
        diag jsonb; pending jsonb; result jsonb; new_key uuid;
        terminal boolean;
BEGIN
  PERFORM mission_ai_board_owner.service_only();
  IF p_session IS NULL OR p_user IS NULL OR p_staff IS NULL
    OR p_source_revision IS NULL OR p_source_revision !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'MGS_TICK_ARGUMENTS' USING ERRCODE='22023'; END IF;
  -- L'Edge deve verificare la sessione utente; il DB ricontrolla ruolo Staff.
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=p_staff AND p.role IN ('admin','master'))
  THEN RAISE EXCEPTION 'MGS_TICK_STAFF_REQUIRED' USING ERRCODE='42501'; END IF;
  -- Il capture del submit e il tick serializzano sullo stesso cursore prima
  -- che la role sia acquisita/pubblicata. Master non va bloccato prima.
  PERFORM 1 FROM mission_generic_owner.role_window_cursors c
    WHERE c.master_session_id=p_session FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MGS_TICK_CURSOR_REQUIRED' USING ERRCODE='55000'; END IF;
  PERFORM public.master_v2_lock_scope(p_session);
  SELECT s.* INTO STRICT m FROM public.master_v2_sessions s WHERE s.id=p_session FOR UPDATE;
  SELECT s.* INTO STRICT r FROM public.mission_run_state s WHERE s.master_session_id=p_session FOR UPDATE;
  IF NOT EXISTS (SELECT 1 FROM mission_generic_owner.flow_staff_sessions f
    JOIN public.locations l ON l.id=m.location_id
    WHERE f.master_session_id=p_session AND f.enabled AND l.is_test)
    OR m.owner_kind<>'ai_service' OR m.closed_at IS NOT NULL
    OR m.stato<>'in_corso' OR m.suspended_at IS NOT NULL OR r.run_phase<>'in_corso'
    OR NOT mission_generic_owner.flow_scope_enabled(p_session)
  THEN RAISE EXCEPTION 'MGS_TICK_SCOPE' USING ERRCODE='42501'; END IF;
  PERFORM mission_generic_owner.dispatch_user(p_session,p_user);
  -- Anche il replay deve appartenere alla revisione ancora corrente: un nuovo
  -- Fato o una nuova role non possono riesporre un vecchio dispatch.
  diag:=mission_generic_owner.role_flow_status_v1(p_session,p_user);
  IF diag->>'source_revision' IS DISTINCT FROM p_source_revision
    OR mission_generic_owner.role_source_revision_v1(p_session) IS DISTINCT FROM p_source_revision
  THEN RAISE EXCEPTION 'MGS_TICK_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;
  SELECT * INTO tick FROM mission_generic_owner.staff_progress_ticks_v1
    WHERE master_session_id=p_session AND source_revision=p_source_revision FOR UPDATE;
  IF tick.request_key IS NOT NULL THEN
    IF tick.actor_user_id<>p_user THEN RAISE EXCEPTION 'MGS_TICK_ACTOR_CONFLICT' USING ERRCODE='40001'; END IF;
    SELECT pr.result INTO STRICT result FROM mission_generic_owner.progress_receipts pr
      WHERE pr.request_key=tick.request_key AND pr.master_session_id=p_session
        AND pr.actor_user_id=p_user AND pr.result_sha256=tick.result_sha256
        AND pr.result_sha256=public.combat_v2_sha256(pr.result);
    -- Immutable no-dispatch progress may acquire one server-owned successor receipt.
    IF (mission_factory_owner.keys_exact_v2(result,ARRAY['schema_version','master_session_id','state','dispatch'])
 AND result->>'schema_version'='mission-generic-progress/1' AND result->>'master_session_id'=p_session::text
 AND result->>'state'='needs_attention' AND result->'dispatch'='null'::jsonb
 AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items healed 
 WHERE healed.master_session_id=p_session AND healed.created_at<tick.created_at AND (healed.kind='director' AND healed.state='failed' AND healed.result->>'ok'='true'
 AND healed.payload_sha256=public.combat_v2_sha256(healed.payload)
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts healed_dr
  JOIN mission_narrative_internal.dispatch_audit healed_a ON healed_a.receipt_id=healed_dr.id AND healed_a.event_code='c1266_saved_director_applied'
  JOIN mission_narrative_internal.dispatch_audit healed_f ON healed_f.receipt_id=healed_dr.id AND healed_f.event_code='generic_finalized'
  JOIN mission_generic_owner.unified_batches healed_b ON healed_b.decision_work_id=healed.id AND healed_b.master_session_id=p_session
  JOIN mission_generic_owner.unified_source_windows healed_s ON healed_s.id=healed_b.source_window_id AND healed_s.work_id=healed.id AND healed_s.master_session_id=p_session
  JOIN mission_generic_owner.work_items healed_writer ON healed_writer.id=healed_b.writer_work_id AND healed_writer.master_session_id=p_session AND healed_writer.authority_receipt_id=healed_b.id
  JOIN public.messages healed_msg ON healed_msg.id=healed_writer.message_id AND healed_msg.kind='fato' AND healed_msg.recipient_user IS NULL AND healed_msg.body=healed_writer.result->>'text'
  WHERE healed_dr.id=healed.dispatch_receipt_id AND healed_dr.master_session_id=p_session AND healed_dr.authority_receipt_id=healed.id AND healed_dr.request_key=healed.request_key
   AND healed_dr.status='success' AND healed_dr.dispatch_count=1 AND healed_dr.finalized_at IS NOT NULL
   AND healed_a.details->>'schema_version'='c1266-saved-director-application/1' AND healed_a.details->>'master_session_id'=p_session::text
   AND healed_a.details->>'work_id'=healed.id::text AND healed_a.details->>'result_sha256'=healed.result_sha256
   AND healed_a.details->>'batch_id'=healed_b.id::text AND healed_a.details->>'writer_work_id'=healed_writer.id::text
   AND healed_a.details->>'generation_http_calls'='0' AND healed_a.details->>'failed_work_preserved'='true'
   AND healed_f.details->>'work_id'=healed.id::text AND healed_f.details->>'receipt_id'=healed.receipt_id::text
   AND healed_f.details->>'result_sha256'=healed.result_sha256 AND healed_f.details->>'result_jsonb_sha256'=public.combat_v2_sha256(healed.result)
   AND healed_b.state='published' AND healed_b.published_at IS NOT NULL AND healed_b.message_id=healed_writer.message_id
   AND healed_s.consumed_message_id=healed_b.message_id AND healed_s.superseded_at IS NULL
   AND healed_s.source_sha256=healed.payload_sha256 AND healed_writer.kind='narration' AND healed_writer.state='completed'
   AND healed_writer.payload=healed_b.payload AND healed_writer.payload_sha256=healed_b.payload_sha256
   AND healed_writer.payload_sha256=public.combat_v2_sha256(healed_writer.payload)
   AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 healed_pub WHERE healed_pub.work_id=healed_writer.id AND healed_pub.message_id=healed_msg.id)
   AND EXISTS(SELECT 1 FROM staff_ai_quota_private.calls healed_q WHERE healed_q.producer='mission_generic_ai' AND healed_q.scope_id=p_session AND healed_q.source_id=healed_dr.id AND healed_q.call_no=1 AND healed_q.state='settled' AND healed_q.charged_usd=healed_dr.charged_cost_usd)))) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items unresolved WHERE unresolved.master_session_id=p_session AND unresolved.step_key=r.current_step_key AND unresolved.run_control_version=r.control_version AND unresolved.state='failed' AND NOT (unresolved.kind='director' AND unresolved.state='failed' AND unresolved.result->>'ok'='true'
 AND unresolved.payload_sha256=public.combat_v2_sha256(unresolved.payload)
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts healed_dr
  JOIN mission_narrative_internal.dispatch_audit healed_a ON healed_a.receipt_id=healed_dr.id AND healed_a.event_code='c1266_saved_director_applied'
  JOIN mission_narrative_internal.dispatch_audit healed_f ON healed_f.receipt_id=healed_dr.id AND healed_f.event_code='generic_finalized'
  JOIN mission_generic_owner.unified_batches healed_b ON healed_b.decision_work_id=unresolved.id AND healed_b.master_session_id=p_session
  JOIN mission_generic_owner.unified_source_windows healed_s ON healed_s.id=healed_b.source_window_id AND healed_s.work_id=unresolved.id AND healed_s.master_session_id=p_session
  JOIN mission_generic_owner.work_items healed_writer ON healed_writer.id=healed_b.writer_work_id AND healed_writer.master_session_id=p_session AND healed_writer.authority_receipt_id=healed_b.id
  JOIN public.messages healed_msg ON healed_msg.id=healed_writer.message_id AND healed_msg.kind='fato' AND healed_msg.recipient_user IS NULL AND healed_msg.body=healed_writer.result->>'text'
  WHERE healed_dr.id=unresolved.dispatch_receipt_id AND healed_dr.master_session_id=p_session AND healed_dr.authority_receipt_id=unresolved.id AND healed_dr.request_key=unresolved.request_key
   AND healed_dr.status='success' AND healed_dr.dispatch_count=1 AND healed_dr.finalized_at IS NOT NULL
   AND healed_a.details->>'schema_version'='c1266-saved-director-application/1' AND healed_a.details->>'master_session_id'=p_session::text
   AND healed_a.details->>'work_id'=unresolved.id::text AND healed_a.details->>'result_sha256'=unresolved.result_sha256
   AND healed_a.details->>'batch_id'=healed_b.id::text AND healed_a.details->>'writer_work_id'=healed_writer.id::text
   AND healed_a.details->>'generation_http_calls'='0' AND healed_a.details->>'failed_work_preserved'='true'
   AND healed_f.details->>'work_id'=unresolved.id::text AND healed_f.details->>'receipt_id'=unresolved.receipt_id::text
   AND healed_f.details->>'result_sha256'=unresolved.result_sha256 AND healed_f.details->>'result_jsonb_sha256'=public.combat_v2_sha256(unresolved.result)
   AND healed_b.state='published' AND healed_b.published_at IS NOT NULL AND healed_b.message_id=healed_writer.message_id
   AND healed_s.consumed_message_id=healed_b.message_id AND healed_s.superseded_at IS NULL
   AND healed_s.source_sha256=unresolved.payload_sha256 AND healed_writer.kind='narration' AND healed_writer.state='completed'
   AND healed_writer.payload=healed_b.payload AND healed_writer.payload_sha256=healed_b.payload_sha256
   AND healed_writer.payload_sha256=public.combat_v2_sha256(healed_writer.payload)
   AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 healed_pub WHERE healed_pub.work_id=healed_writer.id AND healed_pub.message_id=healed_msg.id)
   AND EXISTS(SELECT 1 FROM staff_ai_quota_private.calls healed_q WHERE healed_q.producer='mission_generic_ai' AND healed_q.scope_id=p_session AND healed_q.source_id=healed_dr.id AND healed_q.call_no=1 AND healed_q.state='settled' AND healed_q.charged_usd=healed_dr.charged_cost_usd))) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_source_windows released WHERE released.work_id=unresolved.id AND mission_generic_owner.role_source_released_v4(released.id)))) THEN
      new_key:=mission_ai_service_owner.uuid5(tick.request_key,'mission-staff-no-dispatch-resume/1:'||p_source_revision);
      SELECT pr.result INTO result FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=new_key
       AND pr.master_session_id=p_session AND pr.actor_user_id=p_user AND pr.result_sha256=public.combat_v2_sha256(pr.result);
      IF FOUND THEN RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1','state','replayed','source_revision',p_source_revision,'request_key',new_key,'progress',result);END IF;
      IF EXISTS(SELECT 1 FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=new_key) THEN RAISE EXCEPTION 'MGS_NO_WORK_RECEIPT_CONFLICT' USING ERRCODE='40001';END IF;
    ELSE
    -- The first tick is not rewritten. An attested, released Director may
    -- receive one deterministic retry for this very same role revision.
    DECLARE
      failed_work mission_generic_owner.work_items;
      released_source mission_generic_owner.unified_source_windows;
      retry_receipt mission_generic_owner.progress_receipts;
      second_work mission_generic_owner.work_items;
      second_source mission_generic_owner.unified_source_windows;
      second_receipt mission_generic_owner.progress_receipts;
      failed_id uuid;
      second_id uuid;
    BEGIN
      IF (result->'dispatch'->>'event_id') ~
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        failed_id:=(result->'dispatch'->>'event_id')::uuid;
        SELECT * INTO failed_work FROM mission_generic_owner.work_items w
          WHERE w.id=failed_id
            AND w.master_session_id=p_session AND w.kind='director';
        IF failed_work.id IS NOT NULL THEN
          SELECT * INTO released_source FROM mission_generic_owner.unified_source_windows sw
            WHERE sw.id=failed_work.authority_receipt_id
              AND sw.work_id=failed_work.id AND sw.master_session_id=p_session;
        END IF;
      END IF;
      IF failed_work.id IS NOT NULL AND released_source.id IS NOT NULL
        AND failed_work.state='failed' AND failed_work.finalized_at IS NOT NULL
        AND released_source.context->>'source_revision'=p_source_revision
        AND (released_source.superseded_reason='staff_failed_director_validation_retry' OR (released_source.id IN('d460a7be-a3a2-4ad8-9d3b-d2e929f2947e'::uuid,'f4f7185e-4aae-4edd-ac24-65f8dcfa36f5'::uuid) AND released_source.master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND released_source.superseded_reason='staff_preprovider_request_retry'))
        AND released_source.consumed_message_id IS NULL
        AND result->'dispatch'->>'request_key'=failed_work.request_key::text
        AND mission_generic_owner.role_source_released_v4(released_source.id) THEN
        new_key:=mission_ai_service_owner.uuid5(failed_work.id,
          'mission-staff-released-director-retry/1:'||p_source_revision);
        SELECT * INTO retry_receipt FROM mission_generic_owner.progress_receipts pr
          WHERE pr.request_key=new_key;
        IF retry_receipt.request_key IS NOT NULL THEN
          IF retry_receipt.master_session_id<>p_session
            OR retry_receipt.actor_user_id<>p_user
            OR retry_receipt.result_sha256<>public.combat_v2_sha256(retry_receipt.result)
          THEN RAISE EXCEPTION 'MGS_TICK_RETRY_RECEIPT_CONFLICT' USING ERRCODE='40001'; END IF;
          IF (retry_receipt.result#>>'{dispatch,event_id}') ~
             '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            second_id:=(retry_receipt.result#>>'{dispatch,event_id}')::uuid;
            SELECT * INTO second_work FROM mission_generic_owner.work_items w
              WHERE w.id=second_id AND w.master_session_id=p_session AND w.kind='director';
            IF second_work.id IS NOT NULL THEN
              SELECT * INTO second_source FROM mission_generic_owner.unified_source_windows sw
                WHERE sw.id=second_work.authority_receipt_id
                  AND sw.work_id=second_work.id AND sw.master_session_id=p_session;
            END IF;
          END IF;
          IF second_work.id IS NOT NULL AND second_source.id IS NOT NULL
            AND second_work.state='failed' AND second_work.finalized_at IS NOT NULL
            AND second_source.context->>'source_revision'=p_source_revision
            AND second_source.superseded_reason='staff_failed_director_validation_retry'
            AND second_source.consumed_message_id IS NULL
            AND retry_receipt.result#>>'{dispatch,request_key}'=second_work.request_key::text
            AND mission_generic_owner.role_source_released_v4(second_source.id) THEN
            failed_work:=second_work;
            released_source:=second_source;
            new_key:=mission_ai_service_owner.uuid5(second_work.id,
              'mission-staff-db-context-retry/2:'||p_source_revision);
            SELECT * INTO second_receipt FROM mission_generic_owner.progress_receipts pr
              WHERE pr.request_key=new_key;
            IF second_receipt.request_key IS NOT NULL THEN
              IF second_receipt.master_session_id<>p_session
                OR second_receipt.actor_user_id<>p_user
                OR second_receipt.result_sha256<>public.combat_v2_sha256(second_receipt.result)
              THEN RAISE EXCEPTION 'MGS_TICK_SECOND_RECEIPT_CONFLICT' USING ERRCODE='40001'; END IF;
              RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
                'state','replayed','source_revision',p_source_revision,
                'request_key',new_key,'progress',second_receipt.result);
            END IF;
          ELSE
            RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
              'state','replayed','source_revision',p_source_revision,
              'request_key',new_key,'progress',retry_receipt.result);
          END IF;
        END IF;
        IF EXISTS(SELECT 1 FROM mission_generic_owner.work_items newer
          WHERE newer.master_session_id=p_session AND newer.created_at>failed_work.created_at)
        THEN RAISE EXCEPTION 'MGS_TICK_RETRY_NEWER_WORK' USING ERRCODE='40001'; END IF;
      END IF;
    END;
    END IF;
    IF new_key IS NULL THEN
      RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
        'state','replayed','source_revision',p_source_revision,
        'request_key',tick.request_key,'progress',result);
    END IF;
  END IF;
  -- Una revisione nuova non bypassa work/provider incerti della precedente.
  pending:=public.mission_generic_dispatch_next_v1(p_session,p_user);
  IF jsonb_typeof(pending->'request')='object' THEN
    RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
      'state','existing_work','source_revision',p_source_revision,
      'request_key',null,'progress',jsonb_build_object(
        'schema_version','mission-generic-progress/1',
        'master_session_id',p_session,'state','work_pending','dispatch',null));
  END IF;
  IF EXISTS (SELECT 1 FROM mission_generic_owner.work_items w
    WHERE w.master_session_id=p_session AND w.state IN ('ready','claimed','authorized','provider_started'))
    OR EXISTS (SELECT 1 FROM mission_generic_owner.unified_source_windows sw
      WHERE sw.master_session_id=p_session AND sw.consumed_message_id IS NULL AND sw.superseded_at IS NULL)
    OR EXISTS (SELECT 1 FROM public.combat_v2_sessions cs
      WHERE cs.master_session_id=p_session AND cs.closed_at IS NULL)
  THEN RAISE EXCEPTION 'MGS_TICK_ACTIVE_OR_UNCERTAIN_WORK' USING ERRCODE='55000'; END IF;
  SELECT EXISTS (SELECT 1 FROM jsonb_array_elements(
    mission_generic_owner.run_plan_settings(p_session)->'terminal_steps') t
    WHERE t->>'step_key'=r.current_step_key) INTO terminal;
  IF terminal THEN RAISE EXCEPTION 'MGS_TICK_TERMINAL_STEP' USING ERRCODE='55000'; END IF;
  IF diag->>'flow_reason'<>'ready_to_evaluate'
  THEN RAISE EXCEPTION 'MGS_TICK_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;
  new_key:=coalesce(new_key,gen_random_uuid());
  result:=mission_generic_owner.progress_step(p_session,p_user,new_key);
  INSERT INTO mission_generic_owner.progress_receipts
    (request_key,master_session_id,actor_user_id,result,result_sha256)
  VALUES(new_key,p_session,p_user,result,public.combat_v2_sha256(result));
  IF tick.request_key IS NULL THEN
    INSERT INTO mission_generic_owner.staff_progress_ticks_v1
      (master_session_id,source_revision,request_key,actor_user_id,staff_user_id,result_sha256)
    VALUES(p_session,p_source_revision,new_key,p_user,p_staff,public.combat_v2_sha256(result));
  END IF;
  RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
    'state','issued','source_revision',p_source_revision,
    'request_key',new_key,'progress',result);
END;
$function$

CREATE OR REPLACE FUNCTION public.mission_generic_dispatch_finalize_v1(p_work uuid, p_finalize_token text, p_result_text text, p_result_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w mission_generic_owner.work_items;d mission_narrative_internal.dispatch_receipts;z mission_narrative_internal.provider_authorizations;
 pol mission_narrative_internal.runtime_policy;a mission_narrative_internal.dispatch_attempts;
 ok boolean;stale boolean:=false;metrics jsonb;actual numeric;basis text;receipt uuid:=gen_random_uuid();msg uuid;cr jsonb;
 p_result jsonb;tr mission_generic_owner.trigger_receipts;ev public.mission_run_events;ob public.mission_run_outbox;
 publication uuid;bodysha text;bs mission_generic_owner.board_starts;
 application_error text;application_error_code text;outcome_uncertain boolean:=false;stale_role boolean:=false;role_revision text;
 c726_factory_settlement boolean:=false;shared_on boolean;shared_call staff_ai_quota_private.calls%rowtype;
begin
 perform mission_ai_board_owner.service_only();
 if exists(select 1 from mission_generic_owner.role_window_cursors c
   where c.master_session_id=(select master_session_id from mission_generic_owner.work_items where id=p_work)) then
   perform 1 from mission_generic_owner.role_window_cursors c
     where c.master_session_id=(select master_session_id from mission_generic_owner.work_items where id=p_work)
     for update;
   role_revision:=mission_generic_owner.role_source_revision_v1(
     (select master_session_id from mission_generic_owner.work_items where id=p_work));
 end if;
 perform 1 from public.locations where id=(select q.location_id from mission_factory_owner.quest_run_sources q join mission_generic_owner.work_items wi_lock on wi_lock.master_session_id=q.session_id where wi_lock.id=p_work) for update;
 perform 1 from public.master_v2_sessions where id=(select master_session_id from mission_generic_owner.work_items where id=p_work) for update;
 if p_result_text is null or octet_length(p_result_text)>65536
 or encode(extensions.digest(convert_to(p_result_text,'UTF8'),'sha256'),'hex') is distinct from p_result_sha
 then raise exception 'MGD_RESULT_HASH';end if;
 p_result:=p_result_text::jsonb;
 select * into strict w from mission_generic_owner.work_items where id=p_work for update;
 if w.state in('completed','failed','uncertain') then
  if w.state='completed'
    and w.kind='narration'
    and w.payload->>'schema_version'='mission-generic-narration/4' then
    if not exists(select 1 from mission_generic_owner.unified_segment_publications_v4 pub
      where pub.work_id=w.id and pub.raw_result_sha256=p_result_sha)
    then raise exception 'MGD_FINALIZE_CONFLICT' using errcode='40001';end if;
  elsif w.result_sha256 is distinct from p_result_sha then
    raise exception 'MGD_FINALIZE_CONFLICT' using errcode='40001';
  end if;
  return mission_generic_owner.work_status(w);
 end if;
 select * into strict d from mission_narrative_internal.dispatch_receipts where id=w.dispatch_receipt_id for update;
 select * into strict z from mission_narrative_internal.provider_authorizations where id=w.authorization_id and receipt_id=d.id for update;
 select * into strict a from mission_narrative_internal.dispatch_attempts where id=z.attempt_id for update;
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton for share;
 if w.state<>'provider_started' or d.status<>'provider_started' or z.finalize_token_sha256 is distinct from mission_narrative_internal.token_sha(p_finalize_token)
 or p_result->>'schema_version' is distinct from (case when w.payload->>'schema_version'='mission-generic-narration/4' then 'mission-generic-result/2' else 'mission-generic-result/1' end) or p_result->>'work_id' is distinct from w.id::text
 or p_result->>'master_session_id' is distinct from w.master_session_id::text or p_result->>'event_id' is distinct from w.event_id::text
 or p_result->>'request_key' is distinct from w.request_key::text or (p_result->>'revision')::bigint is distinct from w.revision
 or p_result->>'authority_receipt_id' is distinct from w.authority_receipt_id::text or p_result->>'definition_sha256' is distinct from w.definition_sha256
 or p_result->>'payload_sha256' is distinct from w.payload_sha256 or p_result->>'kind' is distinct from w.kind
 or p_result->>'authorization_id' is distinct from w.authorization_id::text or p_result->>'dispatch_id' is distinct from w.dispatch_id::text
 or p_result->>'model' is distinct from pol.model or coalesce(p_result_sha,'')!~'^[0-9a-f]{64}$'
 or p_result->>'runtime_version' is distinct from (case when w.payload->>'schema_version'='mission-generic-narration/4' then 'mission-generic-runtime/2' else 'mission-generic-runtime/1' end)
 or p_result->>'provider_calls' not in('0','1')
 or jsonb_typeof(p_result->'outcome_uncertain') is distinct from 'boolean'
 or (p_result->>'outcome_uncertain'='true' and p_result->>'ok' is distinct from 'false')
 or (p_result->>'ok'='true' and p_result->>'provider_calls' is distinct from '1')
 then raise exception 'MGD_FINALIZE_BINDING';end if;
 SELECT EXISTS(SELECT 1 FROM staff_ai_quota_private.calls qc726 JOIN mission_generic_owner.dispatch_admissions da726 ON da726.master_session_id=w.master_session_id JOIN mission_generic_owner.run_bindings rb726 ON rb726.master_session_id=da726.master_session_id WHERE qc726.producer='mission_generic_ai' AND qc726.source_id=d.id AND qc726.call_no=1 AND qc726.scope_id=w.master_session_id AND qc726.state IN('reserved','sent','unknown_billable') AND da726.c7_budget_enforced AND da726.call_limit=14 AND da726.cost_budget_usd=0.3136 AND da726.c8_count_upper_cost_usd=0.0112 AND da726.c8_count_qualification_sha256~'^[a-f0-9]{64}$' AND rb726.snapshot_sha256=mission_internal.fingerprint(rb726.snapshot) AND da726.c7_budget_qualification_sha256=encode(extensions.digest(convert_to(jsonb_build_object('schema_version','c717-native-staff-admission-proof/1','count_contract_sha256','b242ee7fcc6655fa951e8697acfbee4d6ba92b42b177fcbcf6a9b08d004661b2','session_id',w.master_session_id,'binding_sha256',rb726.snapshot_sha256,'count_qualification_sha256',da726.c8_count_qualification_sha256,'generation_limit',14,'http_limit',28,'cost','0.3136')::text,'UTF8'),'sha256'),'hex')) INTO c726_factory_settlement;

 if (d.envelope->'narrative_admission') is distinct from mission_public_owner.work_contract_v1(w.id)
 then raise exception 'NARRATIVE_FINALIZE_ADMISSION_BINDING' using errcode='40001';end if;
 -- The exact canonical string is hashed before JSONB parsing; no JS/JSONB equivalence assumption.
 metrics:=p_result->'usage';
 if jsonb_typeof(metrics) is distinct from 'object' then metrics:='{}';end if;
 if jsonb_typeof(metrics)='object' and mission_generic_owner.keys_valid(metrics,array['input_tokens','output_tokens','reasoning_tokens','total_tokens'])
 and not exists(select 1 from jsonb_each_text(metrics) where value!~'^[0-9]+$')
 and (metrics->>'reasoning_tokens')::numeric<=(metrics->>'output_tokens')::numeric
 and (metrics->>'total_tokens')::numeric=(metrics->>'input_tokens')::numeric+(metrics->>'output_tokens')::numeric then
  actual:=((metrics->>'input_tokens')::numeric*pol.input_usd_million+(metrics->>'output_tokens')::numeric*pol.output_usd_million)/1000000;basis:='exact';
 else actual:=d.upper_bound_cost_usd;basis:='upper_bound';end if;
 if actual>d.upper_bound_cost_usd then stale:=true;end if;

begin perform mission_generic_owner.work_assert(w); exception when others then stale:=true;end;
if role_revision is not null then
  if w.kind='director'
     and w.payload#>>'{context,source_revision}' is distinct from role_revision then
    stale_role:=true;stale:=true;
  elsif w.kind='narration' and w.payload->>'schema_version'='mission-generic-narration/4'
     and w.payload->>'source_revision' is distinct from role_revision then
    stale_role:=true;stale:=true;
  end if;
end if;

 outcome_uncertain:=(p_result->>'outcome_uncertain')::boolean;
 ok:=coalesce((p_result->>'ok')::boolean,false) and not outcome_uncertain and not stale and w.lease_expires_at>clock_timestamp();
 -- Result application is a subtransaction: failures roll back every domain write,
 -- while the outer transaction still records the provider receipt and real cost.
 begin
 if ok and w.kind='narration' and mission_generic_owner.flow_scope_enabled(w.master_session_id)
    and w.payload->>'schema_version' is distinct from 'mission-generic-narration/4' then
  if jsonb_typeof(p_result->'text') is distinct from 'string' then raise exception 'MGD_NARRATIVE_TEXT_SHAPE';end if;
  perform mission_generic_owner.assert_no_literal_reuse(w.master_session_id,p_result->>'text');
 end if;
 if ok and w.kind='director' then
  if p_result->'command' is distinct from 'null'::jsonb or p_result->'text' is distinct from 'null'::jsonb
  then raise exception 'MUF_DIRECTOR_RESULT_SHAPE';end if;
  cr:=mission_generic_owner.unified_director_commit(w.id,p_result->'decision');
 elsif ok and w.kind='narration' and w.payload->>'mode'='unified' then
  if w.payload->>'schema_version'='mission-generic-narration/4' then
    cr:=mission_generic_owner.unified_publish_v4(w.id,p_result,w.request_key,p_result_sha);
    msg:=(cr->>'message_id')::uuid;
    p_result:=p_result||jsonb_build_object('text',cr->>'text','continuity',cr->'continuity');
  else
    if jsonb_typeof(p_result->'text') is distinct from 'string' then raise exception 'MUF_WRITER_RESULT_SHAPE';end if;
    cr:=mission_generic_owner.unified_publish(w.id,p_result->>'text',w.request_key);msg:=(cr->>'message_id')::uuid;
  end if;
 elsif ok and w.kind='choice' then
  if p_result ? 'peaceful_exit' then
   if not mission_generic_owner.keys_valid(p_result->'peaceful_exit',
      array['schema_version','intent','pg_declaration_ids','agreement_summary'])
    or p_result#>>'{peaceful_exit,schema_version}' is distinct from 'mission-peaceful-proposal/1'
    or p_result#>>'{peaceful_exit,intent}' not in ('none','accept')
    or jsonb_typeof(p_result#>'{peaceful_exit,pg_declaration_ids}') is distinct from 'array'
    or jsonb_typeof(p_result#>'{peaceful_exit,agreement_summary}') is distinct from 'string'
    or (p_result#>>'{peaceful_exit,intent}'='none' and
      (jsonb_array_length(p_result#>'{peaceful_exit,pg_declaration_ids}')<>0
       or p_result#>>'{peaceful_exit,agreement_summary}'<>''))
    or (p_result#>>'{peaceful_exit,intent}'='accept' and
      (jsonb_array_length(p_result#>'{peaceful_exit,pg_declaration_ids}')=0
       or length(btrim(p_result#>>'{peaceful_exit,agreement_summary}')) not between 8 and 500))
   then raise exception 'MUP_CHOICE_PEACEFUL_SHAPE';end if;
  end if;
  if d.envelope#>>'{narrative_admission,schema_version}' IN('mission-narrative-admission/2','mission-narrative-admission/3') then
   cr:=mission_public_owner.choice_commit_v2(w.id,(w.payload->>'capability_id')::uuid,p_result->'command',p_result->'peaceful_exit');
  else
   cr:=mission_generic_owner.choice_commit(w.id,(w.payload->>'capability_id')::uuid,p_result->'command');
  end if;
  if cr is null or not exists(select 1 from mission_generic_owner.panel_choices pc
   join combat_panel_private.request_receipts rr on rr.principal_user=pc.principal_id and rr.request_key=pc.request_key
   where pc.work_id=w.id and pc.id=(w.payload->>'capability_id')::uuid and pc.consumed_at is not null
    and pc.result=cr and rr.viewer_envelope=cr and rr.event_id is not null
    and rr.offer_id=(p_result#>>'{command,offer_id}')::uuid
    and pc.command_sha256=public.combat_v2_sha256(combat_panel_private.validate_command(p_result->'command')))
  then raise exception 'MGD_COMMAND_RECEIPT_MISSING';end if;
 elsif ok then
  if w.payload#>>'{barrier,closed}' is distinct from 'true'
   or exists(select 1 from jsonb_array_elements_text(w.payload#>'{barrier,required_receipt_ids}') id
    where not(w.payload#>'{barrier,receipt_ids}' ? id))
   or jsonb_typeof(p_result->'text') is distinct from 'string' or length(btrim(p_result->>'text')) not between 1 and 5000
  then raise exception 'MGD_NARRATIVE_BARRIER';end if;
  if w.payload->>'source_kind'='quest' and w.payload#>>'{quest_lifecycle,phase}' in('opening','terminal') then
   cr:=mission_factory_owner.quest_work_publish_v1(w.id,p_result->>'text');
   msg:=(cr->>'message_id')::uuid;
   if msg is null then raise exception 'MF_QUEST_PUBLICATION_MESSAGE_MISSING';end if;
  elsif w.payload->>'mode'='combat' then
   cr:=mission_generic_owner.combat_publish(w.id,p_result->>'text',w.request_key);
   msg:=(cr->>'message_id')::uuid;
   if msg is null or not exists(select 1 from public.messages m join public.master_v2_sessions s on s.location_id=m.location_id
    where s.id=w.master_session_id and m.id=msg) then raise exception 'MGD_COMBAT_PUBLICATION_MISSING';end if;
  elsif w.payload->>'mode'='mission' then
   insert into public.messages(location_id,character_id,author_name,body,kind,sender_user,recipient_user,created_at)
   select location_id,null,'Fato',p_result->>'text','fato',null,null,clock_timestamp() from public.master_v2_sessions where id=w.master_session_id returning id into msg;
   if w.payload ? 'opening_start_receipt_id' then
    select * into strict bs from mission_generic_owner.board_starts where id=w.authority_receipt_id and master_session_id=w.master_session_id for update;
    select * into strict ev from public.mission_run_events where id=bs.event_id and master_session_id=w.master_session_id for update;
   else
    select * into strict tr from mission_generic_owner.trigger_receipts where id=w.authority_receipt_id and master_session_id=w.master_session_id;
    select * into strict ev from public.mission_run_events where id=(tr.result->>'event_id')::uuid and master_session_id=w.master_session_id for update;
   end if;
   select * into strict ob from public.mission_run_outbox where event_id=ev.id and master_session_id=w.master_session_id for update;
   if ev.status<>'committed' or ob.state<>'pending' or ev.version_after<>w.run_control_version
    or ob.event_version_after<>ev.version_after or ev.step_after<>w.step_key or ob.step_key<>w.step_key
    or ob.context_fingerprint<>ev.context_fingerprint then raise exception 'MGD_OUTBOX_STALE';end if;
   bodysha:=encode(extensions.digest(convert_to(p_result->>'text','UTF8'),'sha256'),'hex');
   publication:=gen_random_uuid();
   insert into public.mission_run_publications(id,master_session_id,event_id,request_key_sha256,request_fingerprint,source,
    expected_run_control_version,expected_event_version_after,expected_step_key,context_fingerprint,body_sha256,status)
   values(publication,w.master_session_id,ev.id,mission_internal.request_key_sha256(w.request_key),
    mission_internal.fingerprint(jsonb_build_object('schema_version','mission-generic-publication/1','work_id',w.id,'event_id',ev.id,
    'payload_sha256',w.payload_sha256,'body_sha256',bodysha)),'model',w.run_control_version,ev.version_after,w.step_key,ev.context_fingerprint,bodysha,'committed');
   insert into public.mission_run_messages(publication_id,message_id,body_sha256) values(publication,msg,bodysha);
   -- Same guarded outbox transition as native publication; no invented reveal grants.
   perform set_config('app.mission_outbox_publish','on',true);
   update public.mission_run_outbox set state='published',publication_id=publication,published_at=clock_timestamp() where event_id=ev.id;
   perform set_config('app.mission_outbox_publish','off',true);
   if w.payload ? 'opening_start_receipt_id' then
    perform mission_generic_owner.opening_published(w.master_session_id,publication);
   end if;
  else raise exception 'MGD_NARRATIVE_MODE';
  end if;
 end if;
 exception when others then
  application_error:=SQLSTATE;
  application_error_code:=case when SQLSTATE='22023' and SQLERRM='MG_FATO_LITERAL_REPETITION' then 'MG_FATO_LITERAL_REPETITION'
   WHEN SQLSTATE IN('P0001','40001','42501') AND SQLERRM IN('C1266_PEER_BATCH_PROVENANCE','C1266_PEER_CONTRACT_BINDING','C1266_PEER_EVIDENCE_BINDING','C1266_PEER_FEATURE_SCOPE','C1266_PEER_INTERPRETATION_VERSION_REQUIRED','C1266_PEER_NULL_REQUIRED','C1266_PEER_ORDER_BINDING','C1266_PEER_ORDER_COVERAGE','C1266_PEER_OWN_MOVEMENT_REQUIRED','C1266_PEER_REFERENCE_BINDING','C1266_PEER_REFERENCE_SHAPE','C1266_PEER_SUBMISSION_ORDER_BINDING','C1266_PEER_TEMPORAL_SHAPE','C1266_PEER4_BATCH_FULL_PROJECTION','C1266_PEER4_EFFECT_INVALID','C1266_PEER4_IMMEDIATE_ANCHOR','C1266_PEER4_IMMEDIATE_LIMIT','C1266_PEER4_IMMEDIATE_SHAPE','C1266_PEER4_PROJECTION_IMMEDIATE','C1266_PEER4_ROLE_BINDING','C1266_PEER4_UNKNOWN_BINDING','C1266_PEER4_UNKNOWN_EVIDENCE','C1266_PEER4_VALID_ROSTER_REQUIRED','C1266_PEER4_WRITER_FULL_PROJECTION')
    AND EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 peer_wc
 JOIN mission_factory_owner.editor_release_readiness peer_rr ON peer_rr.singleton
 WHERE peer_wc.work_id=w.id AND peer_wc.master_session_id=w.master_session_id AND peer_wc.scope='staff_mission'
 AND peer_wc.contract_sha256=public.combat_v2_sha256(peer_wc.contract)
 AND peer_wc.contract->>'schema_version'='mission-narrative-admission/3'
 AND peer_wc.contract->'features' ? 'role_intents_v2'
 AND peer_wc.contract->'features' ? 'execution_authority_v1'
 AND peer_wc.contract#>>'{source_attestation,role_intents,schema_version}'='mission-role-intent-attestation/4'
 AND peer_wc.contract#>>'{source_attestation,role_intents,temporal_contract_sha256}'='0603ab23e76750b5babeb41421bc84b551b959945f21267ffd7169140732f1e8'
 AND peer_wc.contract#>>'{source_attestation,role_intents,peer_confirmation,schema_version}'='mission-peer-confirmation-contract/2'
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,schema_version}'='c1266-work-execution-attestation/1' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND peer_wc.contract#>>'{source_attestation,execution_authority,execution_context}'='staff_mission'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,kind}'='staff_finite'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,resource_scope}'='staff_simulation'
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,source_scope,mission_id}'='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,location_id}'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,release_sha256}'=peer_wc.release_sha256
 AND peer_wc.contract#>>'{source_attestation,execution_authority,binding_sha256}'=peer_wc.definition_sha256
 AND (peer_rr.revision_sha256=peer_wc.release_sha256 OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND ((CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='7ce1a932-d339-5914-93d1-3f4698686c2c' OR (CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='e3579a26-560d-5d1d-bfbd-649df53a73c7' OR (CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='a85c7787-7cd4-4998-9ecc-8086e2c84d7b' OR (CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='b2fc5e28-072b-41f2-8dd8-cb5a35a13092')
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,admission,grant_id}'=peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,grant_id}' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND ((w.kind='director' AND w.payload->>'schema_version'='mission-director-work/4' AND w.payload#>>'{peer_confirmation,schema_version}'='mission-peer-confirmation-contract/2') OR(w.kind='narration' AND w.payload->>'schema_version'='mission-generic-narration/4' AND w.payload->>'mode'='unified' AND w.payload#>>'{role_interpretation,schema_version}'='mission-role-interpretation/4' AND w.payload#>>'{role_disposition,schema_version}'='mission-role-disposition/4'))) THEN SQLERRM
   WHEN SQLSTATE IN('P0001','40001','42501') AND SQLERRM IN('C1266_PEER_BATCH_PROVENANCE','C1266_PEER_CONTRACT_BINDING','C1266_PEER_EVIDENCE_BINDING','C1266_PEER_FEATURE_SCOPE','C1266_PEER_INTERPRETATION_VERSION_REQUIRED','C1266_PEER_NULL_REQUIRED','C1266_PEER_ORDER_BINDING','C1266_PEER_ORDER_COVERAGE','C1266_PEER_OWN_MOVEMENT_REQUIRED','C1266_PEER_REFERENCE_BINDING','C1266_PEER_REFERENCE_SHAPE','C1266_PEER_SUBMISSION_ORDER_BINDING','C1266_PEER_TEMPORAL_SHAPE')
    AND EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 peer_wc
 JOIN mission_factory_owner.editor_release_readiness peer_rr ON peer_rr.singleton
 WHERE peer_wc.work_id=w.id AND peer_wc.master_session_id=w.master_session_id AND peer_wc.scope='staff_mission'
 AND peer_wc.contract_sha256=public.combat_v2_sha256(peer_wc.contract)
 AND peer_wc.contract->>'schema_version'='mission-narrative-admission/3'
 AND peer_wc.contract->'features' ? 'role_intents_v2'
 AND peer_wc.contract->'features' ? 'execution_authority_v1'
 AND peer_wc.contract#>>'{source_attestation,role_intents,schema_version}'='mission-role-intent-attestation/3'
 AND peer_wc.contract#>>'{source_attestation,role_intents,temporal_contract_sha256}'='3fdeaa942bcf3ba217a976f7b0896f4594721fa45cde9ff8ed7bddf15391feda'
 AND peer_wc.contract#>>'{source_attestation,role_intents,peer_confirmation,schema_version}'='mission-peer-confirmation-contract/1'
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,schema_version}'='c1266-work-execution-attestation/1' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND peer_wc.contract#>>'{source_attestation,execution_authority,execution_context}'='staff_mission'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,kind}'='staff_finite'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,resource_scope}'='staff_simulation'
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,source_scope,mission_id}'='5878822d-dc03-4ac2-ad0b-1547f0ab3fc0' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND peer_wc.contract#>>'{source_attestation,execution_authority,admission,location_id}'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'
 AND peer_wc.contract#>>'{source_attestation,execution_authority,release_sha256}'=peer_wc.release_sha256
 AND peer_wc.contract#>>'{source_attestation,execution_authority,binding_sha256}'=peer_wc.definition_sha256
 AND (peer_rr.revision_sha256=peer_wc.release_sha256 OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND ((CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='bedc09e2-559b-586d-a38b-cd600b419cd3' OR (CASE WHEN ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)) THEN mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)#>>'{source_qualification,campaign_id}' ELSE peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,campaign_id}' END)='4c316c8c-3d92-5757-815e-dedcb0ac2f24')
 AND (peer_wc.contract#>>'{source_attestation,execution_authority,admission,grant_id}'=peer_rr.canonical_preimage::jsonb#>>'{config,c1266_staff_campaign,grant_id}' OR ((mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND peer_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(peer_wc.work_id)))
 AND ((w.kind='director' AND w.payload->>'schema_version'='mission-director-work/4' AND w.payload#>>'{peer_confirmation,schema_version}'='mission-peer-confirmation-contract/1') OR(w.kind='narration' AND w.payload->>'schema_version'='mission-generic-narration/4' AND w.payload->>'mode'='unified' AND w.payload#>>'{role_interpretation,schema_version}'='mission-role-interpretation/3' AND w.payload#>>'{role_disposition,schema_version}'='mission-role-disposition/3'))) THEN SQLERRM
   else null end;
  ok:=false;msg:=null;cr:=null;publication:=null;
 end;
 if mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR c726_factory_settlement OR mission_generic_owner.c758_admission_proof_v1(w.master_session_id) then
   select enabled into strict shared_on from staff_ai_quota_private.runtime where singleton;
   select * into shared_call from staff_ai_quota_private.calls
       where producer='mission_generic_ai' and source_id=d.id and call_no=1
         and scope_id=w.master_session_id for update;
   if shared_call.id is not null then
     if shared_call.state='reserved' and p_result->>'provider_calls'='0' then
       perform staff_ai_quota_private.no_http(shared_call.id);
       actual:=0;basis:='exact';
     elsif shared_call.state='sent' and basis='exact'
       and p_result->>'provider_calls'='1' then
       perform staff_ai_quota_private.settle(shared_call.id,
         (metrics->>'input_tokens')::integer,(metrics->>'output_tokens')::integer);
     elsif shared_call.state in('sent','unknown_billable') then
       perform staff_ai_quota_private.unknown_billable(shared_call.id);
     else
       raise exception 'STAFF_GENERIC_SETTLEMENT_STATE' using errcode='40001';
     end if;
   elsif shared_on then
     raise exception 'STAFF_GENERIC_SETTLEMENT_MISSING' using errcode='40001';
   end if;
 end if;
 update mission_narrative_internal.dispatch_attempts set status=case when basis='exact' then 'success' else 'unknown_billable' end,
  actual_cost_usd=actual,cost_basis=basis,input_tokens=case when basis='exact' then (metrics->>'input_tokens')::int end,
  output_tokens=case when basis='exact' then (metrics->>'output_tokens')::int end,reasoning_tokens=case when basis='exact' then (metrics->>'reasoning_tokens')::int end,
  total_tokens=case when basis='exact' then (metrics->>'total_tokens')::int end,finalized_at=clock_timestamp() where id=a.id;
 update mission_narrative_internal.dispatch_receipts set status=case when basis='exact' then 'success' else 'unknown_billable' end,
  charged_cost_usd=actual,lease_token_sha256=null,lease_expires_at=null,finalized_at=clock_timestamp(),updated_at=clock_timestamp() where id=d.id;
 update mission_narrative_internal.provider_authorizations set finalize_token_sha256=null where id=z.id;
 update mission_generic_owner.work_items set state=case when outcome_uncertain then 'uncertain' when ok then 'completed' else 'failed' end,result=p_result,result_sha256=case
    when ok and msg is not null and w.kind='narration'
      and w.payload->>'schema_version'='mission-generic-narration/4'
    then public.combat_v2_sha256(p_result)
    else p_result_sha end,

  receipt_id=receipt,message_id=msg,finalized_at=clock_timestamp() where id=w.id returning * into w;
 if stale_role then
   if w.kind='director' then
     update mission_generic_owner.unified_source_windows
       set superseded_at=clock_timestamp(),superseded_reason='role_revision_changed'
       where work_id=w.id and consumed_message_id is null and superseded_at is null;
   elsif w.kind='narration' then
     update mission_generic_owner.unified_source_windows uw
       set superseded_at=clock_timestamp(),superseded_reason='role_revision_changed'
       from mission_generic_owner.unified_batches ub
       where ub.id=w.authority_receipt_id and uw.id=ub.source_window_id
         and uw.consumed_message_id is null and uw.superseded_at is null;
   end if;
 end if;

 insert into mission_narrative_internal.dispatch_audit(receipt_id,event_code,details) values(d.id,'generic_finalized',jsonb_build_object(
  'work_id',w.id,'receipt_id',receipt,'message_id',msg,'result_jsonb_sha256',public.combat_v2_sha256(p_result),'result_sha256',p_result_sha,
  'command_receipt',cr,'cost_basis',basis,'stale',stale,'state',w.state,
  'outcome_uncertain',outcome_uncertain,'application_error_sqlstate',application_error,
  'application_error_code',application_error_code));
 return mission_generic_owner.work_status(w);
end;
$function$

CREATE OR REPLACE FUNCTION mission_public_owner.work_contract_issue_v1(p_work uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w mission_generic_owner.work_items;b mission_generic_owner.run_bindings;
 a mission_public_owner.session_admissions_v1;q mission_factory_owner.quest_run_sources;
 pub mission_factory_owner.publications;source_scope text;release_sha text;profile text;
 q49 jsonb;source_attestation jsonb;payload_version text;features jsonb:='[]'::jsonb;doc jsonb;old jsonb;ignored jsonb;c5_proof jsonb;c5_native jsonb;c5_stamp jsonb;
begin
 select * into strict w from mission_generic_owner.work_items where id=p_work for update;
 old:=mission_public_owner.work_contract_v1(w.id);
 if old is not null then return old;end if;
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) THEN
  c5_proof:=mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true);
  c5_native:=mission_generic_owner.c1266_native_start_v1(w.master_session_id,false,true);
  IF c5_proof IS NULL OR c5_native IS NULL THEN RAISE EXCEPTION 'C1266_NARRATIVE5_ISSUE_CLOSED' USING ERRCODE='42501';END IF;
  release_sha:=c5_proof->>'release_sha256';source_scope:=CASE WHEN c5_proof#>>'{admission,resource_scope}'='world' THEN 'public_mission' ELSE 'staff_mission' END;
  c5_stamp:=jsonb_build_object('schema_version','c1266-work-execution-attestation/1','execution_context',c5_proof->>'execution_context',
   'admission',c5_proof->'admission','release_sha256',release_sha,'binding_sha256',c5_proof->>'binding_sha256',
   'financial_qualification_sha256',c5_proof->>'financial_qualification_sha256','c7_budget_qualification_sha256',c5_proof->>'c7_budget_qualification_sha256',
   'start_receipt_id',c5_native->>'start_receipt_id','start_snapshot_sha256',c5_native#>>'{eligibility,board_snapshot_sha256}',
   'source_scope',(SELECT canonical_preimage::jsonb#>'{config,c1266_opening,source_scope}' FROM mission_factory_owner.editor_release_readiness WHERE singleton));
 q49:=mission_generic_owner.c1266_staff_source_scope_v1(w.master_session_id);
 IF q49 IS NOT NULL THEN
 c5_stamp:=c5_stamp||jsonb_build_object('schema_version','c1266-work-execution-attestation/2','source_scope',q49->'source_scope','source_qualification',q49,'source_qualification_sha256',public.combat_v2_sha256(q49));
 END IF;
 q49:=mission_generic_owner.manual_staff_scope_v1(w.master_session_id);
 IF q49 IS NOT NULL THEN
  c5_stamp:=c5_stamp||jsonb_build_object('schema_version','c1266-work-execution-attestation/3','source_scope',q49->'source_scope','source_qualification',q49,'source_qualification_sha256',public.combat_v2_sha256(q49));
 END IF;
 ELSIF mission_generic_owner.c1266_role_scope_v1(w.master_session_id,true) THEN
  ignored:=mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true);
  release_sha:=ignored->>'release_sha256';source_scope:='staff_mission';
 ELSIF exists(select 1 from mission_factory_owner.quest_run_sources qs where qs.session_id=w.master_session_id and qs.availability_scope='public' and qs.state in('prepared','opening_pending','uncertain','started')) then
  ignored:=mission_factory_owner.quest_run_source_assert_v1(w.master_session_id);
  select * into strict q from mission_factory_owner.quest_run_sources where session_id=w.master_session_id;
  release_sha:=q.public_release_sha256;source_scope:='public_quest';
 elsif mission_public_owner.role_session_allowed_v1(w.master_session_id) then
  select * into strict a from mission_public_owner.session_admissions_v1 where master_session_id=w.master_session_id;
  release_sha:=a.release_sha256;source_scope:='public_mission';
 elsif exists(select 1 from mission_launch_owner.dual_decisions d
  join mission_launch_owner.dual_scopes s on s.mission_id=d.mission_id and s.activation_id=d.activation_id
  where d.master_session_id=w.master_session_id) then
  ignored:=mission_public_owner.launch_provenance_v1(w.master_session_id);
  if ignored->>'availability_scope' is distinct from 'staff'
  then raise exception 'NARRATIVE_STAFF_LAUNCH_PROVENANCE' using errcode='42501';end if;
  release_sha:=ignored->>'release_sha256';source_scope:='staff_mission';
 elsif exists(select 1 from mission_factory_owner.quest_run_sources qs
  join public.master_v2_sessions ms on ms.id=qs.session_id
  join public.locations l on l.id=ms.location_id
  where qs.session_id=w.master_session_id and l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   and l.is_active and l.is_test and ms.owner_kind='ai_service' and ms.mission_id is null
   and ms.closed_at is null and ms.suspended_at is null
   and qs.state in('prepared','opening_pending','uncertain','started')) then
  -- Same authoritative Factory assertion, not a second Quest engine.
  ignored:=mission_factory_owner.quest_run_source_assert_v1(w.master_session_id);
  select * into strict q from mission_factory_owner.quest_run_sources where session_id=w.master_session_id;
  select p.* into strict pub from mission_public_owner.publications_v2 p
   join mission_factory_owner.quest_arcs arc on arc.publication_request=p.request_key where arc.id=q.arc_id;
  if pub.target<>'staff' or pub.state<>'staff' or pub.quest_arc_id is distinct from q.arc_id
  then raise exception 'NARRATIVE_QUEST_PUBLICATION_SCOPE' using errcode='42501';end if;
  release_sha:=pub.release_revision_sha256;source_scope:='staff_quest';
 else return null;end if;
 if w.state<>'ready' or w.kind not in('director','narration','choice')
 or w.payload_sha256 is distinct from public.combat_v2_sha256(w.payload)
 then raise exception 'NARRATIVE_WORK_CONTRACT_SOURCE' using errcode='40001';end if;
 select * into strict b from mission_generic_owner.run_bindings where master_session_id=w.master_session_id;
 if b.snapshot_sha256 is distinct from w.definition_sha256
 or b.snapshot_sha256 is distinct from mission_internal.fingerprint(b.snapshot)
 then raise exception 'NARRATIVE_WORK_CONTRACT_BINDING' using errcode='40001';end if;
 payload_version:=w.payload->>'schema_version';
 profile:=case when w.kind in('narration','director') then 'cinematic_master_1' else 'legacy' end;
 if w.kind='director' and (payload_version in('mission-director-work/1','mission-director-work/2','mission-director-work/3') OR(payload_version='mission-director-work/4' AND mission_generic_owner.c1266_role_scope_v2(w.master_session_id,true) AND mission_generic_owner.c1266_role_work_attest_v2(w.id) IS NOT NULL)) then
  if not exists(select 1 from mission_generic_owner.unified_source_windows sw
   where sw.id=w.authority_receipt_id and sw.master_session_id=w.master_session_id
    and sw.work_id=w.id and sw.definition_sha256=w.definition_sha256
    and sw.step_key=w.step_key and sw.run_control_version=w.run_control_version)
  then raise exception 'NARRATIVE_DIRECTOR_SOURCE_RECEIPT' using errcode='40001';end if;
  features:=jsonb_build_array('director_progression','speech_intent');
 elsif w.kind='narration' and payload_version in('mission-generic-narration/3','mission-generic-narration/4') then
  if not exists(select 1 from mission_generic_owner.unified_batches ub
   where ub.id=w.authority_receipt_id and ub.master_session_id=w.master_session_id
    and ub.writer_work_id=w.id and ub.payload_sha256=w.payload_sha256
    and ub.state='ready')
  then raise exception 'NARRATIVE_WRITER_BATCH_RECEIPT' using errcode='40001';end if;
  features:=jsonb_build_array(case payload_version when 'mission-generic-narration/3'
    then 'unified_narration_v3' else 'segmented_narration_v4' end);
 elsif w.kind='narration' and payload_version in('mission-generic-narration/1','mission-generic-narration/2') then
  if jsonb_array_length(coalesce(w.payload->'roleless_declarations','[]'::jsonb))>0 then
   raise exception 'NARRATIVE_ROLELESS_REQUIRES_NATIVE_UNIFIED_ROUTE' using errcode='55000';end if;
 elsif w.kind<>'choice' then
  raise exception 'NARRATIVE_WORK_PROFILE_UNSUPPORTED' using errcode='55000';
 end if;
 source_attestation:=mission_public_owner.narrative_source_attest_v1(w.id)||jsonb_build_object('master_session_id',w.master_session_id,'definition_sha256',w.definition_sha256,'release_sha256',release_sha);
 IF source_attestation#>>'{role_intents,schema_version}' IN('mission-role-intent-attestation/2','mission-role-intent-attestation/3','mission-role-intent-attestation/4') THEN
  IF source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/4' AND(source_scope IS DISTINCT FROM 'staff_mission' OR source_attestation#>>'{role_intents,temporal_contract_sha256}' IS DISTINCT FROM '0603ab23e76750b5babeb41421bc84b551b959945f21267ffd7169140732f1e8' OR source_attestation#>>'{role_intents,peer_confirmation,schema_version}' IS DISTINCT FROM 'mission-peer-confirmation-contract/2') THEN RAISE EXCEPTION 'C1266_PEER_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  IF source_attestation#>>'{role_intents,schema_version}'='mission-role-intent-attestation/3' AND (source_scope IS DISTINCT FROM 'staff_mission' OR source_attestation#>>'{role_intents,temporal_contract_sha256}' IS DISTINCT FROM '3fdeaa942bcf3ba217a976f7b0896f4594721fa45cde9ff8ed7bddf15391feda' OR source_attestation#>>'{role_intents,peer_confirmation,schema_version}' IS DISTINCT FROM 'mission-peer-confirmation-contract/1') THEN RAISE EXCEPTION 'C1266_PEER_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  IF NOT mission_generic_owner.c1266_role_scope_v2(w.master_session_id,true) OR (source_scope IS DISTINCT FROM 'staff_mission' AND c5_proof IS NULL) THEN RAISE EXCEPTION 'C1266_TEMPORAL_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  features:=features||jsonb_build_array('role_intents_v2');
 ELSIF source_attestation->'role_intents' IS NOT NULL THEN
  IF NOT mission_generic_owner.c1266_role_scope_v1(w.master_session_id,true)
   OR (source_scope IS DISTINCT FROM 'staff_mission' AND c5_proof IS NULL)
  THEN RAISE EXCEPTION 'C1266_ROLE_FEATURE_SCOPE' USING ERRCODE='42501';END IF;
  features:=features||jsonb_build_array('role_intents_v1');
 END IF;
 if jsonb_typeof(source_attestation->'peaceful_exit')='object' then features:=features||jsonb_build_array('peaceful_exit_v1');end if;
 if jsonb_array_length(source_attestation->'continuity_sources')>0 then
  features:=features||jsonb_build_array('continuity_sources_v1');
 end if;
 -- peaceful_exit is not inferred from the profile, caller or an arbitrary UUID.
 -- It requires a separate native legal capability; none is minted here.
 IF c5_stamp IS NOT NULL THEN source_attestation:=source_attestation||jsonb_build_object('execution_authority',c5_stamp);features:=features||jsonb_build_array('execution_authority_v1');END IF;
 doc:=jsonb_build_object('schema_version',case when c5_proof IS NOT NULL OR source_scope='public_quest' then 'mission-narrative-admission/3' else 'mission-narrative-admission/2' end,'scope',source_scope,
  'release_sha256',release_sha,'work_id',w.id,'master_session_id',w.master_session_id,
  'definition_sha256',w.definition_sha256,'payload_sha256',w.payload_sha256,
  'payload_schema_version',payload_version,'editorial_profile',profile,'features',features,'source_attestation',source_attestation);
 insert into mission_public_owner.work_contracts_v1(work_id,master_session_id,scope,release_sha256,
 definition_sha256,payload_sha256,contract,contract_sha256)
 values(w.id,w.master_session_id,source_scope,release_sha,w.definition_sha256,w.payload_sha256,doc,public.combat_v2_sha256(doc));
 return doc;
end $function$
